window.KH_SURA(16, {"sura": "النحل", "n": 16, "ayat": {"1": "أَتَى أَمْرُ اللَّهِ فَلَا تَسْتَعْجِلُوهُ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ", "2": "يُنَزِّلُ الْمَلَائِكَةَ بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَنْ يَشَاءُ مِنْ عِبَادِهِ أَنْ أَنْذِرُوا أَنَّهُ لَا إِلَهَ إِلَّا أَنَا فَاتَّقُونِ", "3": "خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ تَعَالَى عَمَّا يُشْرِكُونَ", "4": "خَلَقَ الْإِنْسَانَ مِنْ نُطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُبِينٌ", "5": "وَالْأَنْعَامَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ وَمَنَافِعُ وَمِنْهَا تَأْكُلُونَ", "6": "وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ", "7": "وَتَحْمِلُ أَثْقَالَكُمْ إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الْأَنْفُسِ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَحِيمٌ", "8": "وَالْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً وَيَخْلُقُ مَا لَا تَعْلَمُونَ", "9": "وَعَلَى اللَّهِ قَصْدُ السَّبِيلِ وَمِنْهَا جَائِرٌ وَلَوْ شَاءَ لَهَدَاكُمْ أَجْمَعِينَ", "10": "هُوَ الَّذِي أَنْزَلَ مِنَ السَّمَاءِ مَاءً لَكُمْ مِنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ فِيهِ تُسِيمُونَ", "11": "يُنْبِتُ لَكُمْ بِهِ الزَّرْعَ وَالزَّيْتُونَ وَالنَّخِيلَ وَالْأَعْنَابَ وَمِنْ كُلِّ الثَّمَرَاتِ إِنَّ فِي ذَلِكَ لَآيَةً لِقَوْمٍ يَتَفَكَّرُونَ", "12": "وَسَخَّرَ لَكُمُ اللَّيْلَ وَالنَّهَارَ وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومُ مُسَخَّرَاتٌ بِأَمْرِهِ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَعْقِلُونَ", "13": "وَمَا ذَرَأَ لَكُمْ فِي الْأَرْضِ مُخْتَلِفًا أَلْوَانُهُ إِنَّ فِي ذَلِكَ لَآيَةً لِقَوْمٍ يَذَّكَّرُونَ", "14": "وَهُوَ الَّذِي سَخَّرَ الْبَحْرَ لِتَأْكُلُوا مِنْهُ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُوا مِنْهُ حِلْيَةً تَلْبَسُونَهَا وَتَرَى الْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ وَلَعَلَّكُمْ تَشْكُرُونَ", "15": "وَأَلْقَى فِي الْأَرْضِ رَوَاسِيَ أَنْ تَمِيدَ بِكُمْ وَأَنْهَارًا وَسُبُلًا لَعَلَّكُمْ تَهْتَدُونَ", "16": "وَعَلَامَاتٍ وَبِالنَّجْمِ هُمْ يَهْتَدُونَ", "17": "أَفَمَنْ يَخْلُقُ كَمَنْ لَا يَخْلُقُ أَفَلَا تَذَكَّرُونَ", "18": "وَإِنْ تَعُدُّوا نِعْمَةَ اللَّهِ لَا تُحْصُوهَا إِنَّ اللَّهَ لَغَفُورٌ رَحِيمٌ", "19": "وَاللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ", "20": "وَالَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ لَا يَخْلُقُونَ شَيْئًا وَهُمْ يُخْلَقُونَ", "21": "أَمْوَاتٌ غَيْرُ أَحْيَاءٍ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ", "22": "إِلَهُكُمْ إِلَهٌ وَاحِدٌ فَالَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ قُلُوبُهُمْ مُنْكِرَةٌ وَهُمْ مُسْتَكْبِرُونَ", "23": "لَا جَرَمَ أَنَّ اللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُ لَا يُحِبُّ الْمُسْتَكْبِرِينَ", "24": "وَإِذَا قِيلَ لَهُمْ مَاذَا أَنْزَلَ رَبُّكُمْ قَالُوا أَسَاطِيرُ الْأَوَّلِينَ", "25": "لِيَحْمِلُوا أَوْزَارَهُمْ كَامِلَةً يَوْمَ الْقِيَامَةِ وَمِنْ أَوْزَارِ الَّذِينَ يُضِلُّونَهُمْ بِغَيْرِ عِلْمٍ أَلَا سَاءَ مَا يَزِرُونَ", "26": "قَدْ مَكَرَ الَّذِينَ مِنْ قَبْلِهِمْ فَأَتَى اللَّهُ بُنْيَانَهُمْ مِنَ الْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ السَّقْفُ مِنْ فَوْقِهِمْ وَأَتَاهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ", "27": "ثُمَّ يَوْمَ الْقِيَامَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنْتُمْ تُشَاقُّونَ فِيهِمْ قَالَ الَّذِينَ أُوتُوا الْعِلْمَ إِنَّ الْخِزْيَ الْيَوْمَ وَالسُّوءَ عَلَى الْكَافِرِينَ", "28": "الَّذِينَ تَتَوَفَّاهُمُ الْمَلَائِكَةُ ظَالِمِي أَنْفُسِهِمْ فَأَلْقَوُا السَّلَمَ مَا كُنَّا نَعْمَلُ مِنْ سُوءٍ بَلَى إِنَّ اللَّهَ عَلِيمٌ بِمَا كُنْتُمْ تَعْمَلُونَ", "29": "فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ", "30": "وَقِيلَ لِلَّذِينَ اتَّقَوْا مَاذَا أَنْزَلَ رَبُّكُمْ قَالُوا خَيْرًا لِلَّذِينَ أَحْسَنُوا فِي هَذِهِ الدُّنْيَا حَسَنَةٌ وَلَدَارُ الْآخِرَةِ خَيْرٌ وَلَنِعْمَ دَارُ الْمُتَّقِينَ", "31": "جَنَّاتُ عَدْنٍ يَدْخُلُونَهَا تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ لَهُمْ فِيهَا مَا يَشَاءُونَ كَذَلِكَ يَجْزِي اللَّهُ الْمُتَّقِينَ", "32": "الَّذِينَ تَتَوَفَّاهُمُ الْمَلَائِكَةُ طَيِّبِينَ يَقُولُونَ سَلَامٌ عَلَيْكُمُ ادْخُلُوا الْجَنَّةَ بِمَا كُنْتُمْ تَعْمَلُونَ", "33": "هَلْ يَنْظُرُونَ إِلَّا أَنْ تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ أَمْرُ رَبِّكَ كَذَلِكَ فَعَلَ الَّذِينَ مِنْ قَبْلِهِمْ وَمَا ظَلَمَهُمُ اللَّهُ وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ", "34": "فَأَصَابَهُمْ سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "35": "وَقَالَ الَّذِينَ أَشْرَكُوا لَوْ شَاءَ اللَّهُ مَا عَبَدْنَا مِنْ دُونِهِ مِنْ شَيْءٍ نَحْنُ وَلَا آبَاؤُنَا وَلَا حَرَّمْنَا مِنْ دُونِهِ مِنْ شَيْءٍ كَذَلِكَ فَعَلَ الَّذِينَ مِنْ قَبْلِهِمْ فَهَلْ عَلَى الرُّسُلِ إِلَّا الْبَلَاغُ الْمُبِينُ", "36": "وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ فَمِنْهُمْ مَنْ هَدَى اللَّهُ وَمِنْهُمْ مَنْ حَقَّتْ عَلَيْهِ الضَّلَالَةُ فَسِيرُوا فِي الْأَرْضِ فَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ", "37": "إِنْ تَحْرِصْ عَلَى هُدَاهُمْ فَإِنَّ اللَّهَ لَا يَهْدِي مَنْ يُضِلُّ وَمَا لَهُمْ مِنْ نَاصِرِينَ", "38": "وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَا يَبْعَثُ اللَّهُ مَنْ يَمُوتُ بَلَى وَعْدًا عَلَيْهِ حَقًّا وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ", "39": "لِيُبَيِّنَ لَهُمُ الَّذِي يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ الَّذِينَ كَفَرُوا أَنَّهُمْ كَانُوا كَاذِبِينَ", "40": "إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ", "41": "وَالَّذِينَ هَاجَرُوا فِي اللَّهِ مِنْ بَعْدِ مَا ظُلِمُوا لَنُبَوِّئَنَّهُمْ فِي الدُّنْيَا حَسَنَةً وَلَأَجْرُ الْآخِرَةِ أَكْبَرُ لَوْ كَانُوا يَعْلَمُونَ", "42": "الَّذِينَ صَبَرُوا وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ", "43": "وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ إِلَّا رِجَالًا نُوحِي إِلَيْهِمْ فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ", "44": "بِالْبَيِّنَاتِ وَالزُّبُرِ وَأَنْزَلْنَا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ", "45": "أَفَأَمِنَ الَّذِينَ مَكَرُوا السَّيِّئَاتِ أَنْ يَخْسِفَ اللَّهُ بِهِمُ الْأَرْضَ أَوْ يَأْتِيَهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ", "46": "أَوْ يَأْخُذَهُمْ فِي تَقَلُّبِهِمْ فَمَا هُمْ بِمُعْجِزِينَ", "47": "أَوْ يَأْخُذَهُمْ عَلَى تَخَوُّفٍ فَإِنَّ رَبَّكُمْ لَرَءُوفٌ رَحِيمٌ", "48": "أَوَلَمْ يَرَوْا إِلَى مَا خَلَقَ اللَّهُ مِنْ شَيْءٍ يَتَفَيَّأُ ظِلَالُهُ عَنِ الْيَمِينِ وَالشَّمَائِلِ سُجَّدًا لِلَّهِ وَهُمْ دَاخِرُونَ", "49": "وَلِلَّهِ يَسْجُدُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مِنْ دَابَّةٍ وَالْمَلَائِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ", "50": "يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ", "51": "وَقَالَ اللَّهُ لَا تَتَّخِذُوا إِلَهَيْنِ اثْنَيْنِ إِنَّمَا هُوَ إِلَهٌ وَاحِدٌ فَإِيَّايَ فَارْهَبُونِ", "52": "وَلَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَلَهُ الدِّينُ وَاصِبًا أَفَغَيْرَ اللَّهِ تَتَّقُونَ", "53": "وَمَا بِكُمْ مِنْ نِعْمَةٍ فَمِنَ اللَّهِ ثُمَّ إِذَا مَسَّكُمُ الضُّرُّ فَإِلَيْهِ تَجْأَرُونَ", "54": "ثُمَّ إِذَا كَشَفَ الضُّرَّ عَنْكُمْ إِذَا فَرِيقٌ مِنْكُمْ بِرَبِّهِمْ يُشْرِكُونَ", "55": "لِيَكْفُرُوا بِمَا آتَيْنَاهُمْ فَتَمَتَّعُوا فَسَوْفَ تَعْلَمُونَ", "56": "وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِمَّا رَزَقْنَاهُمْ تَاللَّهِ لَتُسْأَلُنَّ عَمَّا كُنْتُمْ تَفْتَرُونَ", "57": "وَيَجْعَلُونَ لِلَّهِ الْبَنَاتِ سُبْحَانَهُ وَلَهُمْ مَا يَشْتَهُونَ", "58": "وَإِذَا بُشِّرَ أَحَدُهُمْ بِالْأُنْثَى ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ", "59": "يَتَوَارَى مِنَ الْقَوْمِ مِنْ سُوءِ مَا بُشِّرَ بِهِ أَيُمْسِكُهُ عَلَى هُونٍ أَمْ يَدُسُّهُ فِي التُّرَابِ أَلَا سَاءَ مَا يَحْكُمُونَ", "60": "لِلَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ مَثَلُ السَّوْءِ وَلِلَّهِ الْمَثَلُ الْأَعْلَى وَهُوَ الْعَزِيزُ الْحَكِيمُ", "61": "وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِظُلْمِهِمْ مَا تَرَكَ عَلَيْهَا مِنْ دَابَّةٍ وَلَكِنْ يُؤَخِّرُهُمْ إِلَى أَجَلٍ مُسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ", "62": "وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ الْكَذِبَ أَنَّ لَهُمُ الْحُسْنَى لَا جَرَمَ أَنَّ لَهُمُ النَّارَ وَأَنَّهُمْ مُفْرَطُونَ", "63": "تَاللَّهِ لَقَدْ أَرْسَلْنَا إِلَى أُمَمٍ مِنْ قَبْلِكَ فَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ فَهُوَ وَلِيُّهُمُ الْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌ", "64": "وَمَا أَنْزَلْنَا عَلَيْكَ الْكِتَابَ إِلَّا لِتُبَيِّنَ لَهُمُ الَّذِي اخْتَلَفُوا فِيهِ وَهُدًى وَرَحْمَةً لِقَوْمٍ يُؤْمِنُونَ", "65": "وَاللَّهُ أَنْزَلَ مِنَ السَّمَاءِ مَاءً فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا إِنَّ فِي ذَلِكَ لَآيَةً لِقَوْمٍ يَسْمَعُونَ", "66": "وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُسْقِيكُمْ مِمَّا فِي بُطُونِهِ مِنْ بَيْنِ فَرْثٍ وَدَمٍ لَبَنًا خَالِصًا سَائِغًا لِلشَّارِبِينَ", "67": "وَمِنْ ثَمَرَاتِ النَّخِيلِ وَالْأَعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا إِنَّ فِي ذَلِكَ لَآيَةً لِقَوْمٍ يَعْقِلُونَ", "68": "وَأَوْحَى رَبُّكَ إِلَى النَّحْلِ أَنِ اتَّخِذِي مِنَ الْجِبَالِ بُيُوتًا وَمِنَ الشَّجَرِ وَمِمَّا يَعْرِشُونَ", "69": "ثُمَّ كُلِي مِنْ كُلِّ الثَّمَرَاتِ فَاسْلُكِي سُبُلَ رَبِّكِ ذُلُلًا يَخْرُجُ مِنْ بُطُونِهَا شَرَابٌ مُخْتَلِفٌ أَلْوَانُهُ فِيهِ شِفَاءٌ لِلنَّاسِ إِنَّ فِي ذَلِكَ لَآيَةً لِقَوْمٍ يَتَفَكَّرُونَ", "70": "وَاللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّاكُمْ وَمِنْكُمْ مَنْ يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْئًا إِنَّ اللَّهَ عَلِيمٌ قَدِيرٌ", "71": "وَاللَّهُ فَضَّلَ بَعْضَكُمْ عَلَى بَعْضٍ فِي الرِّزْقِ فَمَا الَّذِينَ فُضِّلُوا بِرَادِّي رِزْقِهِمْ عَلَى مَا مَلَكَتْ أَيْمَانُهُمْ فَهُمْ فِيهِ سَوَاءٌ أَفَبِنِعْمَةِ اللَّهِ يَجْحَدُونَ", "72": "وَاللَّهُ جَعَلَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا وَجَعَلَ لَكُمْ مِنْ أَزْوَاجِكُمْ بَنِينَ وَحَفَدَةً وَرَزَقَكُمْ مِنَ الطَّيِّبَاتِ أَفَبِالْبَاطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ اللَّهِ هُمْ يَكْفُرُونَ", "73": "وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًا مِنَ السَّمَاوَاتِ وَالْأَرْضِ شَيْئًا وَلَا يَسْتَطِيعُونَ", "74": "فَلَا تَضْرِبُوا لِلَّهِ الْأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لَا تَعْلَمُونَ", "75": "ضَرَبَ اللَّهُ مَثَلًا عَبْدًا مَمْلُوكًا لَا يَقْدِرُ عَلَى شَيْءٍ وَمَنْ رَزَقْنَاهُ مِنَّا رِزْقًا حَسَنًا فَهُوَ يُنْفِقُ مِنْهُ سِرًّا وَجَهْرًا هَلْ يَسْتَوُونَ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ", "76": "وَضَرَبَ اللَّهُ مَثَلًا رَجُلَيْنِ أَحَدُهُمَا أَبْكَمُ لَا يَقْدِرُ عَلَى شَيْءٍ وَهُوَ كَلٌّ عَلَى مَوْلَاهُ أَيْنَمَا يُوَجِّهْهُ لَا يَأْتِ بِخَيْرٍ هَلْ يَسْتَوِي هُوَ وَمَنْ يَأْمُرُ بِالْعَدْلِ وَهُوَ عَلَى صِرَاطٍ مُسْتَقِيمٍ", "77": "وَلِلَّهِ غَيْبُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا أَمْرُ السَّاعَةِ إِلَّا كَلَمْحِ الْبَصَرِ أَوْ هُوَ أَقْرَبُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "78": "وَاللَّهُ أَخْرَجَكُمْ مِنْ بُطُونِ أُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْئًا وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ لَعَلَّكُمْ تَشْكُرُونَ", "79": "أَلَمْ يَرَوْا إِلَى الطَّيْرِ مُسَخَّرَاتٍ فِي جَوِّ السَّمَاءِ مَا يُمْسِكُهُنَّ إِلَّا اللَّهُ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يُؤْمِنُونَ", "80": "وَاللَّهُ جَعَلَ لَكُمْ مِنْ بُيُوتِكُمْ سَكَنًا وَجَعَلَ لَكُمْ مِنْ جُلُودِ الْأَنْعَامِ بُيُوتًا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَا أَثَاثًا وَمَتَاعًا إِلَى حِينٍ", "81": "وَاللَّهُ جَعَلَ لَكُمْ مِمَّا خَلَقَ ظِلَالًا وَجَعَلَ لَكُمْ مِنَ الْجِبَالِ أَكْنَانًا وَجَعَلَ لَكُمْ سَرَابِيلَ تَقِيكُمُ الْحَرَّ وَسَرَابِيلَ تَقِيكُمْ بَأْسَكُمْ كَذَلِكَ يُتِمُّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ", "82": "فَإِنْ تَوَلَّوْا فَإِنَّمَا عَلَيْكَ الْبَلَاغُ الْمُبِينُ", "83": "يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنْكِرُونَهَا وَأَكْثَرُهُمُ الْكَافِرُونَ", "84": "وَيَوْمَ نَبْعَثُ مِنْ كُلِّ أُمَّةٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا وَلَا هُمْ يُسْتَعْتَبُونَ", "85": "وَإِذَا رَأَى الَّذِينَ ظَلَمُوا الْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنْظَرُونَ", "86": "وَإِذَا رَأَى الَّذِينَ أَشْرَكُوا شُرَكَاءَهُمْ قَالُوا رَبَّنَا هَؤُلَاءِ شُرَكَاؤُنَا الَّذِينَ كُنَّا نَدْعُو مِنْ دُونِكَ فَأَلْقَوْا إِلَيْهِمُ الْقَوْلَ إِنَّكُمْ لَكَاذِبُونَ", "87": "وَأَلْقَوْا إِلَى اللَّهِ يَوْمَئِذٍ السَّلَمَ وَضَلَّ عَنْهُمْ مَا كَانُوا يَفْتَرُونَ", "88": "الَّذِينَ كَفَرُوا وَصَدُّوا عَنْ سَبِيلِ اللَّهِ زِدْنَاهُمْ عَذَابًا فَوْقَ الْعَذَابِ بِمَا كَانُوا يُفْسِدُونَ", "89": "وَيَوْمَ نَبْعَثُ فِي كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِمْ مِنْ أَنْفُسِهِمْ وَجِئْنَا بِكَ شَهِيدًا عَلَى هَؤُلَاءِ وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ", "90": "إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَى وَيَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ", "91": "وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدْتُمْ وَلَا تَنْقُضُوا الْأَيْمَانَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ اللَّهَ عَلَيْكُمْ كَفِيلًا إِنَّ اللَّهَ يَعْلَمُ مَا تَفْعَلُونَ", "92": "وَلَا تَكُونُوا كَالَّتِي نَقَضَتْ غَزْلَهَا مِنْ بَعْدِ قُوَّةٍ أَنْكَاثًا تَتَّخِذُونَ أَيْمَانَكُمْ دَخَلًا بَيْنَكُمْ أَنْ تَكُونَ أُمَّةٌ هِيَ أَرْبَى مِنْ أُمَّةٍ إِنَّمَا يَبْلُوكُمُ اللَّهُ بِهِ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ الْقِيَامَةِ مَا كُنْتُمْ فِيهِ تَخْتَلِفُونَ", "93": "وَلَوْ شَاءَ اللَّهُ لَجَعَلَكُمْ أُمَّةً وَاحِدَةً وَلَكِنْ يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَاءُ وَلَتُسْأَلُنَّ عَمَّا كُنْتُمْ تَعْمَلُونَ", "94": "وَلَا تَتَّخِذُوا أَيْمَانَكُمْ دَخَلًا بَيْنَكُمْ فَتَزِلَّ قَدَمٌ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا السُّوءَ بِمَا صَدَدْتُمْ عَنْ سَبِيلِ اللَّهِ وَلَكُمْ عَذَابٌ عَظِيمٌ", "95": "وَلَا تَشْتَرُوا بِعَهْدِ اللَّهِ ثَمَنًا قَلِيلًا إِنَّمَا عِنْدَ اللَّهِ هُوَ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ", "96": "مَا عِنْدَكُمْ يَنْفَدُ وَمَا عِنْدَ اللَّهِ بَاقٍ وَلَنَجْزِيَنَّ الَّذِينَ صَبَرُوا أَجْرَهُمْ بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ", "97": "مَنْ عَمِلَ صَالِحًا مِنْ ذَكَرٍ أَوْ أُنْثَى وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُ حَيَاةً طَيِّبَةً وَلَنَجْزِيَنَّهُمْ أَجْرَهُمْ بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ", "98": "فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", "99": "إِنَّهُ لَيْسَ لَهُ سُلْطَانٌ عَلَى الَّذِينَ آمَنُوا وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ", "100": "إِنَّمَا سُلْطَانُهُ عَلَى الَّذِينَ يَتَوَلَّوْنَهُ وَالَّذِينَ هُمْ بِهِ مُشْرِكُونَ", "101": "وَإِذَا بَدَّلْنَا آيَةً مَكَانَ آيَةٍ وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوا إِنَّمَا أَنْتَ مُفْتَرٍ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ", "102": "قُلْ نَزَّلَهُ رُوحُ الْقُدُسِ مِنْ رَبِّكَ بِالْحَقِّ لِيُثَبِّتَ الَّذِينَ آمَنُوا وَهُدًى وَبُشْرَى لِلْمُسْلِمِينَ", "103": "وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُ بَشَرٌ لِسَانُ الَّذِي يُلْحِدُونَ إِلَيْهِ أَعْجَمِيٌّ وَهَذَا لِسَانٌ عَرَبِيٌّ مُبِينٌ", "104": "إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِآيَاتِ اللَّهِ لَا يَهْدِيهِمُ اللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ", "105": "إِنَّمَا يَفْتَرِي الْكَذِبَ الَّذِينَ لَا يُؤْمِنُونَ بِآيَاتِ اللَّهِ وَأُولَئِكَ هُمُ الْكَاذِبُونَ", "106": "مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ وَلَكِنْ مَنْ شَرَحَ بِالْكُفْرِ صَدْرًا فَعَلَيْهِمْ غَضَبٌ مِنَ اللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌ", "107": "ذَلِكَ بِأَنَّهُمُ اسْتَحَبُّوا الْحَيَاةَ الدُّنْيَا عَلَى الْآخِرَةِ وَأَنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ", "108": "أُولَئِكَ الَّذِينَ طَبَعَ اللَّهُ عَلَى قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَارِهِمْ وَأُولَئِكَ هُمُ الْغَافِلُونَ", "109": "لَا جَرَمَ أَنَّهُمْ فِي الْآخِرَةِ هُمُ الْخَاسِرُونَ", "110": "ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا مِنْ بَعْدِ مَا فُتِنُوا ثُمَّ جَاهَدُوا وَصَبَرُوا إِنَّ رَبَّكَ مِنْ بَعْدِهَا لَغَفُورٌ رَحِيمٌ", "111": "يَوْمَ تَأْتِي كُلُّ نَفْسٍ تُجَادِلُ عَنْ نَفْسِهَا وَتُوَفَّى كُلُّ نَفْسٍ مَا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ", "112": "وَضَرَبَ اللَّهُ مَثَلًا قَرْيَةً كَانَتْ آمِنَةً مُطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِنْ كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ اللَّهِ فَأَذَاقَهَا اللَّهُ لِبَاسَ الْجُوعِ وَالْخَوْفِ بِمَا كَانُوا يَصْنَعُونَ", "113": "وَلَقَدْ جَاءَهُمْ رَسُولٌ مِنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ الْعَذَابُ وَهُمْ ظَالِمُونَ", "114": "فَكُلُوا مِمَّا رَزَقَكُمُ اللَّهُ حَلَالًا طَيِّبًا وَاشْكُرُوا نِعْمَتَ اللَّهِ إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ", "115": "إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنْزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ", "116": "وَلَا تَقُولُوا لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ هَذَا حَلَالٌ وَهَذَا حَرَامٌ لِتَفْتَرُوا عَلَى اللَّهِ الْكَذِبَ إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ", "117": "مَتَاعٌ قَلِيلٌ وَلَهُمْ عَذَابٌ أَلِيمٌ", "118": "وَعَلَى الَّذِينَ هَادُوا حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِنْ قَبْلُ وَمَا ظَلَمْنَاهُمْ وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ", "119": "ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا السُّوءَ بِجَهَالَةٍ ثُمَّ تَابُوا مِنْ بَعْدِ ذَلِكَ وَأَصْلَحُوا إِنَّ رَبَّكَ مِنْ بَعْدِهَا لَغَفُورٌ رَحِيمٌ", "120": "إِنَّ إِبْرَاهِيمَ كَانَ أُمَّةً قَانِتًا لِلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ الْمُشْرِكِينَ", "121": "شَاكِرًا لِأَنْعُمِهِ اجْتَبَاهُ وَهَدَاهُ إِلَى صِرَاطٍ مُسْتَقِيمٍ", "122": "وَآتَيْنَاهُ فِي الدُّنْيَا حَسَنَةً وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ", "123": "ثُمَّ أَوْحَيْنَا إِلَيْكَ أَنِ اتَّبِعْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ", "124": "إِنَّمَا جُعِلَ السَّبْتُ عَلَى الَّذِينَ اخْتَلَفُوا فِيهِ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ", "125": "ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ", "126": "وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِهِ وَلَئِنْ صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّابِرِينَ", "127": "وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِمَّا يَمْكُرُونَ", "128": "إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا وَالَّذِينَ هُمْ مُحْسِنُونَ"}, "units": [{"aya": 1, "title": "في الأمر الذي أعلم الله عباده مجيئه وقربه منهم ما هو، وأي شيء هو", "tabari": {"page": "14/158", "sarih": 1, "tarjih": "وأولى القولين في ذلك عندى بالصواب قول من قال: هو تهديد من الله أهل الكفر به وبرسوله، وإعلام منه لهم قرب العذاب منهم والهلاك؛ وذلك أنه عقب ذلك بقوله: ﴿سبحانه وتعالى عما يشركون﴾. فدل بذلك على تقريعه المشركين به ، ووعيده لهم. وبعد، فإنه لم يبلغنا أن أحدا من أصحاب رسول الله ﷺ استعجل فرائض قبل أن تفرض عليهم؛ فيقال لهم من أجل ذلك: قد جاءتكم فرائض الله فلا تستعجلوها. وأما مستعجلو العذاب من المشركين، فقد كانوا كثيرا.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "هو فرائضه وأحكامه", "taqdim": 0, "n_athar": 1, "qailun": [["الضحاك", "تابعي"]], "athar": [40763]}, {"n": 2, "t": "بل ذلك وعيد من الله لأهل الشرك به، أخبرهم أن الساعة قد قربت، وأن عذابهم قد حضر أجله، فدنا", "taqdim": 0, "n_athar": 3, "qailun": [["ابن جريج", "تابع التابعين"], ["أبي بكر بن حفص", ""]], "athar": [40758, 40767]}]}, "mawaqif": [{"taliq": 3633, "mi": 1, "aya": 1, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 159", "qawl": "الثاني", "nass": "وذلك أنه عقب ذلك بقوله: {? عما يشركون}، فدل بذلك على تقريعه المشركين به، ووعيده لهم", "qawaid": ["السياق", "ظاهر الآية ولفظها", "التاريخ والواقع"], "tabi": ""}, {"taliq": 3633, "mi": 1, "aya": 1, "alam": "ابن كثير", "fil": "وكذا", "kind": "موافقة", "ref": "8/ 289", "qawl": "", "nass": "ويبعده قوله: {فلا تستعجلوه}؛ لأنا لا نعرف استعجالا إلا ثلاثة: اثنان منها للكفار في القيامة، وفي العذاب، والثالث للمؤمنين في النصر وظهور الإسلام", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3633, "mi": 1, "aya": 1, "alam": "ابن عطية", "fil": "وكذا", "kind": "موافقة", "ref": "5/ 325", "qawl": "", "nass": "ويبعده قوله: {فلا تستعجلوه}؛ لأنا لا نعرف استعجالا إلا ثلاثة: اثنان منها للكفار في القيامة، وفي العذاب، والثالث للمؤمنين في النصر وظهور الإسلام", "qawaid": [], "tabi": "ابن كثير"}, {"taliq": 3633, "mi": 1, "aya": 1, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "5/ 325", "qawl": "الثاني", "nass": "ومن قال: إن الأمر تعذيب الكفار بنصر محمد صلى الله عليه وسلم وقتله لهم. قال: إن قوله: {فلا تستعجلوه} رد على القائلين: {عجل لنا قطنا} ونحوه من العذاب، أو على مستبطئي النصر من المؤمنين في قراءة من قرأ بالتاء -وهي قراءة الجمهور- على مخاطبة المؤمنين، أو على مخاطبة الكافرين، بمعنى: قل لهم: فلا تستعجلوه", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["016_001_1.png"], "pages": [316], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 3633, "masala": "معنى: {أتى أمر الله}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أمر الله: فرائضه وأحكامه", "ashab": "", "athar": []}, {"n": 2, "t": "أنه وعيد من الله لأهل الشرك به", "ashab": "", "athar": []}, {"n": 3, "t": "خروج رسول الله صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 4, "t": "أنه القيامة", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"], ["ابن كثير", "r"], ["ابن عطية", "r"]]}, "t": {"2": [["ابن جرير", "r"], ["ابن كثير", "r"], ["ابن عطية", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق", "ظاهر الآية ولفظها", "التاريخ والواقع"]}, "rulesD": {}}}, {"aya": 1, "title": "معنى: {أتى أمر الله}", "mawsua": {"taliq": 3633, "masala": "معنى: {أتى أمر الله}", "sigha": "زاد قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه نصر محمد صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 2, "t": "أنه تعذيب كفار مكة بقتل محمد عليه الصلاة والسلام لهم وظهوره عليهم. ووجه القول الثاني منهما بقوله: «ومن قال: إن الأمر تعذيب الكفار بنصر محمد صلى الله عليه وسلم وقتله لهم. قال: إن قوله: {فلا تستعجلوه} رد على القائلين: {عجل لنا قطنا} ونحوه من العذاب، أو على مستبطئي النصر من المؤمنين في قراءة من قرأ بالتاء -وهي قراءة الجمهور- على مخاطبة المؤمنين، أو على مخاطبة الكافرين، بمعنى: قل لهم: فلا تستعجلوه", "ashab": "", "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 2, "title": "معنى «الروح»", "mawsua": {"taliq": 3634, "masala": "معنى «الروح»", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الوحي", "ashab": "", "athar": []}, {"n": 2, "t": "النبوة", "ashab": "", "athar": []}, {"n": 3, "t": "الرحمة والوحي", "ashab": "", "athar": []}, {"n": 4, "t": "كل كلام الله روح", "ashab": "", "athar": []}, {"n": 5, "t": "أنه لا ينزل ملك إلا ومعه روح", "ashab": "مجاهد", "athar": [40773, 40774]}]}, "mawaqif": [{"taliq": 3634, "mi": 1, "aya": 2, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "5/ 326، 327", "qawl": "", "nass": "وهذا قول حسن", "qawaid": [], "tabi": ""}, {"taliq": 3634, "mi": 1, "aya": 2, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "", "qawl": "", "nass": "الروح: شخص له صورة كصورة بني آدم، ما نزل جبريل قط إلا وهو معه، وهم كثير، وهم ملائكة", "qawaid": ["عدم الدليل على غيره"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 8, "title": "الاستدلال بهذه الآية على تحريم أكل لحوم الخيل", "mawsua": {"taliq": 3640, "masala": "الاستدلال بهذه الآية على تحريم أكل لحوم الخيل", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن في هذه الآية دلالة على تحريم أكل لحوم الخيل", "ashab": "", "athar": []}, {"n": 2, "t": "أنها لا تدل على تحريم شيء", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3640, "mi": 1, "aya": 8, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 175 - 176", "qawl": "الثاني", "nass": "لو كان في قوله -تعالى ذكره-: {لتركبوها} دلالة على أنها لا تصلح -إذ كانت للركوب- للأكل، لكان في قوله: {فيها دفء ومنافع ومنها تأكلون} دلالة على أنها لا تصلح -إذ كانت للأكل والدفء- للركوب، وفي إجماع الجميع على أن ركوب ما قال -تعالى ذكره-: {ومنها تأكلون} جائز حلال غير حرام، دليل واضح على أن أكل ما قال: {لتركبوها} جائز حلال غير حرام، إلا بما نص على تحريمه، أو وضع على تحريمه دلالة من كتاب أو وحي إلى رسول الله صلى الله عليه وسلم، فأما بهذه الآية فلا يحرم أكل شيء", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3640, "mi": 1, "aya": 8, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 330", "qawl": "", "nass": "وهذه الحجة غير لازمة عند جماعة من العلماء، قالوا: إنما ذكر الله تعالى عظم منافع الأنعام، وذكر عظم منافع هذه وأهم ما فيها، وليس يقضي ذلك بأن ما ذكره لهذه لا تدخل هذه فيه", "qawaid": [], "tabi": ""}], "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 14, "title": "في تأويل قوله: ﴿مواخر﴾", "tabari": {"page": "14/186", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "المواخر المواقر", "taqdim": 0, "n_athar": 1, "qailun": [["الحسن", "تابعي"]], "athar": [40948, 40949]}, {"n": 2, "t": "ثنا محمد بن ربيعة، عن أبي بكر الأصم، عن عكرمة في قوله: ﴿وترى الفلك مواخر فيه﴾، قال: ما أخذ عن يمين السفينة وعن يسارها من الماء، فهو المواخر", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "بما حدثنا ابن وكيع، قال: ثنا أبو أسامة، عن إسماعيل، عن أبي صالح: ﴿وترى الفلك مواخر فيه﴾. قال: تجرى فيه متعرضة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "ثنا أبو عاصم، قال: ثنا عيسى، عن ابن أبي نجيح، عن مجاهد: ﴿وترى الفلك مواخر فيه﴾. قال: تمخر السفينة الرياح، ولا تمخر الريح من السفن، إلا الفلك العظيم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 5, "t": "ثنا يزيد، قال: ثنا سعيد، عن قتادة قوله:", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 2, "imgs": ["016_002_1.png"], "pages": [316], "n": 4, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 16, "title": "في المعني بالعلامات", "tabari": {"page": "14/192", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله تعالى ذكره عدد على عباده من نعمه إنعامه عليهم بما جعل لهم من العلامات التي يهتدون بها في مسالكهم وطرقهم التي يسيرونها، ولم يخصص بذلك بعض العلامات دون بعض، فكل علامة استدل بها الناس على طرقهم وفجاج سبلهم، فداخل في قوله: ﴿وعلامات﴾، والطرق المسبولة الموطوءة علامة للناحية المقصودة، والجبال علامات يهتدى بهن إلى قصد السبيل، وكذلك النجوم بالليل، غير أن الذي هو أولى بتأويل الآية أن تكون العلامات من أدلة النهار إذ كان الله قد فصل منها أدلة الليل بقوله: ﴿وعلامات وبالنجم هم يهتدون﴾؛ وإذ كان ذلك أشبه وأولى بتأويل الآية، فالواجب أن يكون القول في ذلك ما قاله ابن عباس في الخبر الذي رويناه عن عطية عنه، وهو أن العلامات معالم الطرق وأماراتها التي يهتدى بها إلى المستقيم منها نهارا، وأن يكون النجم الذي يهتدى به ليلا هو الجدى والفرقدان، لأنبها اهتداء السفر، دون غيرها من النجوم.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى بها معالم الطرق بالنهار", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [40988, 40998]}, {"n": 2, "t": "عنى بها النجوم", "taqdim": 0, "n_athar": 6, "qailun": [["إبراهيم", "تابعي"], ["مجاهد", "تابعي"], ["المثنى", ""], ["قتادة", "تابعي"]], "athar": [40989, 40990, 40991, 40992, 40999, 41000, 41001, 41005, 41006]}, {"n": 3, "t": "عنى بها الجبال", "taqdim": 0, "n_athar": 1, "qailun": [["معمر عن الكلبي", "تابع التابعين"]], "athar": []}]}, "mawaqif": [{"taliq": 3652, "mi": 1, "aya": 16, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "14/ 194", "qawl": "العموم", "nass": "أولى الأقوال في ذلك بالصواب أن يقال: إن الله -تعالى ذكره- عدد على عباده من نعمه إنعامه عليهم بما جعل لهم من العلامات التي يهتدون بها في مسالكهم وطرقهم التي يسيرونها، ولم يخصص بذلك بعض العلامات دون بعض، فكل علامة استدل بها الناس على طرقهم وفجاج سبلهم فداخل في قوله: {وعلامات}، والطرق المسبولة الموطوءة علامة للناحية المقصودة، والجبال علامات يهتدى بهن إلى قصد السبيل، وكذلك النجوم بالليل", "qawaid": ["العموم", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3652, "mi": 1, "aya": 16, "alam": "ابن تيمية", "fil": "ذكر", "kind": "نقل", "ref": "النبوات 2/ 757", "qawl": "الأول", "nass": "وقول الأكثرين أصح؛ فإن العلامات كلها يهتدى بها، ولأنه قد قال: {وألقى في الأرض رواسي أن تميد بكم وأنهارا وسبلا لعلكم تهتدون * وعلامات} وهذا كله مما ألقاه في الأرض، وهو منصوب ب", "qawaid": ["ظاهر الآية ولفظها", "اللغة"], "tabi": ""}, {"taliq": 3652, "mi": 1, "aya": 16, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 339", "qawl": "", "nass": "أنه سمع بعض أهل العلم بالمشرق يقول: إن في بحر الهند الذي يجرى فيه من اليمن إلى الهند حيتانا طوالا رقاقا كالحيات في ألوانها وحركتها والتوائها، وأنها تسمى العلامات، وذلك أنها علامة الوصول إلى بلاد الهند، وأمارة النجاة والانتهاء إلى الهند لطول ذلك البحر وصعوبته، وأن بعض الناس قال: إنها التي أراد الله تعالى في هذه الآية. قال القاضي أبو محمد: قال أبي?: وأنا ممن شاهد تلك العلامات في البحر المذكور وعاينها، فحدثني منهم عدد كثير", "qawaid": [], "tabi": ""}], "mushid": {"i": 3, "imgs": ["016_003_1.png"], "pages": [316], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3652, "masala": "المعني ب «العلامات»", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "معالم الطرق بالنهار", "ashab": "", "athar": []}, {"n": 2, "t": "عني بها النجوم", "ashab": "", "athar": []}, {"n": 3, "t": "عني بها الجبال", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "تأويل: ﴿أفلا تذكرون﴾", "tabari": {"page": "14/195", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿أفلا تذكرون﴾ أيها الناس. يقول: أفلا تذكرون نعم الله عليكم، وعظيم سلطانه وقدرته على ما شاء، وعجز أوثانكم وضعفها ومهانتها، وأنها لا تجلب إلى نفسها نفعا، ولا تدفع عنها ضرا، فتعرفوا بذلك خطأ ما أنتم عليه مقيمون، من عبادتكموها، وإقراركم لها بالألوهة.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿كمن لا يخلق﴾ [ومن لا يخلق] هو الوثن والصنم، و \"من\" لذوى التمييز خاصة، فجعل في هذا الموضع لغيرهم التمييز، إذ وقع تفصيلا بين من يخلق ومن لا يخلق. ومحكي عن العرب: اشتبه علي الراكب وحمله ، فما أدرى من ذا من ذا. حيث جمعا وأحدهما إنسان، حسنت \"من\" فيهما جميعا. ومنه قول الله ﷿: ﴿فمنهم من يمشي على بطنه ومنهم من يمشي على رجلين ومنهم من يمشي على أربع﴾ [النور: ٤٥]", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 25, "title": "لام {ليحملوا}", "mawsua": {"taliq": 3657, "masala": "لام {ليحملوا}", "sigha": "ذكر ثلاثة احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن تكون لام العاقبة؛ لأنهم لم يقصدوا بقولهم: {أساطير الأولين} أن يحملوا الأوزار", "ashab": "", "athar": []}, {"n": 2, "t": "أن تكون صريح لام كي، على معنى: قدر هذا", "ashab": "", "athar": []}, {"n": 3, "t": "أن تكون لام الأمر، على معنى: الحتم عليهم بذلك والصغار الموجب لهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3657, "mi": 1, "aya": 25, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 344", "qawl": "", "nass": "أن تكون لام العاقبة؛ لأنهم لم يقصدوا بقولهم: {أساطير الأولين} أن يحملوا الأوزار", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 25, "title": "معنى: {بغير علم}", "mawsua": {"taliq": 3658, "masala": "معنى: {بغير علم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد بها: المضل، أي: أضل بغير برهان قام عنده", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: بغير علم من المقلدين الذين يضلونهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3658, "mi": 1, "aya": 25, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 344", "qawl": "", "nass": "أن يريد بها: المضل، أي: أضل بغير برهان قام عنده", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 26, "title": "في معنى ذلك ﴿فخر عليهم السقف من فوقهم﴾", "tabari": {"page": "14/205", "sarih": 1, "tarjih": "وأولى القولين بتأويل الآية قول من قال: معنى ذلك: تساقطت عليهم سقوف بيوتهم، إذ أتى أصولها وقواعدها أمر الله، فائتفكت بهم منازلهم؛ لأن ذلك هو الكلام المعروف من قواعد البنيان وخر السقف، وتوجيه معاني كلام الله إلى الأشهر الأعرف منهما أولى من توجيهها إلى غير ذلك ما وجد إليه سبيل.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "فخر عليهم السقف من فوقهم: أعالى بيوتهم من فوقهم", "taqdim": 0, "n_athar": 4, "qailun": [["قتادة", "تابعي"], ["ابن أبي نجيح", "تابع التابعين"]], "athar": [41076, 41078, 41083]}, {"n": 2, "t": "عنى بقوله: ﴿فخر عليهم السقف من فوقهم﴾. أن العذاب أتاهم من السماء", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [41072, 41082]}]}, "mawaqif": [{"taliq": 3660, "mi": 1, "aya": 26, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 206 - 207", "qawl": "الأول", "nass": "لأن ذلك هو الكلام المعروف من قواعد البنيان وخر السقف، وتوجيه معاني كلام الله إلى الأشهر الأعرف منهما أولى من توجيهها إلى غير ذلك ما وجد إليه سبيل", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3660, "mi": 1, "aya": 26, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 345", "qawl": "الثاني", "nass": "وهذا ينحو إلى اللغز", "qawaid": [], "tabi": ""}], "mushid": {"i": 4, "imgs": ["016_004_1.png"], "pages": [317], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3660, "masala": "معنى قوله تعالى: {فخر عليهم السقف من فوقهم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن المعنى: فخر عليهم أعالي بيوتهم وهم تحتها", "ashab": "", "athar": []}, {"n": 2, "t": "أن العذاب أتاهم من السماء", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 28, "title": "تأويل: ﴿الذين تتوفاهم الملائكة ظالمي أنفسهم فألقوا السلم ما كنا نعمل من سوء بلى إن الله عليم بما ك﴾", "tabari": {"page": "14/208", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: قال الذين أوتوا العلم: إن الخزى اليوم والسوء على من كفر بالله، فجحد وحدانيته، ﴿الذين تتوفاهم الملائكة﴾. يقول: الذين تقبض أرواحهم الملائكة، ﴿ظالمي أنفسهم﴾. يعني: وهم على كفرهم وشركهم بالله.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إنه عنى بذلك من قتل من قريش ببدر، وقد أخرج إليها كرها. حدثني المثنى، قال: أخبرنا إسحاق، قال: ثنا يعقوب بن محمد الزهري، قال: ثني سفيان بن عيينة، عن عمرو بن دينار، عن عكرمة، قال: كان ناس بمكة أقروا بالإسلام ولم يهاجروا، فأخرج بهم كرها إلى بدر، فقتل بعضهم، فأنزل الله فيهم: ﴿الذين تتوفاهم الملائكة ظالمي أنفسهم﴾", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 37, "title": "قراءة قوله تعالى: {فإن الله لا يهدي من يضل}", "mawsua": {"taliq": 3665, "masala": "قراءة قوله تعالى: {فإن الله لا يهدي من يضل}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "{يهدي} بفتح الياء، و {يضل} بضمها، وقارئو ذلك اختلفوا في معناها على قولين: الأول: أن المعنى: فإن الله من أضله لا يهتدي", "ashab": "", "athar": []}, {"n": 2, "t": "أن المعنى: فإن الله لا يهدي من أضله، بمعنى: أن من أضله الله فإن الله لا يهديه. الثانية: «يهدى» بضم الياء وفتح الدال، و {يضل} بضم الياء، بمعنى: من أضله الله فلا هادي له", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3665, "mi": 1, "aya": 37, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 218", "qawl": "", "nass": "لأن {يهدي} بمعنى: يهتدي، قليل في كلام العرب غير مستفيض، وأنه لا فائدة في قول قائل: من أضله الله فلا يهديه؛ لأن ذلك مما لا يجهله كثير أحد، وإذ كان ذلك كذلك فالقراءة بما كان مستفيضا في كلام العرب من اللغة بما فيه الفائدة العظيمة أولى وأحرى", "qawaid": ["اللغة", "القراءة ورسم المصحف"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["اللغة", "القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 41, "title": "تأويل: ﴿والذين هاجروا في الله من بعد ما ظلموا لنبوئنهم في الدنيا حسنة﴾", "tabari": {"page": "14/224", "sarih": 0, "tarjih": "وأولى القولين في ذلك بالصواب، قول من قال: معنى ﴿لنبوئنهم﴾: لنحلنهم ولنسكننهم؛ لأن التبوء في كلام العرب الحلول بالمكان والنزول به. ومنه قول الله تعالى: ﴿ولقد بوأنا بني إسرائيل مبوأ صدق﴾ [يونس: ٩٣].", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "﴿والذين هاجروا في الله من بعد ما ظلموا لنبوئنهم في الدنيا حسنة﴾. يقول تعالى ذكره: والذين فارقوا قومهم ودورهم وأوطانهم؛ عداوة لهم في الله على كفرهم، إلى آخرين غيرهم. ﴿من بعد ما ظلموا﴾. يقول: من بعد نيل منهم في أنفسهم بالمكاره في ذات الله. ﴿لنبوئنهم في الدنيا حسنة﴾. يقول: لنسكننهم في الدنيا مسكنا يرضونه صالحا.", "taqdim": 1, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["الشعبي", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [41217, 41218, 41222, 41228, 41230, 41232]}, {"n": 2, "t": "عنى بقوله: ﴿لنبوئنهم في الدنيا حسنة﴾: لنرزقنهم في الدنيا رزقا حسنا", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"]], "athar": [41227]}, {"n": 3, "t": "إن هذه الآية نزلت في أبى جندل بن سهيل", "taqdim": 0, "n_athar": 1, "qailun": [["داود بن أبى هند", "تابعي"]], "athar": [41215]}]}, "mawaqif": [{"taliq": 3667, "mi": 1, "aya": 41, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 356", "qawl": "الجمهور", "nass": "وهو الصحيح في سبب هذه الآية؛ لأن هجرة المدينة لم تكن وقت وقوع الآية", "qawaid": ["سبب النزول وأحواله"], "tabi": ""}, {"taliq": 3667, "mi": 1, "aya": 41, "alam": "ابن تيمية", "fil": "ذهب", "kind": "قول", "ref": "4/ 164", "qawl": "", "nass": "سبب نزولها المهاجرون إلى رسول الله صلى الله عليه وسلم، وهي عامة في كل من اتصف بهذه الصفة", "qawaid": [], "tabi": ""}], "mushid": {"i": 5, "imgs": ["016_005_1.png"], "pages": [317], "n": 2, "rajih": [1], "daif": [], "match": false}, "mawsua": {"taliq": 3667, "masala": "نزول هذه الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها نزلت في أبي جندل بن سهيل", "ashab": "", "athar": []}, {"n": 2, "t": "أنها نزلت في خمسة نفر", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن عطية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن عطية": ["سبب النزول وأحواله"]}, "rulesD": {}}}, {"aya": 41, "title": "معنى: {لنبوئنهم في الدنيا حسنة}", "mawsua": {"taliq": 3668, "masala": "معنى: {لنبوئنهم في الدنيا حسنة}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "لنسكننهم في الدنيا مسكنا يرضونه صالحا، وهو المدينة", "ashab": "", "athar": []}, {"n": 2, "t": "لنرزقنهم في الدنيا رزقا حسنا", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3668, "mi": 1, "aya": 41, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 225", "qawl": "الأول", "nass": "لأن التبوء في كلام العرب: الحلول بالمكان والنزول به، ومنه قول الله تعالى: {ولقد بوأنا بني إسرائيل مبوأ صدق} [يونس: 93]", "qawaid": ["اللغة", "القرآن والنظائر"], "tabi": ""}, {"taliq": 3668, "mi": 1, "aya": 41, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 357 بتصرف", "qawl": "", "nass": "وفي قوله: {لنبوئنهم} على هذا التأويل في لسان الصدق تجوز كثير، واستعارة بعيدة", "qawaid": [], "tabi": ""}, {"taliq": 3668, "mi": 1, "aya": 41, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "8/ 313", "qawl": "", "nass": "ولا منافاة بين القولين، فإنهم تركوا مساكنهم وأموالهم، فعوضهم الله خيرا منها في الدنيا، فإن من ترك شيئا لله عوضه الله بما هو خير له منه، وكذلك وقع، فإنهم مكن الله لهم في البلاد، وحكمهم على رقاب العباد، فصاروا أمراء حكاما، وكل منهم للمتقين إماما", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["اللغة", "القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 43, "title": "المعني ب «أهل الذكر»", "mawsua": {"taliq": 3669, "masala": "المعني ب «أهل الذكر»", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أهل الكتاب من اليهود والنصارى", "ashab": "", "athar": []}, {"n": 2, "t": "من أسلم من أهل الكتاب", "ashab": "", "athar": []}, {"n": 3, "t": "أهل القرآن", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3669, "mi": 1, "aya": 43, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "5/ 358 ط: دار الكتب العلمية", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3669, "mi": 1, "aya": 43, "alam": "ابن عطية", "fil": "استظهر", "kind": "ترجيح", "ref": "", "qawl": "الأول", "nass": "والأظهر في هذا كله قول ابن عباس رضي الله عنهما أن يكون أهل الذكر هنا: أحبار اليهود والنصارى الذين لم يسلموا، وهم في هذه النازلة خاصة إنما يخبرون بأن الرسل من البشر، وإخبارهم حجة على هؤلاء، فإنهم لم يزالوا مصدقين لهم، ولا يتهمون بشهادة لنا لأنهم مدافعون في صدر ملة محمد صلى الله عليه وسلم -قاتلهم الله-، وهذا هو كسر حجتهم من مذهبهم، لا أنا افتقرنا إلى شهادة هؤلاء، بل الحق واضح في نفسه، وقد أرسلت قريش إلى يهود يثرب يسألون ويسندون إليهم", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3669, "mi": 1, "aya": 43, "alam": "ابن كثير", "fil": "استدرك", "kind": "نقد", "ref": "8/ 314", "qawl": "الثالث", "nass": "وقول عبد الرحمن بن زيد: الذكر: القرآن. واستشهد بقوله: {إنا نحن نزلنا الذكر وإنا له لحافظون} [الحجر: 9] صحيح، لكن ليس هو المراد هاهنا؛ لأن المخالف لا يرجع في إثباته بعد إنكاره إليه. وكذا قول أبي جعفر الباقر: نحن أهل الذكر", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "tags": {"m": {"1": [["ابن عطية", "r"]], "3": [["ابن كثير", "d"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["الدلالة العقلية"]}, "rulesD": {"ابن كثير": ["الدلالة العقلية"]}}}, {"aya": 44, "title": "معنى", "mawsua": {"taliq": 3670, "masala": "معنى", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد: لتبين بسردك نص القرآن ما نزل", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: لتبين بتفسيرك المجمل، وبشرحك ما أشكل مما نزل", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3670, "mi": 1, "aya": 44, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 359", "qawl": "", "nass": "يحتمل أن يريد: لتبين بسردك نص القرآن ما نزل. ويحتمل أن يريد: لتبين بتفسيرك المجمل، وبشرحك ما أشكل مما نزل", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 48, "title": "في قراءة ذلك ﴿أولم يروا إلى ما خلق الله من شيء يتفيأ ظلاله عن اليمين والشمائل سجدا لله وهم داخرون﴾", "tabari": {"page": "14/239", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله أخبر في هذه الآية، أن ظلال الأشياء هي التي تسجد. وسجودها ميلانها ودورانها من جانب إلى جانب، وناحية إلى ناحية، كما قال ابن عباس. يقال ذلك: سجدت النخلة. إذا مالت. وسجد البعير. وأسجد إذا ميل للركوب. وقد بينا معنى السجود في غير هذا الموضع بما أغنى عن إعادته.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "بل عنى بقوله: ﴿يتفيأ ظلاله﴾: كلا عن اليمين والشمائل في حال سجودها. قالوا: وسجود الأشياء غير ظلالها", "taqdim": 0, "n_athar": 2, "qailun": [["الضحاك", "تابعي"], ["مجاهد", "تابعي"]], "athar": [41323, 41324, 41325, 41326, 41327, 41328, 41329, 41339, 41340]}, {"n": 2, "t": "بل الذي وصف الله بالسجود في هذه الآية، ظلال الأشياء، فإنما يسجد ظلالها دون التي لها الظلال", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [41320, 41321, 41322, 41323, 41324, 41325, 41339]}]}, "mawaqif": [{"taliq": 3676, "mi": 1, "aya": 48, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 365", "qawl": "الأول", "nass": "هو سجود عبادة حقيقية", "qawaid": [], "tabi": ""}, {"taliq": 3676, "mi": 1, "aya": 48, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 242", "qawl": "الثالث", "nass": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله أخبر في هذه الآية أن ظلال الأشياء هي التي تسجد. وسجودها: ميلانها ودورانها من جانب إلى جانب، وناحية إلى ناحية. كما قال ابن عباس. يقال من ذلك: سجدت النخلة إذا مالت، وسجد البعير وأسجد: إذا ميل للركوب", "qawaid": ["اللغة", "أقوال السلف"], "tabi": ""}], "mushid": {"i": 6, "imgs": ["016_006_1.png"], "pages": [317], "n": 3, "rajih": [3], "daif": [], "match": false}, "mawsua": {"taliq": 3676, "masala": "معنى: {سجدا لله}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن ظل كل شيء سجوده", "ashab": "", "athar": []}, {"n": 2, "t": "أن سجود الظلال سجود أشخاصها", "ashab": "", "athar": []}, {"n": 3, "t": "أن سجود الظلال كسجود الأشخاص تسجد لله خاضعة", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن عطية", "w"]], "3": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["اللغة", "أقوال السلف"]}, "rulesD": {}}}, {"aya": 52, "title": "في تأويل الواصب", "tabari": {"page": "14/247", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه ما قلنا", "taqdim": 0, "n_athar": 10, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"], ["مجاهد", "تابعي"], ["الضحاك", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [41363, 41366, 41367, 41368, 41369, 41370, 41374, 41375, 41378]}, {"n": 2, "t": "الواصب في هذا الموضع الواجب", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"]], "athar": [41363, 41366, 41367, 41368, 41369]}]}, "mawaqif": [{"taliq": 3678, "mi": 1, "aya": 52, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "14/ 246", "qawl": "", "nass": "", "qawaid": ["اللغة", "القرآن والنظائر"], "tabi": ""}], "mushid": {"i": 7, "imgs": ["016_007_1.png"], "pages": [317], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3678, "masala": "معنى الواصب", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الواجب", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الدائم", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 53, "title": "في وجه دخول الفاء في قوله: ﴿فمن الله﴾", "tabari": {"page": "14/250", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "دخلت الفاء، لأن (ما) بمنزلة \"من\" فجعل الخبر بالفاء", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "\"ما\" في معنى جزاء، ولها فعل مضمر، كأنك قلت: ما يكن بكم من نعمة فمن الله؛ لأن الجزاء لا بد له من فعل مجزوم، إن ظهر فهو جزم، وإن لم يظهر فهو مضمر، كما قال الشاعر:", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"]], "athar": [41385, 41386]}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 55, "title": "قوله: {ليكفروا}", "mawsua": {"taliq": 3680, "masala": "قوله: {ليكفروا}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون كفر الجحد بالله والشرك، ويؤيده قوله: {بربهم يشركون}", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون كفر النعمة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3680, "mi": 1, "aya": 55, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 370", "qawl": "", "nass": "وقوله: {ليكفروا} يجوز أن يكون اللام لام الصيرورة، أي: فصار أمرهم ليكفروا، وهم لم يقصدوا بأفعالهم تلك أن يكفروا. ويجوز أن تكون لام أمر على معنى التهديد والوعيد، كقوله: {اعملوا ما شئتم} [فصلت: 40]، والكفر هنا يحتمل أن يكون كفر الجحد بالله والشرك، ويؤيده قوله: {بربهم يشركون}، ويحتمل أن يكون كفر النعمة", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3680, "mi": 1, "aya": 55, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "8/ 318", "qawl": "", "nass": "وقيل: لام التعليل، بمعنى: قيضنا لهم ذلك ليكفروا، أي: يستروا ويجحدوا نعم الله عليهم، وأنه المسدي إليهم النعم، الكاشف عنهم النقم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 62, "title": "في تأويل ذلك ﴿وأنهم مفرطون﴾", "tabari": {"page": "14/263", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب القول الذي اخترناه؛ وذلك أن الإفراط الذي هو بمعنى التقديم، إنما يقال في من قدم مقدما لإصلاح ما يقدم إليه، إلى وقت ورود من قدمه عليه، وليس بمقدم من قدم إلى النار من أهلها، لإصلاح شيء فيها، لوارد يرد عليها فيها، فيوافقه مصلحا، وإنما يقدم من قدم إليها لعذاب يعجل له. فإذ كان [ذلك معنى] الإفراط، الذي هو تأويل التعجيل، ففسد أن يكون له وجه في الصحة صح المعنى الآخر، وهو الإفراط الذي بمعنى التخليف والترك. وذلك أنه يحكى عن العرب: ما أفرطت ورائى أحدا. أي: ما خلفته، وما فرطته. أي: لم أخلفه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "معنى ذلك: أنهم معجلون إلى النار، مقدمون إليها. وذهبوا في ذلك إلى قول العرب: أفرطنا فلانا في طلب الماء. إذا قدموه لإصلاح الدلاء والأرشية ، وتسوية ما يحتاجون إليه عند ورودهم عليه، فهو مفرط. فأما المتقدم نفسه فهو فارط، يقال: قد فرط فلان أصحابه يفرطهم فرطا وفروطا. إذا تقدمهم. وجمع فارط فراط، ومنه قول القطامي", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"]], "athar": [41474, 41475, 41479, 41492, 41493]}, {"n": 2, "t": "معنى ذلك: مبعدون في النار", "taqdim": 0, "n_athar": 1, "qailun": [["سعيد", "تابعي"]], "athar": [41487, 41488]}]}, "mawaqif": [{"taliq": 3693, "mi": 1, "aya": 62, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "14/ 265", "qawl": "الثاني", "nass": "أنا فرطكم على الحوض", "qawaid": [], "tabi": ""}, {"taliq": 3693, "mi": 1, "aya": 62, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 266", "qawl": "الأول", "nass": "وذلك أن الإفراط الذي هو بمعنى التقديم إنما يقال فيمن قدم مقدما لإصلاح ما يقدم إليه إلى وقت ورود من قدمه عليه، وليس بمقدم من قدم إلى النار من أهلها لإصلاح شيء فيها لوارد يرد عليها فيها فيوافقه مصلحا، وإنما تقدم من قدم إليها لعذاب يعجل له، فإذا كان معنى ذلك الإفراط الذي هو تأويل التعجيل ففسد أن يكون له وجه في الصحة؛ صح المعنى الآخر، وهو الإفراط الذي بمعنى التخليف والترك، وذلك أن يحكى عن العرب: ما أفرطت ورائي أحدا، أي: ما خلفته، وما فرطته، أي: لم أخلفه", "qawaid": ["الدلالة العقلية", "اللغة"], "tabi": ""}, {"taliq": 3693, "mi": 1, "aya": 62, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "8/ 322", "qawl": "", "nass": "ولا منافاة؛ لأنهم يعجل بهم يوم القيامة إلى النار، وينسون فيها، أي: يخلدون", "qawaid": [], "tabi": ""}], "mushid": {"i": 8, "imgs": ["016_008_1.png"], "pages": [317], "n": 3, "rajih": [1], "daif": [2], "match": false}, "mawsua": {"taliq": 3693, "masala": "تفسير قوله: {وأنهم مفرطون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنهم متروكون في النار", "ashab": "", "athar": []}, {"n": 2, "t": "أنهم معجلون إلى النار مقدمون إليها", "ashab": "", "athar": []}, {"n": 3, "t": "أنهم مبعدون في النار", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية", "اللغة"]}, "rulesD": {}}}, {"aya": 62, "title": "قوله: {الحسنى}", "mawsua": {"taliq": 3689, "masala": "قوله: {الحسنى}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "أن المراد به: الذكور من الأولاد", "ashab": "", "athar": []}, {"n": 2, "t": "أن المراد به: الجنة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3689, "mi": 1, "aya": 62, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 374 - 375", "qawl": "الأول", "nass": "وهو الأسبق من معنى الآية", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 63, "title": "المراد من {اليوم}، فقال", "mawsua": {"taliq": 3694, "masala": "المراد من {اليوم}، فقال", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد: يوم الإخبار بهذه الآية، وهو بعد موت أولئك الأمم المذكورة، أي: لا ولي لهم مذ ماتوا واحتاجوا إلى الغوث إلا الشيطان", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: يوم القيامة، والألف واللام فيه للعهد، أي: هو وليهم في اليوم المشهود، وهو وقت الحاجة والفصل", "ashab": "", "athar": []}, {"n": 3, "t": "أن يريد: فهو وليهم مدة حياتهم، ثم انقطعت ولايته بموتهم. وعبر عن ذلك بقوله: {اليوم} تمثيلا للمخاطبين بمدة حياتهم، كما تقول لرجل شاب تحضه على طلب العلم: يا فلان، لا يدرس أحد من الناس إلا اليوم. تريد: في مثل سنك هذه. فكأنه قال لهؤلاء: {فهو وليهم} في مثل حياتكم هذه، وهي التي كانت لهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3694, "mi": 1, "aya": 63, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 376", "qawl": "", "nass": "وقوله: {اليوم} يحتمل أن يريد: يوم الإخبار بهذه الآية، وهو بعد موت أولئك الأمم المذكورة، أي: لا ولي لهم مذ ماتوا واحتاجوا إلى الغوث إلا الشيطان. ويحتمل أن يريد: يوم القيامة، والألف واللام فيه للعهد، أي: هو وليهم في اليوم المشهود، وهو وقت الحاجة والفصل. ويحتمل أن يريد: فهو وليهم مدة حياتهم، ثم انقطعت ولايته بموتهم. وعبر عن ذلك بقوله: {اليوم} تمثيلا للمخاطبين بمدة حياتهم، كما تقول لرجل شاب تحضه على طلب العلم: يا فلان، لا يدرس أحد من الناس إلا اليوم. تريد: في مثل سنك هذه. فكأنه قال لهؤلاء: {فهو وليهم} في مثل حياتكم هذه، وهي التي كانت لهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 67, "title": "في معنى قوله: ﴿تتخذون منه سكرا ورزقا حسنا﴾", "tabari": {"page": "14/275", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى بالسكر الخمر، وبالرزق الحسن التمر والزبيب", "taqdim": 0, "n_athar": 33, "qailun": [["ابن عباس", "صحابي"], ["عمرو بن سفيان البصري", ""], ["سعيد بن جبير", "تابعي"], ["أبي رزين", "تابعي"], ["إبراهيم والشعبى وأبى رزين", ""], ["إبراهيم", "تابعي"], ["الحسن", "تابعي"], ["الضحاك", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [41518, 41519, 41520, 41522, 41523, 41525, 41526, 41527, 41528, 41529, 41530, 41531, 41534, 41535, 41536, 41537, 41541, 41542, 41543, 41553, 41554, 41555, 41556, 41559, 41562, 41563]}, {"n": 2, "t": "السكر بمنزلة الخمر في التحريم، وليس بخمر. وقالوا: هو نقيع التمر والزبيب إذا اشتد وصار يسكر شاربه", "taqdim": 0, "n_athar": 8, "qailun": [["ابن عباس", "صحابي"], ["موسى", "تابع التابعين"], ["إبراهيم", "تابعي"], ["إبراهيم وأبى رزين", ""], ["ابن زيد", "تابع التابعين"]], "athar": [41525, 41527, 41528, 41529, 41530, 41531, 41547, 41555, 41556, 41559]}, {"n": 3, "t": "السكر هو كل ما كان حلالا شربه؛ كالنبيذ الحلال، والخل، والرب ، والرزق الحسن التمر والزبيب", "taqdim": 0, "n_athar": 5, "qailun": [["مجاهد", "تابعي"], ["الشعبي", "تابعي"]], "athar": [41524, 41535, 41536, 41537, 41540, 41554, 41557, 41562]}]}, "mawaqif": [{"taliq": 3697, "mi": 1, "aya": 67, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "14/ 284 - 285 بتصرف", "qawl": "الثالث", "nass": "وعلى هذا التأويل الآية غير منسوخة، بل حكمها ثابت", "qawaid": ["اللغة", "عدم الدليل على غيره"], "tabi": ""}, {"taliq": 3697, "mi": 1, "aya": 67, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 379", "qawl": "", "nass": "والسكر: ما يسكر. هذا هو المشهور في اللغة", "qawaid": [], "tabi": ""}], "mushid": {"i": 9, "imgs": ["016_009_1.png"], "pages": [318], "n": 3, "rajih": [3], "daif": [], "match": true}, "mawsua": {"taliq": 3697, "masala": "تفسير قوله: {تتخذون منه سكرا ورزقا حسنا}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "عنى بالسكر: الخمر. وبالرزق الحسن: التمر والزبيب. وقال أصحاب هذا القول: إنما نزلت هذه الآية قبل تحريم الخمر، ثم حرمت بعد", "ashab": "", "athar": []}, {"n": 2, "t": "السكر بمنزلة الخمر في التحريم، وليس بخمر، وقالوا: هو نقيع التمر والزبيب إذا اشتد وصار يسكر شاربه", "ashab": "", "athar": []}, {"n": 3, "t": "السكر: هو كل ما كان حلالا شربه؛ كالنبيذ الحلال، والخل، والرطب. والرزق الحسن: التمر، والزبيب", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن جرير", "r"]]}, "t": {"3": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 69, "title": "تأويل: ﴿ثم كلي من كل الثمرات فاسلكي سبل ربك ذللا يخرج من بطونها شراب مختلف ألوانه فيه شفاء للناس إ﴾", "tabari": {"page": "14/288", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ﴿ثم كلي﴾ أيتها النحل ﴿من كل الثمرات فاسلكي سبل ربك﴾. يقول: فاسلكى طرق ربك ﴿ذللا﴾. يقول: مذللة لك. والذلل: جمع ذلول.", "taqdim": 1, "n_athar": 2, "qailun": [["مجاهد", "تابعي"]], "athar": [41582, 41594, 41595]}, {"n": 2, "t": "ثنا يزيد، قال: ثنا سعيد، عن قتادة قوله: ﴿فاسلكي سبل ربك ذللا﴾. أي: مطيعة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3701, "mi": 1, "aya": 69, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "14/ 288", "qawl": "مجاهد ومن", "nass": "وعلى هذا التأويل الذي تأوله مجاهد الذلل من نعت السبل. والتأويل على قوله: {فاسلكي سبل ربك ذللا} الذلل لك: لا يتوعر عليك سبيل سلكتيه، ثم أسقطت الألف واللام فنصب على الحال", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3701, "mi": 1, "aya": 69, "alam": "ابن كثير", "fil": "ووافقه", "kind": "موافقة", "ref": "8/ 325", "qawl": "", "nass": "والقول الأول أظهر، وهو أنه حال من الطريق، أي: فاسلكيها مذللة لك. نص عليه مجاهد", "qawaid": [], "tabi": "ابن جرير"}], "mawsua": {"taliq": 3701, "masala": "قوله تعالى: {ذللا}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "مذللة لك", "ashab": "", "athar": []}, {"n": 2, "t": "مطيعة", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 69, "title": "في عادت عليه الهاء التي في قوله: ﴿فيه﴾", "tabari": {"page": "14/289", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عادت على القرآن، وهو المراد بها", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [41582, 41594, 41595]}, {"n": 2, "t": "بل أريد بها العسل", "taqdim": 0, "n_athar": 5, "qailun": [["قتادة", "تابعي"], ["عبد الله", "صحابي"], ["ابن عباس", "صحابي"]], "athar": [41583, 41589, 41597, 41602, 41603, 41604, 41609]}]}, "mawaqif": [{"taliq": 3703, "mi": 1, "aya": 69, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 291", "qawl": "الثاني", "nass": "لأن قوله: {فيه} في سياق الخبر عن العسل، فأن تكون الهاء من ذكر العسل إذ كانت في سياق الخبر عنه أولى من غيره", "qawaid": ["السياق", "السنة"], "tabi": ""}, {"taliq": 3703, "mi": 1, "aya": 69, "alam": "ابن كثير", "fil": "وكذا", "kind": "موافقة", "ref": "8/ 326 - 329", "qawl": "", "nass": "الصحيح: رجوع الضمير إلى الشراب، وهو قول ابن مسعود، وابن عباس، والحسن، وقتادة، والأكثرين، فإنه هو المذكور، والكلام سيق لأجله، ولا ذكر للقرآن في الآية، وهذا الحديث الصحيح وهو قوله: «صدق الله", "qawaid": ["السنة"], "tabi": "ابن جرير"}, {"taliq": 3703, "mi": 1, "aya": 69, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "8/ 326", "qawl": "الأول", "nass": "وهذا قول صحيح في نفسه، ولكن ليس هو الظاهر هاهنا من سياق الآية؛ فإن الآية إنما ذكر فيها العسل، ولم يتابع مجاهد على قوله هاهنا، وإنما الذي قاله ذكروه في قوله تعالى: {وننزل من القرآن ما هو شفاء ورحمة للمؤمنين} الآية [الإسراء: 82]، وقوله تعالى: {يا أيها الناس قد جاءتكم موعظة من ربكم وشفاء لما في الصدور وهدى ورحمة للمؤمنين} [يونس: 57]", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3703, "mi": 1, "aya": 69, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 381", "qawl": "", "nass": "وذهب قوم من أهل الجهالة إلى أن هذه الآية إنما يراد بها: أهل البيت ورجال بني هاشم، وأنهم النحل، وأن الشراب: القرآن والحكمة، وقد ذكر بعضهم هذا في مجلس المنصور أبي جعفر العباسي: فقال له رجل ممن حضر: جعل الله طعامك وشرابك مما يخرج من بطون بني هاشم. فأضحك الحاضرين، وبهت الآخر، وظهرت سخافة قوله", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 10, "imgs": ["016_010_1.png"], "pages": [318], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 3703, "masala": "ما عنى الله بقوله: {فيه شفاء للناس}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه القرآن", "ashab": "", "athar": []}, {"n": 2, "t": "أنه العسل", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق", "السنة"], "ابن كثير": ["السنة"]}, "rulesD": {}}}, {"aya": 72, "title": "في المعني بالحفدة", "tabari": {"page": "14/295", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندى أن يقال: إن الله تعالى ذكره أخبر عباده معرفهم نعمه عليهم فيما جعل لهم من الأزواج والبنين، فقال تعالى ذكره: ﴿والله جعل لكم من أنفسكم أزواجا وجعل لكم من أزواجكم بنين وحفدة﴾، فأعلمهم أنه جعل لهم من أزواجهم بنين وحفدة، والحفدة في كلام العرب جمع حافد، كما الكذبة جمع كاذب، والفسقة جمع فاسق. والحافد في كلامهم هو المتخفف في الخدمة والعمل. والحفد خفة الرجل العمل. يقال: مر البعير يحفد حفدانا. إذا مر يسرع في سيره، ومنه قولهم: إليك نسعى ونحفد . أي: نسرع إلى العمل بطاعتك. يقال منه: حفد له يحفد حفدا وحفودا وحفدانا. ومنه قول الراعى :", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هم الأحتان، أحتان الرجل على بناته", "taqdim": 0, "n_athar": 13, "qailun": [["عبد الله", "صحابي"], ["أبي الضحى", "تابعي"], ["إبراهيم", "تابعي"], ["سعيد بن حبير", ""], ["ابن عباس", "صحابي"], ["ابن مسعود", "صحابي"], ["زر بن حبيش", "تابعي"]], "athar": [41641, 41642, 41643, 41644, 41645, 41646, 41647, 41648, 41650, 41651, 41652, 41654, 41655, 41656]}, {"n": 2, "t": "هم أعوان الرجل وخدمه", "taqdim": 0, "n_athar": 20, "qailun": [["قوله", ""], ["عكرمة", "تابعي"], ["الحسن", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["أبي مالك", "تابعي"]], "athar": [41638, 41657, 41658, 41659, 41660, 41667, 41668, 41669, 41671, 41676]}, {"n": 3, "t": "هم ولد الرجل وولد ولده", "taqdim": 0, "n_athar": 6, "qailun": [["ابن عباس", "صحابي"], ["ابن زيد", "تابع التابعين"]], "athar": [41643, 41644, 41645, 41646, 41647, 41648, 41650, 41651, 41652, 41674]}, {"n": 4, "t": "هم بنو امرأة الرجل من غيره", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [41643, 41644, 41645, 41646, 41647, 41648, 41650, 41651, 41652]}]}, "mawaqif": [{"taliq": 3707, "mi": 1, "aya": 72, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 383", "qawl": "الثالث", "nass": "وقالت فرقة: الحفدة: هم البنون. وهذا يستقيم على أن تكون الواو عاطفة صفة لهم، كما لو قال: جعلنا لهم بنين وأعوانا، أي: وهم لهم أعوان، فكأنه قال: وهم حفدة", "qawaid": [], "tabi": ""}, {"taliq": 3707, "mi": 1, "aya": 72, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 303 - 304 بتصرف", "qawl": "", "nass": "والحفدة في كلام العرب: جمع حافد، والحافد في كلامهم: هو المتخفف في الخدمة والعمل، والحفد: خفة العمل، يقال: مر البعير يحفد حفدانا: إذا مر يسرع في سيره، ومنه قولهم: إليك نسعى ونحفد، أي: نسرع إلى العمل بطاعتك … وإذ كان معنى الحفدة ما ذكرنا من أنهم المسرعون في خدمة الرجل المتخففون فيها، وكان أولادنا وأزواجنا الذين يصلحون للخدمة منا ومن غيرنا، وأختاننا الذين هم أزواج بناتنا من أزواجنا، وخدمنا من مماليكنا، إذا كانوا يحفدوننا فيستحقون اسم حفدة، ولم يكن الله تعالى دل بظاهر تنزيله ولا على لسان رسوله صلى الله عليه وسلم ولا بحجة عقل على أنه عنى بذلك نوعا من الحفدة دون نوع منهم، وكان قد أنعم بكل ذلك علينا؛ لم يكن لنا أن نوجه ذلك إلى خاص من الحفدة دون عام، إلا ما اجتمعت الأمة عليه أنه غير داخل فيهم، وإذا كان ذلك كذلك فلكل الأقوال التي ذكرنا عمن ذكرنا وجه في الصحة، ومخرج في التأويل، وإن كان أولى بالصواب من القول ما اخترنا لما بينا من الدليل", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3707, "mi": 1, "aya": 72, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 383 - 384", "qawl": "", "nass": "ولا خلاف أن معنى الحفد: الخدمة، والبر، والمشي مسرعا في الطاعة، ومنه في القنوت: «وإليك نسعى ونحفد", "qawaid": [], "tabi": ""}, {"taliq": 3707, "mi": 1, "aya": 72, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "8/ 332 - 333", "qawl": "", "nass": "فمن جعل {وحفدة} متعلقا ب {أزواجكم} فلا بد أن يكون المراد: الأولاد، وأولاد الأولاد، والأصهار؛ لأنهم أزواج البنات، وأولاد الزوجة. وكما قال الشعبي والضحاك، فإنهم غالبا يكونون تحت كنف الرجل، وفي حجره، وفي خدمته. وقد يكون هذا هو المراد من قوله عليه الصلاة والسلام في حديث بصرة بن أكثم: «والولد عبد لك", "qawaid": [], "tabi": ""}], "mushid": {"i": 11, "imgs": ["016_011_1.png"], "pages": [318], "n": 4, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3707, "masala": "المعني بالحفدة", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الأختان", "ashab": "", "athar": []}, {"n": 2, "t": "أعوان الرجل وخدمه", "ashab": "", "athar": []}, {"n": 3, "t": "ولد الرجل، وولد ولده", "ashab": "", "athar": []}, {"n": 4, "t": "بنو امرأة الرجل من غيره", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن عطية", "w"]]}, "t": {"3": [["ابن عطية", "w"]]}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 74, "title": "في الناصب قوله: ﴿شيئا﴾", "tabari": {"page": "14/306", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هو منصوب على البدل من \"الرزق\"، وهو في معنى: لا يملكون رزقا قليلا ولا كثيرا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "نصب ﴿شيئا﴾ بوقوع \"الرزق\" عليه، كما قال تعالى ذكره: ﴿ألم نجعل الأرض كفاتا (٢٥) أحياء وأمواتا﴾ [المرسلات: ٢٥، ٢٦]. أي: تكفت الأحياء والأموات. ومثله قوله تعالى ذكره: ﴿أو إطعام في يوم ذي مسغبة (١٤) يتيما ذا مقربة (١٥) أو مسكينا ذا متربة﴾ [البلد: ١٤ - ١٦]. قال: ولو كان الرزق مع الشيء لجاز خفضه: لا يملك لهم رزق شيء من السماوات", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 75, "title": "هذا المثل", "mawsua": {"taliq": 3709, "masala": "هذا المثل", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه مثل ضربه الله? لنفسه، وللأوثان؛ فالله? هو المالك لكل شيء، وينفق كيف يشاء، والأوثان مملوكة عاجزة، لا تقدر على شيء، فهل يستوى هذا وهذا؟!", "ashab": "مجاهد، والضحاك", "athar": [41695]}, {"n": 2, "t": "أنه مثل ضربه الله عز وجل للمؤمن والكافر؛ فالعبد المملوك الذي لا يقدر على شيء مثل الكافر، والمرزوق الرزق الحسن فهو ينفق منه سرا وجهرا هو المؤمن", "ashab": "ابن عباس، وقتادة", "athar": [41691, 41693, 41694, 41703, 41704, 41711, 41712, 41706]}]}, "mawaqif": [{"taliq": 3709, "mi": 1, "aya": 75, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الأول", "nass": "", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3709, "mi": 1, "aya": 75, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "4/ 170", "qawl": "الأول", "nass": "", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": "ابن عطية"}, {"taliq": 3709, "mi": 1, "aya": 75, "alam": "ابن القيم", "fil": "وكذا", "kind": "موافقة", "ref": "", "qawl": "", "nass": "", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": "ابن تيمية"}, {"taliq": 3709, "mi": 1, "aya": 75, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 388", "qawl": "", "nass": "هذا التأويل أصوب؛ لأن الآية تكون من معنى ما قبلها وبعدها في تبيين أمر الله والرد على الأصنام", "qawaid": [], "tabi": ""}, {"taliq": 3709, "mi": 1, "aya": 75, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "2/ 114 - 115", "qawl": "", "nass": "القول الأول أشبه بالمراد؛ فإنه أظهر في بطلان الشرك، وأوضح عند المخاطب، وأعظم في إقامة الحجة، وأقرب نسبا بقوله: {ويعبدون من دون الله ما لا يملك لهم رزقا من السماوات والأرض شيئا ولا يستطيعون فلا تضربوا لله الأمثال إن الله يعلم وأنتم لا تعلمون}، ثم قال: {ضرب الله مثلا عبدا مملوكا لا يقدر على شيء}، ومن لوازم هذا المثل وأحكامه أن يكون المؤمن الموحد كمن رزقه منه رزقا حسنا، والكافر المشرك كالعبد المملوك الذي لا يقدر على شيء، فهذا مما نبه عليه المثل، وأرشد إليه، فذكره ابن عباس منبها على إرادته، لا أن الآية اختصت به، فتأمله فإنك تجده كثيرا في كلام ابن عباس، وغيره من السلف في فهم القرآن، فيظن الظان أن ذلك هو معنى الآية التي لا معنى لها غيره، فيحكيه قوله", "qawaid": [], "tabi": ""}, {"taliq": 3709, "mi": 1, "aya": 75, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 307", "qawl": "الثاني", "nass": "إنما اخترنا القول الذي اخترناه في المثل الأول لأنه -تعالى ذكره- مثل مثل الكافر بالعبد الذي وصف صفته، ومثل مثل المؤمن بالذي رزقه رزقا حسنا فهو ينفق مما رزقه سرا وجهرا، فلم يجز أن يكون ذلك لله مثلا؛ إذ كان الله إنما مثل الكافر الذي لا يقدر على شيء بأنه لم يرزقه رزقا ينفق منه سرا، ومثل المؤمن الذي وفقه الله لطاعته فهداه لرشده فهو يعمل بما يرضاه الله، كالحر الذي بسط له في الرزق فهو ينفق منه سرا وجهرا، والله -تعالى ذكره- هو الرازق غير المرزوق، فغير جائز أن يمثل إفضاله وجوده بإنفاق المرزوق الرزق الحسن", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3709, "mi": 1, "aya": 75, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 388", "qawl": "الثاني", "nass": "التمثيل على هذا التأويل إنما وقع في جهة الكافر فقط، جعل له مثلا، ثم قرن بالمؤمن المرزوق، إلا أن يكون المرزوق ليس بمؤمن، وإنما هو مثال للمؤمن، فيقع التمثيل من جهتين", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن عطية", "r"], ["ابن تيمية", "r"], ["ابن القيم", "r"]], "2": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["السياق", "الدلالة العقلية"], "ابن تيمية": ["السياق", "الدلالة العقلية"], "ابن القيم": ["السياق", "الدلالة العقلية"], "ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 76, "title": "هذا المثل", "mawsua": {"taliq": 3711, "masala": "هذا المثل", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه مثل ضربه الله? لنفسه، وللأصنام", "ashab": "قتادة، ومجاهد، والضحاك", "athar": [41740, 41720]}, {"n": 2, "t": "أنه مثل ضربه الله عز وجل للمؤمن، والكافر", "ashab": "ابن عباس", "athar": [41738, 41739]}]}, "mawaqif": [{"taliq": 3711, "mi": 1, "aya": 76, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 313", "qawl": "الأول", "nass": "أما المثل الثاني فإنه تمثيل منه -تعالى ذكره- من مثله الأبكم الذي لا يقدر على شيء، والكفار لا شك أن منهم من له الأموال الكثيرة، ومن يضر أحيانا الضر العظيم بفساده، فغير كائن ما لا يقدر على شيء، كما قال -تعالى ذكره- مثلا لمن يقدر على أشياء كثيرة، فإذا كان ذلك كذلك كان أولى المعاني به تمثيل ما لا يقدر على شيء كما قال -تعالى ذكره- بمثله ما لا يقدر على شيء، وذلك الوثن الذي لا يقدر على شيء بالأبكم الكل على مولاه الذي لا يقدر على شيء كما قال ووصف", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3711, "mi": 1, "aya": 76, "alam": "ابن تيمية", "fil": "ذهب", "kind": "قول", "ref": "4/ 171", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3711, "mi": 1, "aya": 76, "alam": "ابن القيم", "fil": "ذهب", "kind": "قول", "ref": "2/ 115", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن تيمية"}], "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 81, "title": "سبب نزول: ﴿كذلك يتم نعمته عليكم لعلكم تسلمون﴾", "tabari": {"page": "14/324", "sarih": 0, "tarjih": "وأولى القولين في ذلك بالصواب قول من قال: إن القوم خوطبوا على قدر معرفتهم، وإن كان في ذكر بعض ذلك دلالة على ما ترك ذكره، لمن عرف المذكور والمتروك، وذلك أن الله تعالى ذكره إنما عدد نعمه التي أنعمها على الذين قصدوا بالذكر في هذه السورة دون غيرهم، فذكر أياديه عندهم.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "قيل له: قد اختلف في السبب الذي من أجله جاء التنزيل كذلك، وسنذكر ما قيل في ذلك، ثم ندل على أولى الأقوال في ذلك بالصواب.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "ذكر ذلك خاصة اكتفاء بذكر أحدهما من ذكر الآخر؛ إذ كان معلوما عند المخاطبين به معناه، وأن السرابيل التي تقى الحر تقى أيضا البرد. وقالوا: ذلك موجود في كلام العرب مستعمل، واستشهدوا لقولهم بقول الشاعر :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3716, "mi": 0, "aya": 81, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 393", "qawl": "", "nass": "ذكر وقاية الحر إذ هو أمس في تلك البلاد على ما ذكرنا، والبرد فيها معدوم في الأكثر، وإذا جاء في الشتوات فإنما يتوقى بما هو أكثف من السربال من الأثاث المتقدم الذكر، فتبقى السرابيل لتوقي الحر فقط. قاله الطبري عن عطاء الخراساني. ألا ترى أن الله قد نبههم إلى العبرة في البرد، ولم يذكر لهم الثلج؛ لأنه ليس في بلادهم، قال ابن عباس: إن الثلج شيء أبيض ينزل من السماء ما رأيته قط. وأيضا فذكر أحدهما يدل على الآخر", "qawaid": [], "tabi": ""}, {"taliq": 3716, "mi": 0, "aya": 81, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "14/ 324", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 3716, "mi": 0, "aya": 81, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "4/ 173 - 174", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 12, "imgs": ["016_012_1.png"], "pages": [318], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن تيمية", "r"], ["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 83, "title": "في المعني بالنعمة التي أخبر الله تعالى ذكره عن هؤلاء المشركين أنهم ينكرونها مع معرفتهم بها", "tabari": {"page": "14/325", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب، وأشبهها بتأويل الآية قول من قال: عنى بالنعمة التي ذكرها الله في قوله: ﴿يعرفون نعمت الله﴾. النعمة عليهم بإرسال محمد ﷺ إليهم، داعيا إلى ما بعثه بدعائهم إليه، وذلك أن هذه الآية بين آيتين، كلتاهما خبر عن رسول الله، وعما بعث به، فأولى ما بينهما أن يكون في معنى ما قبله وما بعده، إذ لم يكن معنى يدل على انصرافه عما قبله وعما بعده، فالذى قبل هذه الآية قوله: ﴿فإن تولوا فإنما عليك البلاغ المبين (٨٢) يعرفون نعمت الله ثم ينكرونها﴾، وما بعده ﴿ويوم نبعث من كل أمة شهيدا﴾، وهو رسولها. فإذ كان ذلك كذلك، فمعنى الآية: يعرف هؤلاء المشركون بالله نعمة الله عليهم يا محمد بك، ثم ينكرونك، ويجحدون نبوتك، ﴿وأكثرهم الكافرون﴾. يقول: وأكثر قومك الجاحدون نبوتك، لا المقرون بها.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "هو النبي ﷺ، عرفوا نبوته، ثم جحدوها وكذبوه", "taqdim": 0, "n_athar": 2, "qailun": [["السدي", "تابعي"]], "athar": [41837, 41838]}, {"n": 2, "t": "بل معني ذلك: أنهم يعرفون أن ما عدد الله تعالى ذكره في هذه السورة من النعم من عند الله، وأن الله هو المنعم بذلك عليهم، ولكنهم ينكرون ذلك، فيزعمون أنهم ورثوه عن آبائهم", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"]], "athar": [41831, 41832, 41833]}, {"n": 3, "t": "ثنا معاوية، عن عمرو، عن أبي إسحاق الفزاري، عن ليث، عن عون بن عبد الله بن عتبة: ﴿يعرفون نعمت الله ثم ينكرونها﴾، قال: إنكارهم إياها، أن يقول الرجل: لولا فلان ما كان كذا وكذا، ولولا فلان ما أصبت كذا وكذا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "معنى ذلك أن الكفار إذا قيل لهم: من رزقكم؟ أقروا بأن الله هو الذي رزقهم، ثم ينكرون ذلك بقولهم: رزقنا ذلك بشفاعة آلهتنا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3720, "mi": 1, "aya": 83, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 326 - 327", "qawl": "الرابع", "nass": "وذلك أن هذه الآية بين آيتين كلتاهما خبر عن رسول الله صلى الله عليه وسلم وعما بعث به، فأولى ما بينهما أن يكون في معنى ما قبله وما بعده؛ إذ لم يكن معنى يدل على انصرافه عما قبله وعما بعده، فالذي قبل هذه الآية قوله: {فإن تولوا فإنما عليك البلاغ المبين يعرفون نعمة الله ثم ينكرونها} وما بعده: {ويوم نبعث من كل أمة شهيدا} وهو رسولها. فإذ كان ذلك كذلك فمعنى الآية: يعرف هؤلاء المشركون بالله نعمة الله عليهم يا محمد بك، ثم ينكرونك ويجحدون نبوتك", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 13, "imgs": ["016_013_1.png"], "pages": [319], "n": 4, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3720, "masala": "تأويل قوله تعالى: {يعرفون نعمت الله ثم ينكرونها}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن النعمة: ما ذكر في هذه السورة، وإنكارها: قولهم: ورثناها عن آبائنا", "ashab": "مجاهد", "athar": [41832]}, {"n": 2, "t": "أن النعمة: ما ذكر في هذه السورة، وإنكارها: قولهم: لولا فلان ما كان كذا وكذا، ولولا فلان ما أصبت كذا وكذا", "ashab": "عون بن عبد الله", "athar": [41835]}, {"n": 3, "t": "أن النعمة: ما ذكر في هذه السورة، وإنكارها: قولهم: هذه بشفاعة آلهتنا", "ashab": "الكلبي، وغيره", "athar": [41839]}, {"n": 4, "t": "أن النعمة: نبوة محمد صلى الله عليه وسلم، وإنكارها: جحد نبوته وتكذيبه", "ashab": "السدي", "athar": [41837, 41838]}]}, "tags": {"m": {"4": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 91, "title": "تأويل: ﴿وقد جعلتم الله عليكم كفيلا﴾", "tabari": {"page": "14/339", "sarih": 0, "tarjih": "والصواب من القول فى ذلك أن يقال: إن الله تعالى ذكره أمر في هذه الآية عباده بالوفاء بعهوده، التى يجعلونها على أنفسهم، ونهاهم عن نقض الأيمان بعد توكيدها على أنفسهم لآخرين، بعقود تكون بينهم بحق، مما لا يكرهه الله.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿وقد جعلتم الله عليكم كفيلا﴾. يقول: وقد جعلتم الله بالوفاء بما تعاقدتم عليه على أنفسكم راعيا، يرعى الموفي منكم بعهد الله الذي عاهد على الوفاء به والناقض.", "taqdim": 1, "n_athar": 1, "qailun": [], "athar": []}, {"n": 2, "t": "نزلت فى الحلف الذى كان أهل الشرك تحالفوا في الجاهلية، فأمرهم الله ﷿ فى الإسلام أن يوفوا به، ولا ينقضوه", "taqdim": 0, "n_athar": 5, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"], ["قول الله تعالى ذكره", ""]], "athar": [41952, 41953, 41955, 41957, 41960, 41961, 41967]}]}, "mawaqif": [{"taliq": 3734, "mi": 1, "aya": 91, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 402", "qawl": "الثاني", "nass": "كما قال صلى الله عليه وسلم: «لا حلف في الإسلام، وما كان من حلف في الجاهلية فلم يزده الإسلام إلا شدة»", "qawaid": [], "tabi": ""}, {"taliq": 3734, "mi": 1, "aya": 91, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 340 - 341", "qawl": "العموم", "nass": "الصواب من القول في ذلك أن يقال: إن الله تعالى أمر في هذه الآية عباده بالوفاء بعهوده التي يجعلونها على أنفسهم، ونهاهم عن نقض الأيمان بعد توكيدها على أنفسهم لآخرين بعقود تكون بينهم بحق مما لا يكرهه الله. وجائز أن تكون نزلت في الذين بايعوا رسول الله صلى الله عليه وسلم بنهيهم عن نقض بيعتهم حذرا من قلة عدد المسلمين وكثرة عدد المشركين، وأن تكون نزلت في الذين أرادوا الانتقال بحلفهم عن حلفائهم لقلة عددهم في آخرين لكثرة عددهم. وجائز أن تكون في غير ذلك. ولا خبر تثبت به الحجة أنها نزلت في شيء من ذلك دون شيء، ولا دلالة في كتاب، ولا حجة عقل أي ذلك عني بها، ولا قول في ذلك أولى بالحق مما قلنا؛ لدلالة ظاهره عليه، وأن الآية كانت قد تنزل لسبب من الأسباب، ويكون الحكم بها عاما في كل ما كان بمعنى السبب الذي نزلت فيه", "qawaid": [], "tabi": ""}, {"taliq": 3734, "mi": 1, "aya": 91, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 402", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 14, "imgs": ["016_014_1.png"], "pages": [319], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3734, "masala": "من عني بهذه الآية، وفيم أنزلت", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه عني بها: الذين بايعوا رسول الله صلى الله عليه وسلم على الإسلام، وفيهم أنزلت", "ashab": "", "athar": []}, {"n": 2, "t": "أنها نزلت في الحلف الذي كان أهل الشرك؛ تحالفوا في الجاهلية، فأمرهم الله عز وجل في الإسلام أن يوفوا به ولا ينقضوه", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح العموم"], ["ابن عطية", "رجّح العموم"]], "rules": {}, "rulesD": {}}}, {"aya": 92, "title": "تأويل: ﴿ولا تكونوا كالتي نقضت غزلها من بعد قوة أنكاثا تتخذون أيمانكم دخلا بينكم أن تكون أمة هي أرب﴾", "tabari": {"page": "14/342", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره - ناهيا عباده عن نقض الأيمان بعد توكيدها، وآمرا بوفاء العهود، وممثلا ناقض ذلك بناقضة غزلها من بعد إبرامه، وناكثته من بعد إحكامه -: ﴿ولا تكونوا﴾ أيها الناس في نقضكم أيمانكم بعد توكيدها، وإعطائكم الله بالوفاء بذلك العهود والمواثيق، ﴿كالتي نقضت غزلها من بعد قوة﴾، يعنى: من بعد إبرام.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إن التي كانت تفعل ذلك امرأة حمقاء معروفة بمكة", "taqdim": 0, "n_athar": 2, "qailun": [["ابن جريج", "تابع التابعين"], ["السدى", "تابعي"]], "athar": [41974, 41996]}, {"n": 3, "t": "إنما هذا مثل ضربه الله لمن نقض العهد، فشبهه بامرأة تفعل هذا الفعل، وقالوا: فى معنى: ﴿نقضت غزلها من بعد قوة﴾، نحوا مما قلنا", "taqdim": 0, "n_athar": 5, "qailun": [["مجاهد", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [41979, 41989, 41993, 41997]}]}, "mawaqif": [{"taliq": 3735, "mi": 0, "aya": 91, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 348 - 349", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3735, "mi": 0, "aya": 91, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 405", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3735, "mi": 0, "aya": 91, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "هذه الآية تدل على أن تأويل بريدة الذي ذكرنا عنه في قوله: {وأوفوا بعهد الله إذا عاهدتم} والآيات التي بعدها أنه عني بذلك: الذين بايعوا رسول الله صلى الله عليه وسلم على الإسلام، عن مفارقة الإسلام لقلة أهله، وكثرة أهل الشرك [يعني: أمرهم بالوفاء بالعهد؛ لئلا ينقضوه لقلة أهل الإسلام، وكثرة أهل الشرك] هو الصواب، دون الذي قال مجاهد أنهم عنوا به؛ لأنه ليس في انتقال قوم تحالفوا عن حلفائهم إلى آخرين غيرهم صد عن سبيل الله، ولا ضلال عن الهدى، وقد وصف -تعالى ذكره- في هذه الآية فاعلي ذلك أنهم باتخاذهم الأيمان دخلا بينهم، ونقضهم الأيمان بعد توكيدها؛ صادون عن سبيل الله، وأنهم أهل ضلال في التي قبلها، وهذه صفة أهل الكفر بالله، لا صفة أهل النقلة بالحلف عن قوم إلى قوم", "qawaid": [], "tabi": ""}, {"taliq": 3735, "mi": 0, "aya": 91, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "وقوله: {بما صددتم عن سبيل الله} يدل على أن الآية فيمن بايع رسول الله صلى الله عليه وسلم", "qawaid": [], "tabi": ""}, {"taliq": 3738, "mi": 0, "aya": 92, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "14/ 344", "qawl": "", "nass": "الدخل في كلام العرب: كل أمر لم يكن صحيحا", "qawaid": [], "tabi": ""}, {"taliq": 3738, "mi": 0, "aya": 92, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 403", "qawl": "", "nass": "الدخل: الدغل بعينه، وهي الذرائع إلى الخدع والغدر، وذلك أن المحلوف له مطمئن فيتمكن الحالف من ضره بما يريده", "qawaid": [], "tabi": ""}], "mushid": {"i": 15, "imgs": ["016_015_1.png"], "pages": [319], "n": 2, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"], ["ابن عطية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {}, "rulesD": {}}}, {"aya": 97, "title": "تأويل: ﴿من عمل صالحا من ذكر أو أنثى وهو مؤمن فلنحيينه حياة طيبة ولنجزينهم أجرهم بأحسن ما كانوا يعم﴾", "tabari": {"page": "14/352", "sarih": 0, "tarjih": "وأولى هذه الأقوال بالصواب قول من قال: تأويل ذلك: فلنحيينه حياة طيبة بالقناعة؛ وذلك أن من قنعه الله بما قسم له من رزق، لم يكثر [في الدنيا] تعبه، ولم يعظم فيها نصبه، ولم يتكدر فيها عيشه، بإتباعه نفسه ما فاته منها، وحرصه على ما لعله لا يدركه فيها.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: من عمل بطاعة الله، وأوفى بعهود الله إذا عاهد، ﴿من ذكر أو أنثى﴾ من بني آدم، ﴿وهو مؤمن﴾. يقول: وهو مصدق بثواب الله الذى وعد أهل طاعته على الطاعة، وبوعيد أهل معصيته على المعصية، ﴿فلنحيينه حياة طيبة﴾.", "taqdim": 1, "n_athar": 8, "qailun": [["ابن عباس", "صحابي"], ["الضحاك", "تابعي"], ["الضحاك فى", "تابعي"]], "athar": [42028, 42029, 42030, 42031, 42036, 42037, 42050]}, {"n": 2, "t": "﴿فلنحيينه حياة طيبة﴾، بأن نرزقه القناعة", "taqdim": 0, "n_athar": 2, "qailun": [["علي", "صحابي"], ["الحسن البصري", "تابعي"]], "athar": [42027, 42038, 42039, 42040]}, {"n": 3, "t": "بل يعنى بالحياة الطيبة الحياة مؤمنا بالله، عاملا بطاعته", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 4, "t": "الحياة الطيبة السعادة", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [42028, 42029, 42030, 42031, 42050]}, {"n": 5, "t": "بل معنى ذلك: الحياة في الجنة", "taqdim": 0, "n_athar": 6, "qailun": [["الحسن", "تابعي"], ["قتادة", "تابعي"], ["مجاهد", "تابعي"], ["ابن زيد", "تابع التابعين"], ["الربيع", "تابعي"]], "athar": [42025, 42035, 42038, 42039, 42040, 42042, 42047]}]}, "mawaqif": [{"taliq": 3741, "mi": 1, "aya": 97, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 354 - 355", "qawl": "الثاني", "nass": "أولى الأقوال بالصواب قول من قال: تأويل ذلك: فلنحيينه حياة طيبة بالقناعة. وذلك أن من قنعه الله بما قسم له من رزق لم يكثر للدنيا تعبه، ولم يعظم فيها نصبه، ولم يتكدر فيها عيشه باتباعه بغية ما فاته منها، وحرصه على ما لعله لا يدركه فيها. وإنما قلت ذلك أولى التأويلات في ذلك بالآية لأن الله -تعالى ذكره- أوعد قوما قبلها على معصيتهم إياه إن عصوه أذاقهم السوء في الدنيا والعذاب في الآخرة، فقال تعالى: {ولا تتخذوا أيمانكم دخلا بينكم فتزل قدم بعد ثبوتها، وتذوقوا السوء بما صددتم عن سبيل الله} فهذا لهم في الدنيا، {ولكم} في الآخرة {عذاب عظيم} فهذا لهم في الآخرة، ثم أتبع ذلك ما لمن أوفى بعهد الله وأطاعه، فقال تعالى: {ما عندكم} في الدنيا {ينفد وما عند الله باق}، فالذي أوعد أهل المعاصي بإذاقتهم هذه السيئة بحكمته أراد أن يعقب ذلك الوعد لأهل طاعته بالإحسان في الدنيا، والغفران في الآخرة، وكذلك فعل -تعالى ذكره-", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3741, "mi": 1, "aya": 97, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 406", "qawl": "الخامس", "nass": "هناك هو الطيب على الإطلاق، ولكن ظاهر هذا الوعد أنه في الدنيا", "qawaid": [], "tabi": ""}, {"taliq": 3741, "mi": 1, "aya": 97, "alam": "ابن كثير", "fil": "ذهب", "kind": "قول", "ref": "8/ 352 - 353 بتصرف", "qawl": "", "nass": "الصحيح أن الحياة الطيبة تشمل هذا كله، كما جاء في الحديث أن رسول الله صلى الله عليه وسلم قال: «قد أفلح من أسلم، ورزق كفافا، وقنعه الله بما آتاه", "qawaid": ["السنة"], "tabi": ""}], "mushid": {"i": 16, "imgs": ["016_016_1.png"], "pages": [320], "n": 5, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 3741, "masala": "المراد بالحياة الطيبة", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن المراد: أنه تعالى يحييهم في الدنيا ما عاشوا فيها بالرزق الحلال", "ashab": "", "athar": []}, {"n": 2, "t": "أن المراد: أنه تعالى يرزقهم في الدنيا القناعة", "ashab": "", "athar": []}, {"n": 3, "t": "أن المراد: أنه تعالى يحييهم في الدنيا حياة مؤمنين به عاملين بطاعته", "ashab": "", "athar": []}, {"n": 4, "t": "أن المراد: أنه تعالى يحييهم في الدنيا سعداء", "ashab": "", "athar": []}, {"n": 5, "t": "أن المراد بالحياة الطيبة: حياة الآخرة، ونعيم الجنة", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق", "الدلالة العقلية"], "ابن كثير": ["السنة"]}, "rulesD": {}}}, {"aya": 97, "title": "تأويل: ﴿ولنجزينهم أجرهم بأحسن ما كانوا يعملون﴾", "tabari": {"page": "14/356", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿ولنجزينهم أجرهم بأحسن ما كانوا يعملون﴾، فذلك لا شك أنه في الآخرة، وكذلك قال أهل التأويل.", "taqdim": 1, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"]], "athar": [42028, 42029, 42030, 42031, 42050]}, {"n": 2, "t": "إن هذه الآية نزلت بسبب قوم من أهل ملل شتى تفاخروا، فقال أهل كل ملة منها: نحن أفضل. فبين الله لهم أفضل أهل الملل", "taqdim": 0, "n_athar": 1, "qailun": [["أبي صالح", "تابعي"]], "athar": [42023]}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 98, "title": "حكم الاستعاذة أواجبة هي، أو مندوبة؟", "mawsua": {"taliq": 3742, "masala": "حكم الاستعاذة أواجبة هي، أو مندوبة؟", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": []}, "mawaqif": [{"taliq": 3742, "mi": 0, "aya": 98, "alam": "ابن عطية", "fil": "ذهب", "kind": "قول", "ref": "5/ 407", "qawl": "", "nass": "", "qawaid": ["القرآن والنظائر", "السنة", "أقوال السلف"], "tabi": ""}, {"taliq": 3742, "mi": 0, "aya": 98, "alam": "ابن كثير", "fil": "ذهب", "kind": "قول", "ref": "8/ 353", "qawl": "", "nass": "", "qawaid": ["القرآن والنظائر", "السنة", "أقوال السلف"], "tabi": "ابن عطية"}, {"taliq": 3742, "mi": 0, "aya": 98, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "تقدير الآية: فإذا أخذت في قراءة القرآن. كما قال عز وجل: {إذا قمتم إلى الصلاة فاغسلوا وجوهكم} [المائدة: 6]، وكما تقول لرجل: إذ أكلت فقل: بسم الله", "qawaid": [], "tabi": ""}, {"taliq": 3742, "mi": 0, "aya": 98, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "الصحيح الأول؛ لما تقدم من الأحاديث الدالة على تقدمها على التلاوة", "qawaid": [], "tabi": ""}, {"taliq": 3742, "mi": 0, "aya": 98, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "وكأن من قال: إن الاستعاذة بعد القراءة. لاحظ هذا المعنى [يعني: بقاء فائدة القرآن، وحفظها، وثباتها]، وهو لعمر الله ملحظ جيد، إلا أن السنة وآثار الصحابة إنما جاءت بالاستعادة قبل الشروع في القراءة، وهو قول جمهور الأمة من السلف والخلف", "qawaid": [], "tabi": ""}, {"taliq": 3742, "mi": 0, "aya": 98, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "14/ 357", "qawl": "", "nass": "إذا كنت -يا محمد- قارئا القرآن؛ فاستعذ بالله من الشيطان الرجيم", "qawaid": [], "tabi": ""}, {"taliq": 3742, "mi": 1, "aya": 98, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "", "qawl": "", "nass": "", "qawaid": ["الإجماع", "أقوال السلف"], "tabi": ""}, {"taliq": 3742, "mi": 1, "aya": 98, "alam": "ابن عطية", "fil": "ذهب", "kind": "قول", "ref": "", "qawl": "", "nass": "", "qawaid": ["الإجماع", "أقوال السلف"], "tabi": "ابن جرير"}, {"taliq": 3742, "mi": 1, "aya": 98, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "14/ 357", "qawl": "", "nass": "ليس قوله: {فاستعذ بالله من الشيطان الرجيم} بالأمر اللازم، وإنما هو إعلام وندب، وذلك أنه لا خلاف بين الجميع أن من قرأ القرآن ولم يستعذ بالله من الشيطان الرجيم قبل قراءته أو بعدها أنه لم يضيع فرضا واجبا. وكان ابن زيد يقول في ذلك نحو الذي قلنا", "qawaid": [], "tabi": ""}, {"taliq": 3742, "mi": 1, "aya": 98, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 407", "qawl": "", "nass": "الاستعاذة ندب عند الجميع", "qawaid": [], "tabi": ""}, {"taliq": 3742, "mi": 1, "aya": 98, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "8/ 353", "qawl": "", "nass": "وهذا أمر ندب ليس بواجب، حكى الإجماع على ذلك أبو جعفر ابن جرير، وغيره من الأئمة", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {"ابن عطية": ["القرآن والنظائر", "السنة", "أقوال السلف", "الإجماع"], "ابن كثير": ["القرآن والنظائر", "السنة", "أقوال السلف"], "ابن جرير": ["الإجماع", "أقوال السلف"]}, "rulesD": {}}}, {"aya": 99, "title": "تأويل: ﴿إنه ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون﴾", "tabari": {"page": "14/359", "sarih": 0, "tarjih": "وأولى الأقوال فى ذلك بالصواب قول من قال: معناه: إنه ليس له سلطان على الذين آمنوا، فاستعاذوا بالله منه؛ بما ندب الله تعالى ذكره من الاستعاذة، وعلى ربهم يتوكلون على ما عرض لهم من خطراته ووساوسه.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "وأما قوله: ﴿إنه ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون﴾. فإنه يعنى بذلك: إن الشيطان ليست له حجة على الذين آمنوا بالله ورسوله، وعملوا بما أمر الله به، وانتهوا عما نهاهم الله عنه، ﴿وعلى ربهم يتوكلون﴾. يقول: وعلى ربهم يتوكلون، فيما نابهم من مهمات أمورهم، ﴿إنما سلطانه على الذين يتولونه﴾. يقول: إنما حجته على الذين يعبدونه، ﴿والذين هم به مشركون﴾. يقول: والذين هم بالله مشركون.", "taqdim": 1, "n_athar": 2, "qailun": [["مجاهد", "تابعي"]], "athar": []}, {"n": 2, "t": "هو الاستعاذة، فإنه إذا استعاذ بالله منع منه، ولم يسلط عليه. واستشهدوا لصحة قولهم ذلك بقول الله تعالى ذكره: ﴿وإما ينزغنك من الشيطان نزغ فاستعذ بالله إنه سميع عليم﴾ [الأعراف: ٢٠٠]. وقد ذكرنا الرواية بذلك في سورة \"الحجر\"", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "ثنا إسحاق، قال: ثنا عبد الله بن أبي جعفر، عن أبيه، عن الربيع في قوله: ﴿إنه ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون﴾ إلى قوله: ﴿والذين هم به مشركون﴾. قال: إن عدو الله إبليس قال: ﴿لأغوينهم أجمعين (٨٢) إلا عبادك منهم المخلصين﴾ [ص: ٨٢، ٨٣] فهؤلاء الذين لم يجعل للشيطان عليهم سبيل، وإنما سلطانه على قوم اتخذوه وليا، وأشركوه في أعمالهم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3744, "mi": 1, "aya": 100, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 361 - 362", "qawl": "الأول", "nass": "ذلك أن الذين يتولون الشيطان إنما يشركونه بالله في عبادتهم، وذبائحهم، ومطاعمهم، ومشاربهم، لا أنهم يشركون بالشيطان، ولو كان معنى الكلام ما قاله الربيع لكان التنزيل: الذين هم مشركوه. ولم يكن في الكلام {به}، فكان يكون لو كان التنزيل كذلك: والذين هم مشركوه في أعمالهم، إلا أن يوجه موجه معنى الكلام إلى أن القوم كانوا يدينون بألوهة الشيطان، ويشركون الله به في عبادتهم إياه، فيصح حينئذ معنى الكلام، ويخرج عما جاء التنزيل به في سائر القرآن، وذلك أن الله تعالى وصف المشركين في سائر سور القرآن أنهم أشركوا بالله ما لم ينزل به عليهم سلطانا، وقال في كل موضع تقدم إليهم بالزجر عن ذلك: لا تشركوا بالله شيئا، ولم نجد في شيء من التنزيل: لا تشركوا الله بشيء، ولا في شيء من القرآن خبرا من الله عنهم أنهم أشركوا الله بشيء، فيجوز لنا توجيه معنى قوله: {والذين هم به مشركون} إلى: والذين هم بالشيطان مشركو الله، فبين إذا -إذ كان ذلك كذلك- أن الهاء في قوله: {والذين هم به} عائدة على", "qawaid": ["القرآن والنظائر"], "tabi": ""}, {"taliq": 3744, "mi": 1, "aya": 100, "alam": "ابن عطية", "fil": "ذهب", "kind": "قول", "ref": "5/ 407", "qawl": "الثالث", "nass": "الظاهر أنه يعود على اسم إبليس، بمعنى من أجله وبسببه، كما تقول لمعلمك: أنا عالم بك. أي: بسببك، فكأنه قال: والذين هم بسببه مشركون بالله", "qawaid": ["اللغة"], "tabi": ""}], "mushid": {"i": 17, "imgs": ["016_017_1.png"], "pages": [320], "n": 3, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 3744, "masala": "تأويل قوله تعالى: {والذين هم به مشركون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "والذين هم بالله مشركون", "ashab": "مجاهد، والضحاك", "athar": [42082, 42083]}, {"n": 2, "t": "مشركو الشيطان في أعمالهم", "ashab": "الربيع", "athar": [42085]}, {"n": 3, "t": "والذين هم لأجل الشيطان وبسببه مشركون", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]], "3": [["ابن عطية", "q"]]}, "t": {"1": [["ابن جرير", "r"]], "3": [["ابن عطية", "q"]], "2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["القرآن والنظائر"], "ابن عطية": ["اللغة"]}, "rulesD": {}}}, {"aya": 99, "title": "تأويل قوله تعالى: {إنه ليس له سلطان على الذين آمنوا}", "mawsua": {"taliq": 3743, "masala": "تأويل قوله تعالى: {إنه ليس له سلطان على الذين آمنوا}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه ليس له قدرة على أن يحملهم على ذنب لا يغفر", "ashab": "", "athar": []}, {"n": 2, "t": "أنه ليس له حجة على ما يدعوهم إليه من المعاصي", "ashab": "", "athar": []}, {"n": 3, "t": "أنه ليس له عليهم سلطان؛ لاستعاذتهم بالله منه", "ashab": "", "athar": []}, {"n": 4, "t": "أنه ليس له عليهم سلطان بحال؛ لأن الله تعالى صرف سلطانه عنهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3743, "mi": 1, "aya": 99, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 360", "qawl": "الثالث", "nass": "إنما قلنا ذلك أولى التأويلات بالآية لأن الله -تعالى ذكره- أتبع هذا القول: {فإذا قرأت القرآن فاستعذ بالله من الشيطان الرجيم}، وقال في موضع آخر: {وإما ينزغنك من الشيطان نزغ فاستعذ بالله، إنه سميع عليم} [الأعراف: 200]، فكان بينا بذلك أنه إنما ندب عباده إلى الاستعاذة منه في هذه الأحوال؛ ليعيذهم من سلطانه", "qawaid": ["السياق", "القرآن والنظائر", "القرآن والنظائر"], "tabi": ""}, {"taliq": 3743, "mi": 1, "aya": 99, "alam": "ابن القيم", "fil": "رجح", "kind": "ترجيح", "ref": "2/ 126", "qawl": "الرابع", "nass": "الصواب: أن يقال: ليس له طريق يتسلط به عليهم، لا من جهة الحجة، ولا من جهة القدرة. والقدرة داخلة في مسمى السلطان، وإنما سميت الحجة: سلطانا؛ لأن صاحبها يتسلط بها تسلط صاحب القدرة بيده، وقد أخبر سبحانه أنه لا سلطان لعدوه على عباده المخلصين المتوكلين، فقال في سورة الحجر [39 - 42]: {قال رب بما أغويتني لأزينن لهم في الأرض ولأغوينهم أجمعين إلا عبادك منهم المخلصين قال هذا صراط على مستقيم إن عبادي ليس لك عليهم سلطان إلا من اتبعك من الغاوين}، وقال في سورة النحل: {إنه ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون * إنما سلطانه على الذين يتولونه والذين هم به مشركون}، فتضمن ذلك أمرين: أحدهما: نفي سلطانه، وإبطاله على أهل التوحيد والإخلاص. والثاني: إثبات سلطانه على أهل الشرك، وعلى من تولاه", "qawaid": ["القرآن والنظائر"], "tabi": ""}], "tags": {"m": {"3": [["ابن جرير", "r"]], "4": [["ابن القيم", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["السياق", "القرآن والنظائر"], "ابن القيم": ["القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 100, "title": "في تأويله", "tabari": {"page": "14/360", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "إن معناه: والذين هم بالله مشركون", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"]], "athar": [42074, 42075, 42082]}, {"n": 2, "t": "معنى ذلك: والذين هم به مشركو الشيطان في أعمالهم", "taqdim": 0, "n_athar": 1, "qailun": [["الربيع", "تابعي"]], "athar": [42079, 42085]}]}, "mawaqif": [], "mushid": {"i": 18, "imgs": ["016_018_1.png"], "pages": [320], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 103, "title": "تأويل: ﴿ولقد نعلم أنهم يقولون إنما يعلمه بشر لسان الذي يلحدون إليه أعجمي وهذا لسان عربي مبين﴾", "tabari": {"page": "14/365", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ولقد نعلم أن هؤلاء المشركين يقولون، جهلا منهم: إنما يعلم محمدا هذا الذى يتلوه بشر من بنى آدم، وما هو من عند الله. يقول الله تعالى ذكره مكذبهم فى قيلهم ذلك: ألا تعلمون كذب ما تقولون. إن لسان الذى تلحدون إليه. يقول: تميلون إليه بأنه يعلم محمدا، أعجمي. وذلك أنهم، فيما ذكر، كانوا يزعمون أن الذى يعلم محمدا هذا القرآن عبد رومي؛ فلذلك قال تعالى: ﴿لسان الذي يلحدون إليه أعجمي وهذا لسان عرب", "taqdim": 1, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [42107, 42108]}, {"n": 2, "t": "اسمه يعيش", "taqdim": 0, "n_athar": 2, "qailun": [["عكرمة", "تابعي"], ["قتادة", "تابعي"]], "athar": [42116, 42117]}, {"n": 3, "t": "بل كان اسمه جبر", "taqdim": 0, "n_athar": 2, "qailun": [["ابن إسحاق", "تابع التابعين"], ["ابن جريج", "تابع التابعين"]], "athar": [42122]}, {"n": 4, "t": "بل كانا غلامين؛ اسم أحدهما يسار، والآخر جبر", "taqdim": 0, "n_athar": 3, "qailun": [["لأحدهما", ""], ["عبد الله بن مسلم", ""]], "athar": []}, {"n": 5, "t": "بل كان ذلك سلمان الفارسي", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"]], "athar": [42111, 42127]}, {"n": 6, "t": "إن الذى قال ذلك: رجل كاتب لرسول الله ﷺ ارتد عن الإسلام", "taqdim": 0, "n_athar": 1, "qailun": [["ابن شهاب", "تابع التابعين"]], "athar": []}, {"n": 7, "t": "﴿وهذا لسان عربي مبين﴾. يعنى القرآن، كما تقول العرب لقصيدة من الشعر [لسن فيها] الشاعر: هذا لسان فلان. تريد قصيدته، كما قال الشاعر :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 19, "imgs": ["016_019_1.png", "016_019_2.png"], "pages": [320, 321], "n": 6, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 106, "title": "تأويل: ﴿من كفر بالله من بعد إيمانه إلا من أكره وقلبه مطمئن بالإيمان ولكن من شرح بالكفر صدرا فعليهم﴾", "tabari": {"page": "14/372", "sarih": 0, "tarjih": "والصواب من القول فى ذلك عندى: أن الرافع ل \"من\" الأولى والثانية، قوله: ﴿فعليهم غضب من الله﴾، والعرب تفعل ذلك في حروف الجزاء، إذا استأنفت أحدهما على الآخر.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "إنما هذان جزاءان اجتمعا، أحدهما منعقد بالآخر، فجوابهما واحد، كقول القائل: من يأتنا، فمن يحسن نكرمه. بمعنى: من يحسن ممن يأتنا نكرمه. قال: وكذلك كل جزاءين اجتمعا، الثاني منعقد بالأول، فالجواب لهما واحد", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل قوله: ﴿من كفر بالله﴾ مرفوع بالرد على \"الذين\" فى قوله: ﴿إنما يفتري الكذب الذين لا يؤمنون بآيات الله﴾. ومعنى الكلام عنده: إنما يفترى الكذب من كفر بالله من بعد إيمانه، إلا من أكره من هؤلاء وقلبه مطمئن بالإيمان. وهذا قول لا وجه له؛ وذلك أن معنى الكلام لو كان كما قال قائل هذا القول، لكان الله تعالى ذكره قد أخرج ممن افترى الكذب في هذه الآية، الذين ولدوا على الكفر وأقاموا عليه، ولم يؤمنوا قط، وخص به الذين قد كانوا آمنوا ", "taqdim": 0, "n_athar": 6, "qailun": [["ابن عباس", "صحابي"], ["قتادة", "تابعي"], ["أبي مالك", "تابعي"], ["الشعبي", "تابعي"]], "athar": [42139, 42147, 42149, 42153]}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 110, "title": "سبب نزول: ﴿ثم إن ربك للذين هاجروا من بعد ما فتنوا ثم جاهدوا وصبروا إن ربك من بعدها لغفور رحيم﴾", "tabari": {"page": "14/380", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿ثم إن ربك للذين هاجروا من بعد ما فتنوا ثم جاهدوا وصبروا إن ربك من بعدها لغفور رحيم﴾. ذكر لنا أنه لما أنزل الله أن أهل مكة لا يقبل منهم إسلام حتى يهاجروا، كتب بها أهل المدينة إلى أصحابهم من أهل مكة، فلما جاءهم ذلك تبايعوا بينهم على أن يخرجوا، فإن لحق بهم المشركون من أهل مكة، قاتلوهم حتى ينجوا أو يلحقوا بالله، فخرجوا فأدركهم المشركون، فقاتلوهم؛ فمنهم من قتل، ومنهم من نجا، فأنزل الله تعالى: ﴿ثم إن ر", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل نزلت هذه الآية في شأن ابن أبى سرح", "taqdim": 0, "n_athar": 1, "qailun": [["عكرمة والحسن البصري", "تابعي"]], "athar": []}]}, "mawaqif": [], "mushid": {"i": 20, "imgs": ["016_020_1.png"], "pages": [321], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 111, "title": "تأويل: ﴿يوم تأتي كل نفس تجادل عن نفسها وتوفى كل نفس ما عملت وهم لا يظلمون﴾", "tabari": {"page": "14/381", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ﴿إن ربك من بعدها لغفور رحيم (١١٠) يوم تأتي كل نفس﴾ تخاصم عن نفسها وتحتج عنها، بما أسلفت في الدنيا من خير أو شر، أو إيمان أو كفر، ﴿وتوفى كل نفس ما عملت﴾ في الدنيا من طاعة ومعصية، ﴿وهم لا يظلمون﴾. يقول: وهم لا يفعل بهم إلا ما يستحقونه ويستوجبونه، بما قدموه من خير أو شر، فلا يجزى المحسن إلا بالإحسان، ولا المسئ إلا بالذى أسلف من الإساءة، لا يعاقب محسن، ولا يبخس جزاء إحسانه، ولا يثاب م", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "قيل ذلك لأن معني ﴿كل نفس﴾: كل إنسان. وأنث لأن النفس تذكر وتؤنث، يقال: ما جاءنى نفس واحد وواحدة. وكان بعض أهل العربية يرى هذا القول من قائله غلطا، ويقول: \"كل\" إذا أضيفت إلى نكرة واحدة خرج الفعل على قدر النكرة؛ كل امرأة قائمة، وكل رجل قائم، وكل امرأتين قائمتان، وكل رجلين قائمان، وكل نساء قائمات، وكل رجال قائمون. فيخرج على عدد النكرة وتأنيثها وتذكيرها، ولا حاجة به إلى تأنيث النفس وتذكيرها", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3756, "mi": 0, "aya": 112, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 382", "qawl": "", "nass": "ومثل الله مثلا لمكة التي سكانها أهل الشرك بالله هي القرية التي كانت آمنة مطمئنة", "qawaid": ["أقوال السلف"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["أقوال السلف"]}, "rulesD": {}}}, {"aya": 112, "title": "تأويل: ﴿وضرب الله مثلا قرية كانت آمنة مطمئنة يأتيها رزقها رغدا من كل مكان فكفرت بأنعم الله فأذاقها﴾", "tabari": {"page": "14/383", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول الله تعالى ذكره: ومثل الله مثلا لمكة التي سكانها أهل الشرك بالله، هى القرية التى كانت آمنة مطمئنة، وكان أمنها أن العرب كانت تتعادى، ويقتل بعضها بعضا، ويسبى بعضها بعضا، وأهل مكة لا يغار عليهم، ولا يحاربون في بلدهم، فذلك كان أمنها. وقوله: ﴿مطمئنة﴾. يعنى قارة بأهلها، لا يحتاج أهلها إلى النجع ، كما كان سكان البوادى يحتاجون إليها، ﴿يأتيها رزقها رغدا﴾. يقول: تأتى أهلها معايشهم واسعة كثيرة. وقوله: ﴿", "taqdim": 1, "n_athar": 6, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [42193, 42194, 42196, 42199, 42204]}, {"n": 2, "t": "بل القرية التي ذكر الله فى هذا الموضع: مدينة الرسول ﷺ", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3755, "mi": 0, "aya": 112, "alam": "ابن جرير", "fil": "أورد", "kind": "نقل", "ref": "14/ 383 - 384", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3755, "mi": 0, "aya": 112, "alam": "ابن عطية", "fil": "رد", "kind": "نقد", "ref": "5/ 417 - 418 ط: دار الكتب العلمية", "qawl": "", "nass": "فأدخل الطبري هذا على أن حفصة قالت: إن الآية نزلت في المدينة. وإنها هي التي ضربت مثلا، والأمر عندي ليس كذلك، وإنما أرادت أن المدينة قد حصلت في محذور المثل، وحل بها ما حل بالتي جعلت مثالا", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 3755, "mi": 0, "aya": 112, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "", "qawl": "", "nass": "فأصابتهم السنون والخوف، وسرايا رسول الله صلى الله عليه وسلم وغزواته، هذا إن كانت الآية مدنية، وإن كانت مكية فجوع السنين وخوف العذاب من الله بحسب التكذيب", "qawaid": [], "tabi": ""}], "mushid": {"i": 21, "imgs": ["016_021_1.png"], "pages": [321], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {"ابن عطية": ["لم يذكر مستندًا"]}}}, {"aya": 115, "title": "قوله: {غير باغ ولا عاد}", "mawsua": {"taliq": 3760, "masala": "قوله: {غير باغ ولا عاد}", "sigha": "ذكر ثلاثة أقوال", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن الباغي هو صاحب البغي على الإمام، أو في قطع الطريق، وبالجملة في سفر المعاصي، والعادي بمعناه في أنه ينوي المعصية", "ashab": "", "athar": []}, {"n": 2, "t": "أن قوله {غير باغ} معناه: غير مستعمل لهذه المحرمات مع وجود غيرها، وقوله: {ولا عاد} أي: لا يعدو حدود الله في هذا", "ashab": "", "athar": []}, {"n": 3, "t": "أن معناه: باغ وعاد في الشبع والتزود", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3760, "mi": 1, "aya": 115, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 422", "qawl": "الثاني", "nass": "وهذا القول أرجح وأعم في الرخصة", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 120, "title": "معنى الأمة", "mawsua": {"taliq": 3766, "masala": "معنى الأمة", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه معلم الناس الخير", "ashab": "", "athar": []}, {"n": 2, "t": "يؤتم به. ووجه معنى الآية على القول الثاني، فقال: «ف {أمة} على هذا صفة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3766, "mi": 1, "aya": 120, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 426", "qawl": "الثاني", "nass": "ف {أمة} على هذا صفة", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 125, "title": "هذه الآية، أمحكمة هي أم منسوخة؟", "mawsua": {"taliq": 3770, "masala": "هذه الآية، أمحكمة هي أم منسوخة؟", "sigha": "خلاف مصرَّح به", "nasib": "ابن عطية", "aqwal": []}, "mawaqif": [{"taliq": 3770, "mi": 0, "aya": 125, "alam": "ابن عطية", "fil": "أورد", "kind": "نقل", "ref": "5/ 429", "qawl": "", "nass": "ويظهر لي أن الاقتصار على هذه الحال وأن لا تتعدى مع الكفرة متى احتيج إلى المخاشنة، وهو منسوخ لا محالة، وأما من أمكنت معه هذه الأحوال من الكفار، ويرجى إيمانه بها دون قتال، فهي فيه محكمة إلى يوم القيامة، وأيضا فهي محكمة في جهة العصاة، فهكذا ينبغي أن يوعظ المسلمون إلى يوم القيامة", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 126, "title": "تأويل: ﴿وإن عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم﴾", "tabari": {"page": "14/404", "sarih": 0, "tarjih": "والصواب من القول في ذلك أن يقال: إن الله تعالى ذكره أمر من عوقب من المؤمنين بعقوبة، أن يعاقب من عاقبه بمثل الذى عوقب به، إن اختار عقوبته، وأعلمه أن الصبر على ترك عقوبته، على ما كان منه إليه، خير، وعزم على نبيه ﷺ أن يصبر، وذلك أن ذلك هو ظاهر التنزيل، والتأويلات التي ذكرناها عمن ذكروها عنه، محتملتها الآية كلها. فإذ كان ذلك كذلك، ولم يكن في الآية دلالة على أي ذلك عنى بها من خبر ولا عقل، كان الواجب علينا الحكم بها، إلى باطن لا دلالة عليه، وأن يقال: هي آية محكمة، أمر الله تعالى ذكره عباده ألا يتجاوزوا فيما وجب لهم قبل غيرهم من حق، من مال أو نفس -الحق الذي جعله الله لهم إلى غيره. وأنها غير منسوخة، إذ كان لا دلالة على نسخها، وأن للقول بأنها محكمة، وجها صحيحا مفهوما.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿وإن عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم﴾، [فلم تعاقبوا] ، ﴿لهو خير للصابرين﴾. ثم عزم وأخبر فلا يمثل ، فنهى عن المثل. قال: مثل الكفار بقتلى أحد، إلا حنظلة بن الراهب، كان الراهب أبو عامر مع أبي سفيان، فتركوا حنظلة لذلك.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "نسخ ذلك بقوله فى \"براءة\": ﴿فاقتلوا المشركين حيث وجدتموهم﴾ [التوبة: ٥]. قالوا: وإنما قال: ﴿وإن عاقبتم فعاقبوا بمثل ما عوقبتم به﴾. [حين أمر المؤمنين] ألا يبتدئوهم بقتال حتى يبتدئوهم به، فقال: ﴿وقاتلوا في سبيل الله الذين يقاتلونكم ولا تعتدوا إن الله لا يحب المعتدين﴾ [البقرة: ١٩٠]", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [42312, 42317]}, {"n": 3, "t": "بل عنى الله تعالى ذكره بقوله: ﴿واصبر وما صبرك إلا بالله﴾. نبي الله خاصة، دون سائر أصحابه، فكان الأمر بالصبر له عزيمة من الله دونهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [42322]}, {"n": 4, "t": "لم يعن بهاتين الآيتين شيء مما ذكر هؤلاء، وإنما عنى بهما أن من ظلم بظلامة، فلا يحل له أن ينال [ممن ظلمه] أكثر مما نال الظالم منه. وقالوا: الآية محكمة غير منسوخة", "taqdim": 0, "n_athar": 4, "qailun": [["ابن سيرين", "تابعي"], ["إبراهيم", "تابعي"], ["مجاهد", "تابعي"]], "athar": [42318, 42319, 42323, 42324, 42325]}]}, "mawaqif": [{"taliq": 3775, "mi": 0, "aya": 127, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "14/ 408 - بتصرف", "qawl": "", "nass": "وأولى القراءتين بالصواب في ذلك عندنا قراءة من قرأه: {في ضيق} بفتح الضاد؛ لأن الله تعالى إنما نهى نبيه صلى الله عليه وسلم أن يضيق صدره مما يلقى من أذى المشركين على تبليغه إياهم وحي الله وتنزيله، فقال له: {فلا يكن في صدرك حرج منه لتنذر به} [الأعراف: 2]، وقال: {فلعلك تارك بعض ما يوحى إليك وضائق به صدرك أن يقولوا لولا أنزل عليه كنز أو جاء معه ملك، إنما أنت نذير} [هود: 12]، وإذ كان ذلك هو الذي نهاه -تعالى ذكره-؛ ففتح الضاد هو الكلام المعروف من كلام العرب في ذلك المعنى، تقول العرب: في صدري من هذا الأمر ضيق. وإنما تكسر الضاد في الشيء الذي يتسع أحيانا ويضيق من قلة المعاش وضيق المسكن ونحو ذلك، فإن وقع الضيق -بفتح الضاد- في موضع الضيق -بالكسر- كان على أحد وجهين، إما على جمع الضيقة … والآخر: على تخفيف الشيء الضيق، كما يخفف الهين اللين فيقال: هو هين لين", "qawaid": ["اللغة"], "tabi": ""}], "mushid": {"i": 22, "imgs": ["016_022_1.png", "016_022_2.png"], "pages": [321, 322], "n": 4, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 126, "title": "سبب نزول هذه الآية", "mawsua": {"taliq": 3772, "masala": "سبب نزول هذه الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها نزلت في قتلى أحد حين مثلت بهم قريش", "ashab": "", "athar": []}, {"n": 2, "t": "أنها نزلت في كل مظلوم أن يقتص من ظالمه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3772, "mi": 1, "aya": 126, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "14/ 406", "qawl": "", "nass": "والصواب من القول في ذلك أن يقال: إن الله -تعالى ذكره- أمر من عوقب من المؤمنين بعقوبة أن يعاقب من عاقبه بمثل الذي عوقب به إن اختار عقوبته، وأعلمه أن الصبر على ترك عقوبته على ما كان منه إليه خير، وعزم على نبيه صلى الله عليه وسلم أن يصبر، وذلك أن ذلك هو ظاهر التنزيل، والتأويلات التي ذكرناها عمن ذكروها عنه محتملتها الآية كلها، فإذا كان ذلك كذلك، ولم يكن في الآية دلالة على أي ذلك عنى بها من خبر ولا عقل كان الواجب علينا الحكم بها إلى ناطق لا دلالة عليه، وأن يقال: هي آية محكمة أمر الله -تعالى ذكره- عباده أن لا يتجاوزوا فيما وجب لهم قبل غيرهم من حق من مال أو نفس؛ الحق الذي جعله الله لهم إلى غيره، وأنها غير منسوخة، إذ كان لا دلالة على نسخها، وأن للقول بأنها محكمة وجها صحيحا مفهوما", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [], "others": {"4": [{"id": 3635, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 327) في معنى {خصيم} احتمالين، فقال: «يحتمل: أن يريد به الكفرة الذين يختصمون في الله، ويجادلون في توحيده وشرعه. ذكره ابن سلام عن الحسن البصري. ويحتمل أن يريد أعمّ من هذا». ثم علَّق بقوله: «على أن الآية تعديد نعمة الذهن والبيان على البشر، ويظهر أنها إذ تقرر في خصام الكافرين ينضاف إلى العبرة وعيد ما».", "mawaqif": [{"taliq": 3635, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 327", "qawl": "", "nass": "يحتمل: أن يريد به الكفرة الذين يختصمون في الله، ويجادلون في توحيده وشرعه. ذكره ابن سلام عن الحسن البصري. ويحتمل أن يريد أعم من هذا", "qawaid": [], "tabi": ""}]}], "5": [{"id": 3636, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (5/ 328) أن الدِّفْء: السَّخانة وذهاب البرد بالأكسية. وحكى ابن عطية عن الأموي -نقلًا عن النحاس- «قال: الدِّفْء في لغة بعضهم: تناسل الإبل». ونقل عن ابن عباس أن الدِّفْء: نسل كل شيء. ثم رجَّح قائلًا: «والمعنى الأول هو الصحيح». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 3636, "mi": 0, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 328", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3636, "mi": 0, "aya": 5, "alam": "ابن عطية", "fil": "حكى", "kind": "نقل", "ref": "", "qawl": "", "nass": "قال: الدفء في لغة بعضهم: تناسل الإبل", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "7": [{"id": 3637, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 329) أن «الأثقال: الأمتعة». ونقل احتمالًا آخر أن «المراد هنا الأجسام، كقوله تعالى: {وأَخْرَجَتِ الأَرْضُ أثْقالَها} [الزلزلة: 2]، أي: بني آدم». ثم علَّق بقوله: «واللفظ يحتمل المعنيين».", "mawaqif": [{"taliq": 3637, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 329", "qawl": "", "nass": "الأثقال: الأمتعة", "qawaid": [], "tabi": ""}]}, {"id": 3638, "kinds": "تعليق", "text": "علَّق ابن عطية (5/ 329) على قول ابن عباس وعكرمة بقوله: «وفي الآية -على هذا- حضٌّ مّا على الحج».", "mawaqif": [{"taliq": 3638, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 329", "qawl": "ابن عباس", "nass": "وفي الآية -على هذا- حض ما على الحج", "qawaid": [], "tabi": ""}]}, {"id": 3639, "kinds": "تعليق،نقل", "text": "نقل ابنُ عطية (5/ 330) عن الفراء أن معنى «{بِشِقِّ الأَنْفُس} أي: بذهاب نصفها، كأنها قد ذابت تعبًا ونصبًا». ثم علَّق عليه بقوله: «كما تقول لرجل: لا تقدر على كذا إلا بذهاب جُلِّ نفسك، وبقطعة من كبدك. ونحو هذا من المجاز».", "mawaqif": [{"taliq": 3639, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 330", "qawl": "", "nass": "{بشق الأنفس} أي: بذهاب نصفها، كأنها قد ذابت تعبا ونصبا", "qawaid": [], "tabi": ""}]}], "8": [{"id": 3641, "kinds": "تعليق،نقل", "text": "ذكر ابن عطية (5/ 330) رواية «أن الله تعالى خلق ألف نوع من الحيوان، منها في البَرِّ أربعمائة، وبثَّها بأعيانها في البحر، وزاد فيه مائتين ليستا في البَرِّ». ثم علَّق عليها بقوله: «وكل من خصَّص في تفسير هذه الآية شيئًا -كقول من قال: سوس الثياب وغير ذلك- فإنما هو على جهة المثال، لا أن ما ذكره هو المقصود في نفسه».", "mawaqif": [{"taliq": 3641, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 330", "qawl": "", "nass": "أن الله تعالى خلق ألف نوع من الحيوان، منها في البر أربعمائة، وبثها بأعيانها في البحر، وزاد فيه مائتين ليستا في البر", "qawaid": [], "tabi": ""}]}], "9": [{"id": 3642, "kinds": "تعليق،نقل", "text": "نقل ابنُ كثير (8/ 296 - 297) في قوله تعالى: {وعَلى اللَّهِ قَصْدُ السَّبِيلِ} قول ابن عباس، وقول مجاهد، والضحاك، وقتادة، ونقل عن السدي أن {قصد السبيل} معناه: الإسلام. ثم علَّق بقوله: «وقول مجاهد هاهنا أقوى من حيث السياق؛ لأنه تعالى أخبر أن ثَمَّ طرقًا تسلك إليه، فليس يصل إليه منها إلا طريق الحق، وهي الطريق التي شرعها ورضيها، وما عداها مسدودة، والأعمال فيها مردودة».", "mawaqif": [{"taliq": 3642, "mi": 0, "aya": 9, "alam": "ابن كثير", "fil": "نقل", "kind": "نقل", "ref": "8/ 296 - 297", "qawl": "ابن عباس", "nass": "وقول مجاهد هاهنا أقوى من حيث السياق؛ لأنه تعالى أخبر أن ثم طرقا تسلك إليه، فليس يصل إليه منها إلا طريق الحق، وهي الطريق التي شرعها ورضيها، وما عداها مسدودة، والأعمال فيها مردودة", "qawaid": [], "tabi": ""}]}, {"id": 3643, "kinds": "نقد،توجيه،بيان،نقل", "text": "بيَّن ابنُ عطية (5/ 331) أن معنى: {وعَلى اللَّهِ قَصْدُ السَّبِيلِ} «أي: على الله تقويم طريق الهدى وتبيينه، وذلك بنصب الأدلة وبعث الرسل، وإلى هذا ذهب المتأوِّلون». ثم ذكر احتمالًا آخر: «أن يكون المعنى: إن من سلك السبيل القاصد فعلى الله رحمته ونعيمه وطريقه، وإلى ذلك مصيره». ثم وجَّهه بقوله: «فيكون هذا مثل قوله تعالى: {هَذا صِراطٌ مُسْتَقِيمٌ} [آل عمران: 51]، وقول النبي صلى الله عليه وسلم:» والشَّرُّ ليس إليك «. أي: لا يُفضي إلى رحمتك».\nونقل ابنُ تيمية (4/ 152) قولًا ولم ينسبه: أن «معنى قصد السبيل: سيركم ورجوعكم، والسبيل واحدة بمعنى الجمع». ثم انتقده مستندًا إلى دلالة اللغة، ولفظ الآية قائلًا: «هذا قول بعض المتأخرين، جعل القصد بمعنى: الإرادة، أي: عليه قصدكم للسبيل في ذهابكم ورجوعكم، وهو كلام مَن لم يفهم الآية، فإنّ السبيل القصد هي السبيل العادلة، أي: عليه السبيل القصد، والسبيل اسم جنس، ولهذا قال: {ومِنها جائِرٌ}. أي: عليه القصد من السبيل، ومن السبيل جائر، فأضافه إلى اسم الجنس إضافة النوع إلى الجنس، أي: القصد من السبيل، كما تقول: ثوب خز. ولهذا قال: {ومِنها جائِرٌ}. وأمّا من ظن أن التقدير: قصدكم السبيل. فهذا لا يطابق لفظ الآية ونظمها من وجوه متعددة».\nوذكر ابنُ عطية (5/ 332) أن «الألف واللام في {السَّبِيلِ} للعهد، وهي سبيل الشرع، وليست للجنس، ولو كانت للجنس لم يكن فيها جائر».\nوانتقده ابن تيمية (4/ 155) مستندًا إلى الدلالة العقلية، فقال: «وأما قوله: {قَصْدُ السَّبِيلِ} هي سبيل الشرع، وهي سبيل الهدى، والصراط المستقيم، وأنها لو كانت للجنس لم يكن منها جائر، فهذا أحد الوجهين في دلالة الآية، وهو مرجوح، والصحيح الوجه الآخر: أن السبيل اسم جنس، ولكن الذي على الله: هو القصد منها، وهي سبيل واحدة، ولما كان جنسًا قال: {ومِنها جائِرٌ}، والضمير يعود على ما ذُكِرَ بلا تكلف. وقوله: لو كان للجنس لم يكن منها جائر. ليس كذلك، فإنها ليست كلها عليه، بل إنما عليه القصد منها، وهي سبيل الهدى، والجائر ليس من القصد، وكأنه ظن أنه إذا كانت للجنس يكون عليه قصد كل سبيل، وليس كذلك، بل إنما عليه سبيل واحدة، وهي الصراط المستقيم، هي التي تدل عليه، وسائرها سبل الشيطان، كما قال: {وأَنَّ هَذا صِراطِي مُسْتَقِيمًا فاتَّبِعُوهُ ولا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ} [الأنعام: 153]، وقد أحسن في هذا الاحتمال، وفي تمثيله ذلك بقوله: {هَذا صِراطٌ عَلَيَّ مُسْتَقِيمٌ} [الحجر: 41]».", "mawaqif": [{"taliq": 3643, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "5/ 331", "qawl": "", "nass": "أي: على الله تقويم طريق الهدى وتبيينه، وذلك بنصب الأدلة وبعث الرسل، وإلى هذا ذهب المتأولون", "qawaid": [], "tabi": ""}, {"taliq": 3643, "mi": 0, "aya": 9, "alam": "ابن تيمية", "fil": "نقل", "kind": "نقل", "ref": "4/ 152", "qawl": "", "nass": "معنى قصد السبيل: سيركم ورجوعكم، والسبيل واحدة بمعنى الجمع", "qawaid": ["اللغة", "ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 3643, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 332", "qawl": "", "nass": "الألف واللام في {السبيل} للعهد، وهي سبيل الشرع، وليست للجنس، ولو كانت للجنس لم يكن فيها جائر", "qawaid": [], "tabi": ""}, {"taliq": 3643, "mi": 0, "aya": 9, "alam": "ابن تيمية", "fil": "انتقده", "kind": "نقد", "ref": "4/ 155", "qawl": "", "nass": "وأما قوله: {قصد السبيل} هي سبيل الشرع، وهي سبيل الهدى، والصراط المستقيم، وأنها لو كانت للجنس لم يكن منها جائر، فهذا أحد الوجهين في دلالة الآية، وهو مرجوح، والصحيح الوجه الآخر: أن السبيل اسم جنس، ولكن الذي على الله: هو القصد منها، وهي سبيل واحدة، ولما كان جنسا قال: {ومنها جائر}، والضمير يعود على ما ذكر بلا تكلف. وقوله: لو كان للجنس لم يكن منها جائر. ليس كذلك، فإنها ليست كلها عليه، بل إنما عليه القصد منها، وهي سبيل الهدى، والجائر ليس من القصد، وكأنه ظن أنه إذا كانت للجنس يكون عليه قصد كل سبيل، وليس كذلك، بل إنما عليه سبيل واحدة، وهي الصراط المستقيم، هي التي تدل عليه، وسائرها سبل الشيطان، كما قال: {وأن هذا صراطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله} [الأنعام: 153]، وقد أحسن في هذا الاحتمال، وفي تمثيله ذلك بقوله: {هذا صراط علي مستقيم} [الحجر: 41]", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}, {"id": 3644, "kinds": "نقد،نقل", "text": "ذكر ابن عطية (5/ 332) احتمالين لعود الضمير في قوله تعالى: {ومِنها جائِرٌ}: الأول: أن يعود الضمير على «السبل» التي يتضمنها معنى الآية، كأنه قال: ومن السبل جائر. ويكون المراد: طريق اليهود والنصارى وغيرهم كعباد الأصنام. الثاني: أن يعود الضمير على سبيل الشرع المذكورة، وتكون «مِن» للتبعيض، ويكون المراد: فرق الضلالة من أمة محمد صلى الله عليه وسلم، كأنه قال: ومن بنيات الطريق في هذه السبيل ومن شعبها جاير.\nواستدرك عليه ابن تيمية (4/ 155) قائلًا: «سبيل أهل البدع جائرة خارجة عن الصراط المستقيم فيما ابتدعوا فيه، ولا يقال: إن ذلك من السبيل المشروعة».", "mawaqif": [{"taliq": 3644, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 332", "qawl": "", "nass": "السبل", "qawaid": [], "tabi": ""}]}, {"id": 3645, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (5/ 332) عن الزجاج أن قوله تعالى: {ولَوْ شاءَ لَهَداكُمْ أجْمَعِينَ} «معناه: لو شاء لعرض عليكم آية تضطركم إلى الإيمان والاهتداء». ثم انتقده بقوله: «وهذا قول سوءٍ لأهل البدع الذين يرون الله لا يخلق أفعال العباد؛ لم يُحَصِّله الزجاج، ووقع فيه رحمة الله عليه عن غير قصد».", "mawaqif": [{"taliq": 3645, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 332", "qawl": "", "nass": "معناه: لو شاء لعرض عليكم آية تضطركم إلى الإيمان والاهتداء", "qawaid": [], "tabi": ""}]}], "12": [{"id": 3646, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (3/ 382 ط: دار الكتب العلمية) أنّ مِن منافع النجوم أنها هدايات، «ولهذا الوجْه عدت في جملة النعم على بني آدم، ومن النعمة بها ضياؤها أحيانًا». ثم نقل عن الزجاج أن من النعمة بها أيضًا: «علم عدد السنين والحساب بها». ثم علق قائلًا: «وفي هذا نظر».", "mawaqif": [{"taliq": 3646, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "3/ 382 ط: دار الكتب العلمية", "qawl": "", "nass": "ولهذا الوجه عدت في جملة النعم على بني آدم، ومن النعمة بها ضياؤها أحيانا", "qawaid": [], "tabi": ""}]}], "13": [{"id": 3647, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (5/ 336) أن قوله تعالى: {ألْوانُهُ} «معناه: أصنافه، كما تقول: هذه ألوان من الثَّمر ومن الطعام، ومن حيث كانت هذه المبثوثات في الأرض أصنافًا عُدَّت في النعمة، وظهر الانتفاع بها أنه على وجوه، ولا يظهر ذلك من حيث هي متلونة حُمرة وصُفرة وغير ذلك، ويحتمل أن يكون التنبيه على اختلاف الألوان حمرة وصفرة». ثم رجَّح قائلًا: «والأول أبْيَن».", "mawaqif": [{"taliq": 3647, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 336", "qawl": "", "nass": "معناه: أصنافه، كما تقول: هذه ألوان من الثمر ومن الطعام، ومن حيث كانت هذه المبثوثات في الأرض أصنافا عدت في النعمة، وظهر الانتفاع بها أنه على وجوه، ولا يظهر ذلك من حيث هي متلونة حمرة وصفرة وغير ذلك، ويحتمل أن يكون التنبيه على اختلاف الألوان حمرة وصفرة", "qawaid": [], "tabi": ""}]}], "14": [{"id": 3648, "kinds": "بيان،تعليق،نقل", "text": "ذكر ابن عطية (5/ 337) أن «المَخْرَ في اللغة: الصوت الذي يكون من هبوب الرِّيح على شيءٍ يُشَقُّ، أو يصحب في الجملة الماء. فيترتب منه أن يكون» المَخْرَ «من الريح، وأن يكون من السفينة ونحوها، وهو في هذه الآية من السفن. ثم نقل عن» بعض اللغويين أن «المَخْر» في كلام العرب: الشَّقُّ، يقال: مَخَرَ الماء في الأرض «. ثم علَّق بقوله:» فهذا بيِّنٌ أن يقال فيه للفلك: مواخر «. ونقل أيضًا قول الضحاك، وقول الحسن من طريق يزيد بن إبراهيم، وقتادة، ومقاتل، أن {مَواخِرَ} معناه: تجيء وتذهب بريح واحدة، ثم علَّق على ما سبق بقوله:» وهذه الأقوال ليست تفسيرًا لِلَّفظة، وإنما أرادوا بها أنها مواخر لهذه الأحوال، فنَصُّوا على هذه الأحوال، إذ هي موضع النعم المعدودة، إذ نَفْس كون الفلك ماخرة لا نعمة فيه، وإنما النعمة في مخرها بهذه الأحوال في التجارات، والسفر فيها، وما يمنح الله فيها من الأرباح والمِنَن\".\nوذكر ابنُ كثير (8/ 299 بتصرف) «أن السفن تمخر البحر، أي: تشقه، وقيل: تمخر الرياح،». ثم علَّق عليهما بقوله: «وكلاهما صحيح».", "mawaqif": [{"taliq": 3648, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 337", "qawl": "", "nass": "المخر في اللغة: الصوت الذي يكون من هبوب الريح على شيء يشق، أو يصحب في الجملة الماء. فيترتب منه أن يكون", "qawaid": [], "tabi": ""}, {"taliq": 3648, "mi": 0, "aya": 14, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "8/ 299 بتصرف", "qawl": "", "nass": "أن السفن تمخر البحر، أي: تشقه، وقيل: تمخر الرياح،", "qawaid": [], "tabi": ""}]}], "15": [{"id": 3649, "kinds": "نقل،استدلال", "text": "استدل ابن عطية (5/ 337، 338) بهذا الأثر على أن «ألقى» ليست بمعنى: خَلَقَ وجَعَلَ كما ذكر ذلك بعض المفسرين، بل هي أخَصُّ من ذلك؛ لأن «ألْقى» تقتضي أن الله أحدث الجبال ليس من الأرض، لكن من قدرته واختراعه، فقال: «ويؤيد هذا النظر ما روي في القصص عن الحسن عن قيس بن عباد أن الله تعالى لما خلق الأرض جعلت تمور، فقالت الملائكة: ما هذه بمُقرَّة على ظهرها أحدًا. فأصبحت ضحى وفيها رواسيها». واستدل على ذلك أيضا بالإجماع على أن قوله تعالى: {وأَنْهارًا} «منصوب بفعل مضمر، تقديره: وجَعَلَ أو خَلَقَ أنهارًا». فقال: «وإجماعهم على إضمار هذا الفعل دليل على خصوص {ألْقى}، ولو كان {ألْقى} بمعنى: خَلَقَ، لم يحتج إلى الإضمار».", "mawaqif": [{"taliq": 3649, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "استدل", "kind": "استدلال", "ref": "5/ 337، 338", "qawl": "", "nass": "ألقى", "qawaid": [], "tabi": ""}]}, {"id": 3650, "kinds": "غيره", "text": "لم يذكر ابن جرير (14/ 190) في معنى: {أنْ تَمِيدَ بِكُمْ} سوى قول مجاهد، والحسن.", "mawaqif": []}, {"id": 3651, "kinds": "نقل", "text": "ذكر ابن عطية (5/ 338) في معنى الآية احتمالًا آخر، فقال: «ويحتمل: لعلكم تهتدون بالنظر في دلالة هذه المصنوعات على صانعها». ثم استحسنه قائلًا: «وهذا التأويل هو البارع، أي: سخَّر وألقى وجعل أنهارًا وسُبُلًا لعل البشر يعتبرون ويرشدون، ولتكون علامات».", "mawaqif": [{"taliq": 3651, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 338", "qawl": "", "nass": "ويحتمل: لعلكم تهتدون بالنظر في دلالة هذه المصنوعات على صانعها", "qawaid": [], "tabi": ""}]}], "16": [{"id": 3653, "kinds": "ترجيح،نقل", "text": "نقل ابنُ عطية (5/ 340) في المراد بـ «النجم» ثلاثة أقوال: الأول: أنه الجَدْيُ والفَرْقدان. ونسبه للفراء. الثاني: أنه القطب الذي لا يجري. الثالث: أنه اسم جنس، والمراد جميع النجوم.\nثم رجَّح الثالث قائلًا: «وهذا هو الصواب». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 3653, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 340", "qawl": "", "nass": "النجم", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "21": [{"id": 3654, "kinds": "توجيه،تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 341) في قوله تعالى: {والَّذِينَ يَدْعُونَ} قراءتان: الأولى: (يُدْعَوْنَ) بضم الياء وفتح العين، على ما لم يُسَمَّ فاعله، وعلَّق عليها بقوله: «و {أمْواتٌ} يراد به الذين يدعون من دون الله، ورفع على ابتداء خبر مضمر تقديره: هم أموات، ويجوز أن يكون خبرًا لقوله: {والَّذِينَ} بعد الخبر في قوله: {لا يَخْلُقُونَ}، ووصفهم بالموت مجازًا، وإنما المراد أنهم لم يقبلوا حياةً قط ولا اتَّصفوا بها». الثانية: {يَدعُون} بفتح الياء وضم العين، وعلَّق على هذه القراءة بأنه «يجوز أن يراد بالأموات الكفار الذين ضميرهم في {يَدعُون}، شبَّههم بالأموات غير الأحياء من حيث هم ضلال غير مهتدين، ويستقيم -على هذا- فيهم قوله: {وما يَشْعُرُونَ أيّانَ يُبْعَثُونَ}، والبعث هنا: هو الحشر من القبور».\nثم نقل ابنُ عطية عن فرقة: أن الضمير في: {وما يَشْعُرُونَ} و {أيّانَ يُبْعَثُونَ} للكفار، ونقل عن فرقة أخرى: أن الضمير في {وما يَشْعُرُونَ} للأصنام، و {أيّانَ يُبْعَثُونَ} أي: أيّان يُبعَث الكفار، وذكر احتمالًا آخر: «أن يكون الضميران للأصنام، [ويكون البعث الإثارة،] كما تقول: بعثت النائم من نومه. إذا نبهته، وكما تقول: بعث الراعي سهمه. فكأنه وصفهم بغاية الجمود، أي: وإن طلبتَ حركاتهم بالتحريك لم يشعروا بذلك». ثم وجَّه قول الفرقة الأولى بقوله: «وعلى تأويل من يرى الضميرين للكفار ينبغي أن يُعتَقد في الكلام الوعيد، أي: وما يشعر الكفار متى يُبعَثون إلى التعذيب، ولو اختصر هذا المعنى لم يكن في وصفهم بأنهم لا يشعرون وأيان يبعثون طائل؛ لأن الملائكة والأنبياء والصالحين كذلك هم في الجهل بوقت البعث».", "mawaqif": [{"taliq": 3654, "mi": 0, "aya": 21, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 341", "qawl": "", "nass": "و {أموات} يراد به الذين يدعون من دون الله، ورفع على ابتداء خبر مضمر تقديره: هم أموات، ويجوز أن يكون خبرا لقوله: {والذين} بعد الخبر في قوله: {لا يخلقون}، ووصفهم بالموت مجازا، وإنما المراد أنهم لم يقبلوا حياة قط ولا اتصفوا بها", "qawaid": [], "tabi": ""}, {"taliq": 3654, "mi": 0, "aya": 21, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "", "qawl": "", "nass": "أن يكون الضميران للأصنام، [ويكون البعث الإثارة،] كما تقول: بعثت النائم من نومه. إذا نبهته، وكما تقول: بعث الراعي سهمه. فكأنه وصفهم بغاية الجمود، أي: وإن طلبت حركاتهم بالتحريك لم يشعروا بذلك", "qawaid": [], "tabi": ""}]}], "22": [{"id": 3655, "kinds": "غيره", "text": "لم يذكر ابن جرير (14/ 197) في معنى: {قُلُوبُهُمْ مُنْكِرَةٌ} سوى قول قتادة.", "mawaqif": []}], "23": [{"id": 3656, "kinds": "نقل", "text": "نقل ابنُ عطية (5/ 343) عن يحيى بن سلام والنقاش أن «المراد هنا بـ {ما يُسِرُّون}: تشاورهم في دار الندوة في قتل النبي صلى الله عليه وسلم».", "mawaqif": [{"taliq": 3656, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 343", "qawl": "", "nass": "المراد هنا ب {ما يسرون}: تشاورهم في دار الندوة في قتل النبي صلى الله عليه وسلم", "qawaid": [], "tabi": ""}]}], "26": [{"id": 3659, "kinds": "توجيه،نقل", "text": "نقل ابنُ عطية (5/ 345) عن فرقة أن «المراد بـ {الَّذِينَ مِن قَبْلِهِمْ}: جميع من كفر من الأمم المتقدمة ومكر، ونزلت به عقوبة من الله تعالى». ثم وجَّهه بقوله: «وقوله -على هذا-: {فَأَتى اللَّهُ بُنْيانَهُمْ مِنَ القَواعِدِ} إلى آخر الآية تمثيل وتشبيه، أي: حالهم كحال مَن فُعِل به هذا».", "mawaqif": [{"taliq": 3659, "mi": 0, "aya": 26, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 345", "qawl": "", "nass": "المراد ب {الذين من قبلهم}: جميع من كفر من الأمم المتقدمة ومكر، ونزلت به عقوبة من الله تعالى", "qawaid": [], "tabi": ""}]}], "27": [{"id": 3661, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (14/ 208) في معنى: {تُشاقُّونَ فِيهِمْ} سوى قول ابن عباس.", "mawaqif": []}, {"id": 3662, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (5/ 346) في معنى قوله تعالى: {قالَ الَّذِينَ أُوتُوا العِلْمَ} قول مقاتل، ويحيى بن سلام، ثم رجَّح قائلًا: «والصواب أن يعمَّ جميع مَن آتاه الله علم ذلك مِن جميع مَن حضر الموقف مِن مَلَك أو إنسي، وغير ذلك».", "mawaqif": [{"taliq": 3662, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 346", "qawl": "مقاتل", "nass": "والصواب أن يعم جميع من آتاه الله علم ذلك من جميع من حضر الموقف من ملك أو إنسي، وغير ذلك", "qawaid": [], "tabi": ""}]}], "28": [{"id": 3663, "kinds": "نقد،توجيه", "text": "استدرك ابن عطية (5/ 347) مستندًا إلى أحوال النزول على قول عكرمة، فقال: «وإنما اشتبهت عليه بالآية الأخرى التي نزلت في أولئك باتفاقٍ من العلماء». ثم وجَّهه بقوله: «وعلى هذا القول يحسن قطع {الَّذِينَ}، ورفعه بالابتداء».", "mawaqif": [{"taliq": 3663, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "استدرك", "kind": "نقد", "ref": "5/ 347", "qawl": "عكرمة", "nass": "وإنما اشتبهت عليه بالآية الأخرى التي نزلت في أولئك باتفاق من العلماء", "qawaid": ["سبب النزول وأحواله"], "tabi": ""}]}, {"id": 3664, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 347) في معنى: {ما كُنّا نَعْمَلُ مِن سُوء}: «ويحتمل قولهم: {ما كُنّا نَعْمَلُ مِن سُوءٍ} وجهين: أحدهما: أنهم كذبوا وقصدوا الكذب اعتصامًا منهم به، على نحو قولهم: {واللَّهِ رَبِّنا ما كُنّا مُشْرِكِينَ} [الأنعام: 23]. والآخر: أنهم أخبروا عن أنفسهم أنهم لم يكونوا يعملون سوءًا، فأخبروا عن ظنهم بأنفسهم، وهو كذب في نفسه».", "mawaqif": [{"taliq": 3664, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 347", "qawl": "", "nass": "ويحتمل قولهم: {ما كنا نعمل من سوء} وجهين: أحدهما: أنهم كذبوا وقصدوا الكذب اعتصاما منهم به، على نحو قولهم: {والله ربنا ما كنا مشركين} [الأنعام: 23]. والآخر: أنهم أخبروا عن أنفسهم أنهم لم يكونوا يعملون سوءا، فأخبروا عن ظنهم بأنفسهم، وهو كذب في نفسه", "qawaid": [], "tabi": ""}]}], "38": [{"id": 3666, "kinds": "نقد،نقل", "text": "ذكر ابن عطية (5/ 354) أن بعض الشيعة يقول: «إن الإشارة بهذه الآية لعلي بن أبي طالب?، وإن الله سيبعثه في الدنيا». ثم انتقدهم مستندًا إلى عدم الدليل، وأقوال السلف قائلًا: «وهذا هو القول بالرجعة، وقولهم هذا باطل وافتراءٌ على الله، وبهتانٌ من القول ردَّه ابن عباس رضي الله عنهما، وغيره».", "mawaqif": [{"taliq": 3666, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 354", "qawl": "", "nass": "إن الإشارة بهذه الآية لعلي بن أبي طالب?، وإن الله سيبعثه في الدنيا", "qawaid": ["عدم الدليل على غيره", "أقوال السلف"], "tabi": ""}]}], "45": [{"id": 3671, "kinds": "ترجيح،نقل", "text": "رجَّح ابنُ جرير (14/ 233) مستندًا إلى السياق أنّ المقصود بقوله تعالى: {أفَأَمِنَ الَّذِينَ مَكَرُوا السَّيِّئاتِ} هم مشركو مكة، ومكرهم السيئات: شركهم وتكذيبهم، وعلَّل ذلك بقوله: «لأن ذلك تهديدٌ من الله أهل الشرك به، وهو عقيب قوله: {وما أرْسَلْنا مِن قَبْلِكَ إلا رِجالا نُوحِي إلَيْهِمْ فاسْأَلُوا أهْلَ الذِّكْرِ إنْ كُنْتُمْ لا تَعْلَمُونَ}، فكان تهديدُ مَن لم يُقِرَّ بحجَّة الله الذي جرى الكلام بخطابه قبل ذلك أحْرى من الخبر عمَّن انقطع ذِكْرُه عنه». ثم ذكر أثر قتادة.\nواستظهر ذلك ابنُ عطية (5/ 359)، ولم يذكر مستندًا.", "mawaqif": [{"taliq": 3671, "mi": 0, "aya": 45, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 233", "qawl": "", "nass": "لأن ذلك تهديد من الله أهل الشرك به، وهو عقيب قوله: {وما أرسلنا من قبلك إلا رجالا نوحي إليهم فاسألوا أهل الذكر إن كنتم لا تعلمون}، فكان تهديد من لم يقر بحجة الله الذي جرى الكلام بخطابه قبل ذلك أحرى من الخبر عمن انقطع ذكره عنه", "qawaid": ["السياق"], "tabi": ""}]}], "46": [{"id": 3672, "kinds": "تعليق", "text": "علَّق ابنُ كثير (8/ 316) على قول الضحاك، وقول محمد بن السائب، ومقاتل، وابن جريج، من طريق حجاج أن قوله تعالى: {فِي تَقَلُّبِهِمْ} معناه: بالليل والنهار، بقوله: «كقوله تعالى: {أفَأَمِنَ أهْلُ القُرى أنْ يَأْتِيَهُمْ بَأْسُنا بَياتًا وهُمْ نائِمُونَ * أوَأَمِنَ أهْلُ القُرى أنْ يَأْتِيَهُمْ بَأْسُنا ضُحًى وهُمْ يَلْعَبُونَ} [الأعراف: 97 - 98]».", "mawaqif": [{"taliq": 3672, "mi": 0, "aya": 46, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "8/ 316", "qawl": "الضحاك", "nass": "كقوله تعالى: {أفأمن أهل القرى أن يأتيهم بأسنا بياتا وهم نائمون * أوأمن أهل القرى أن يأتيهم بأسنا ضحى وهم يلعبون} [الأعراف: 97 - 98]", "qawaid": [], "tabi": ""}]}], "47": [{"id": 3673, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 361) أن «هذا التنقيص يتَّجه الوعيد به على معنيين: أحدهما: أن يهلكهم ويخرج أرواحهم على تخوف، أي: أفذاذًا، يتَنَقَّصَهم بذلك الشيء بعد الشيء». ثم علَّق عليه بقوله: «وهذا لا يدَّعي أحد أنه يأمنه، وكأن هذا الوعيد إنما يكون بعذاب ما يلقون بعد الموت، وإلا فهكذا تهلك الأمم كلها، ويؤيد هذا قوله: {فَإنَّ رَبَّكُمْ لَرَؤُفٌ رَحِيمٌ}، أي: أن هذه الرتبة من الوعيد فيها رأفة ورحمة وإمهال ليتوب التائب ويرجع الراجع». «والآخر: ما قال الضحاك: أن يأخذ بالعذاب طائفة أو قرية، ويترك أخرى، ثم كذلك حتى يهلك الكل».", "mawaqif": [{"taliq": 3673, "mi": 0, "aya": 47, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 361", "qawl": "", "nass": "هذا التنقيص يتجه الوعيد به على معنيين: أحدهما: أن يهلكهم ويخرج أرواحهم على تخوف، أي: أفذاذا، يتنقصهم بذلك الشيء بعد الشيء", "qawaid": [], "tabi": ""}]}, {"id": 3674, "kinds": "تعليق", "text": "علق ابنُ عطية (5/ 361) على قول محمد بن السائب الكلبي قائلًا: «وفي هذا تكلُّف ما».", "mawaqif": [{"taliq": 3674, "mi": 0, "aya": 47, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 361", "qawl": "محمد بن", "nass": "وفي هذا تكلف ما", "qawaid": [], "tabi": ""}]}], "48": [{"id": 3675, "kinds": "توجيه،نقل", "text": "وجَّه ابنُ عطية (5/ 364) قول ابن عباس من طريق العوفي بقوله: «وعلى هذا فأول ذرور الشمس [طلوعها] فالظل عن يمين مستقبل الجنوب، ثم يبدأُ الانحراف فهو عن الشمائل؛ لأنها حركات كثيرة وظلال مقطعة، فهي شمائل كثيرة، وكان الظل عن اليمين متصلًا واحدًا عامًّا لكلِّ شيءٍ، وفي هذا القول تجوُّز في {يَتَفَيَّأُ}». ووجَّه قول قتادة، وابن جريج بقوله: «ومن ذهب إلى أن اليمين: من غدوة النهار إلى الزوال، ثم يكون من الزوال إلى المغيب عن الشمال -وهو قول قتادة، وابن جريج-، فإنما يترتب له ذلك فيما قدره مستقبل الجنوب، والاعتبار في هذه الآية عندي إنما هو مستقبل الجنوب». ثم ذكر قولًا عن بعض الناس، وانتقده، فقال: «وما قاله بعض الناس من: أن اليمين أول دفعة للظل بعد الزوال، ثم الآخر إلى الغروب هي عن الشمائل، ولذلك جمع الشَّمائل وأفرد اليمين. فتخليط من القول يبطل من جهات». ولم يذكرها.", "mawaqif": [{"taliq": 3675, "mi": 0, "aya": 48, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 364", "qawl": "ابن عباس", "nass": "وعلى هذا فأول ذرور الشمس [طلوعها] فالظل عن يمين مستقبل الجنوب، ثم يبدأ الانحراف فهو عن الشمائل؛ لأنها حركات كثيرة وظلال مقطعة، فهي شمائل كثيرة، وكان الظل عن اليمين متصلا واحدا عاما لكل شيء، وفي هذا القول تجوز في {يتفيأ}", "qawaid": [], "tabi": ""}]}], "52": [{"id": 3677, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 368) عن ابن عباس أن «الواصب» بمعنى: الواجب. وعلّق عليه بقوله: «وهذا نحو قوله: الواصب: الدائم». وذكر ابنُ عطية في معنى الواصب قولًا آخر: أن معناه: التعب. ثم علّق عليه قائلًا: «فـ» واصب\" على هذا جار على النسب، أي: ذا وصب، كما قال:\nأضحى فؤادي به فاتنًا\nوهذا كثير\".", "mawaqif": [{"taliq": 3677, "mi": 0, "aya": 52, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 368", "qawl": "", "nass": "الواصب", "qawaid": [], "tabi": ""}, {"taliq": 3677, "mi": 0, "aya": 52, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "ف", "qawaid": [], "tabi": ""}]}], "53": [{"id": 3679, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (14/ 252) غير قول ابن عباس.", "mawaqif": []}], "56": [{"id": 3681, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 371): «وقوله: {لِما لا يَعْلَمُونَ} يريد الأصنام، ومعناه: لا يعلمون فيهم حجة ولا برهانًا، ويحتمل أن يريد بقوله: {يَعْلَمُونَ} الأصنام، أي: يجعلون لجمادات لا تعلم شيئا نَصِيبًا، فالمفعول محذوف، ثم عبر عنهم بعبارة من يعقل بحسب مذهب الكفار الذين يسندون إليها ما يُسند إلى من يعقل، وبحسب أنه إسناد منفي، وهذا الاحتمال كله ضعيف».", "mawaqif": [{"taliq": 3681, "mi": 0, "aya": 56, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 371", "qawl": "", "nass": "وقوله: {لما لا يعلمون} يريد الأصنام، ومعناه: لا يعلمون فيهم حجة ولا برهانا، ويحتمل أن يريد بقوله: {يعلمون} الأصنام، أي: يجعلون لجمادات لا تعلم شيئا نصيبا، فالمفعول محذوف، ثم عبر عنهم بعبارة من يعقل بحسب مذهب الكفار الذين يسندون إليها ما يسند إلى من يعقل، وبحسب أنه إسناد منفي، وهذا الاحتمال كله ضعيف", "qawaid": [], "tabi": ""}]}], "58": [{"id": 3682, "kinds": "غيره", "text": "لم يذكر ابن جرير (14/ 256) في معنى {كظيم} غير قول ابن عباس من طريق ابن جريج، وقول الضحاك.", "mawaqif": []}], "59": [{"id": 3683, "kinds": "نقل", "text": "قال ابنُ عطية (5/ 372): «وقوله: {يَتَوارى مِنَ القَوْمِ} الآية، هذا التواري الذي ذكر الله تعالى إنما هو بعد البشارة بالأنثى، وما يحكى أن الرجل منهم كان إذا أصاب امرأته الطلق توارى حتى يخبر بأحد الأمرين فليس المراد في الآية، ويُشبه أن ذلك كان إذا أخبر بسارٍّ خرج، وإن أخبر بسوء بقي على تواريه ولم يحتج إلى إحداثه».", "mawaqif": [{"taliq": 3683, "mi": 0, "aya": 59, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 372", "qawl": "", "nass": "وقوله: {يتوارى من القوم} الآية، هذا التواري الذي ذكر الله تعالى إنما هو بعد البشارة بالأنثى، وما يحكى أن الرجل منهم كان إذا أصاب امرأته الطلق توارى حتى يخبر بأحد الأمرين فليس المراد في الآية، ويشبه أن ذلك كان إذا أخبر بسار خرج، وإن أخبر بسوء بقي على تواريه ولم يحتج إلى إحداثه", "qawaid": [], "tabi": ""}]}], "60": [{"id": 3684, "kinds": "ترجيح،نقد،بيان،تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 372 - 373) في قوله: {مثل} قولًا، وانتقده مستندًا لظاهر اللفظ، فقال: «قالت فرقة: {مَثَلُ} في هذه الآية بمعنى: صفة، أي: لهؤلاء صفة السوء، ولله الوصف الأعلى. وهذا لا نضطر إليه، لأنه خروج عن اللفظ».\nوعلّق عليه ابنُ القيم (2/ 112) بقوله: «وهذا قول صحيح، فالمثل كثيرًا ما يرد بمعنى: الصفة. قاله جماعة من المتقدمين».\nثم رجّح ابنُ عطية مستندًا إلى دلالة العقل أن قوله: «{مَثَلُ} على حاله، وذلك أنهم إذا قالوا: إنّ البنات لله. فقد جعلوا له مثلًا، فالبنات من البشر، وكثرة البنات عندهم مكروه ذميم، فهو مثل السوء الذي أخبر الله تعالى أنه لهم ليس في البنات فقط، لكن لما جعلوه هم في البنات جعله هو لهم على الإطلاق في كل سوء، ولا غاية بعد عذاب النار، وقوله: {ولِلَّهِ المَثَلُ الأَعْلى} على الإطلاق أيضًا في الكمال المستغني».\nوذكر ابنُ القيم (2/ 112 - 113) عدة أقوال في معنى الآية، ثم علّق بقوله: «قلت: المثل الأعلى يتضمن الصفة العليا، وعلم العالمين بها، ووجودها العلمي، والخبر عنها، وذكرها، وعبادة الرب سبحانه بواسطة العلم والمعرفة القائمة بقلوب عابديه وذاكريه، فهاهنا أربعة أمور، الأول: ثبوت الصفات العليا لله سبحانه في نفس الأمر، علمها العباد أو جهلوها، وهذا معنى قول مَن فسره بالصفة. الثاني: وجودها في العلم والتصور، وهذا معنى قول مَن قال من السلف والخلف: إنه ما في قلوب عابديه وذاكريه من معرفته وذكره ومحبته وإجلاله وتعظيمه. وهذا الذي في قلوبهم من المثل الأعلى لا يشترك فيه غيره معه، بل يختص به في قلوبهم، كما اختص في ذاته، وهذا معنى قول مَن قال من المفسرين: أهل السماء يعظمونه ويحبونه ويعبدونه، وأهل الأرض يعظمونه ويجلونه. الثالث: ذكر صفاته والخبر عنها وتنزيهها عن النقائص والعيوب والتمثيل. الرابع: محبة الموصوف بها وتوحيده والإخلاص له والتوكل عليه والإنابة إليه، وكلما كان الإيمان بالصفات أكمل كان هذا الحب والإخلاص أقوى. فعبارات السلف تدور حول هذه المعاني الأربعة لا تتجاوزها».", "mawaqif": [{"taliq": 3684, "mi": 0, "aya": 60, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 372 - 373", "qawl": "", "nass": "قالت فرقة: {مثل} في هذه الآية بمعنى: صفة، أي: لهؤلاء صفة السوء، ولله الوصف الأعلى. وهذا لا نضطر إليه، لأنه خروج عن اللفظ", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 3684, "mi": 0, "aya": 60, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "{مثل} على حاله، وذلك أنهم إذا قالوا: إن البنات لله. فقد جعلوا له مثلا، فالبنات من البشر، وكثرة البنات عندهم مكروه ذميم، فهو مثل السوء الذي أخبر الله تعالى أنه لهم ليس في البنات فقط، لكن لما جعلوه هم في البنات جعله هو لهم على الإطلاق في كل سوء، ولا غاية بعد عذاب النار، وقوله: {ولله المثل الأعلى} على الإطلاق أيضا في الكمال المستغني", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3684, "mi": 0, "aya": 60, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 112 - 113", "qawl": "", "nass": "قلت: المثل الأعلى يتضمن الصفة العليا، وعلم العالمين بها، ووجودها العلمي، والخبر عنها، وذكرها، وعبادة الرب سبحانه بواسطة العلم والمعرفة القائمة بقلوب عابديه وذاكريه، فهاهنا أربعة أمور، الأول: ثبوت الصفات العليا لله سبحانه في نفس الأمر، علمها العباد أو جهلوها، وهذا معنى قول من فسره بالصفة. الثاني: وجودها في العلم والتصور، وهذا معنى قول من قال من السلف والخلف: إنه ما في قلوب عابديه وذاكريه من معرفته وذكره ومحبته وإجلاله وتعظيمه. وهذا الذي في قلوبهم من المثل الأعلى لا يشترك فيه غيره معه، بل يختص به في قلوبهم، كما اختص في ذاته، وهذا معنى قول من قال من المفسرين: أهل السماء يعظمونه ويحبونه ويعبدونه، وأهل الأرض يعظمونه ويجلونه. الثالث: ذكر صفاته والخبر عنها وتنزيهها عن النقائص والعيوب والتمثيل. الرابع: محبة الموصوف بها وتوحيده والإخلاص له والتوكل عليه والإنابة إليه، وكلما كان الإيمان بالصفات أكمل كان هذا الحب والإخلاص أقوى. فعبارات السلف تدور حول هذه المعاني الأربعة لا تتجاوزها", "qawaid": [], "tabi": ""}]}], "61": [{"id": 3685, "kinds": "بيان،تعليق،نقل", "text": "بيّن ابنُ عطية (5/ 374) أنّ ما جاء من آثار عن السلف تفيد بموت الجُعل وغيره من الدواب بفعل ابن آدم إنما هو مترتب على أن المراد بالدابة في الآية: كل ما يدب على الأرض. ثم نقل قولًا آخر لم ينسبه لأحد من السلف أن المراد بالدابة: الظَلَمة فقط. وعلّق عليه، فقال: «وقالت فرقة: قوله: {مِن دابَّةٍ} يريد: من أولئك الظلمة فقط، ويدل على هذا التخصيص أنّ الله لا يعاقب أحدًا بذنب أحد، واحتجت بقول الله تعالى: {ولا تَزِرُ وازِرَةٌ وِزْرَ أُخْرى} [الأنعام: 164]». ثم قال معلّقًا مستندًا إلى النظائر، ودلالة العقل: «وهذا كله لا حُجَّة فيه، وذلك أنّ الله تعالى لا يجعل العقوبة تقصد أحدًا بسبب إذناب غيره، ولكن إذا أرسل عذابًا على أمة عاصية، لم يمكن البريء التخلص من ذلك العذاب، فأصابه العذاب لا بأنه له مجازاة، ونحو هذا قوله: {واتَّقُوا فِتْنَةً لا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنكُمْ خاصَّةً} [الأنفال: 25]، وقيل للنبي صلى الله عليه وسلم: أنهلك وفينا الصالحون؟ قال: «نعم، إذا كثر الخبث». ثم لا بد من تَعَلُّق ظلم ما بالأبرياء، وذلك بترك التغيير ومداهنة أهل الظلم ومداومة جوارهم».", "mawaqif": [{"taliq": 3685, "mi": 0, "aya": 61, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "5/ 374", "qawl": "", "nass": "وقالت فرقة: قوله: {من دابة} يريد: من أولئك الظلمة فقط، ويدل على هذا التخصيص أن الله لا يعاقب أحدا بذنب أحد، واحتجت بقول الله تعالى: {ولا تزر وازرة وزر أخرى} [الأنعام: 164]", "qawaid": ["القرآن والنظائر", "الدلالة العقلية"], "tabi": ""}]}, {"id": 3686, "kinds": "حصر", "text": "لم يذكر ابن جرير (14/ 261) غير قول محمد ابن شهاب الزهري.", "mawaqif": []}], "62": [{"id": 3687, "kinds": "ترجيح،تعليق،نقل", "text": "ذكر ابنُ جرير (14/ 267) هذه القراءة، وعلّق عليها قائلًا: «وقرأه أبو جعفر القارئ: «وأَنَّهُم مُّفَرِّطُونَ» بكسر الراء وتشديدها، بتأويل: أنهم مفرطون في أداء الواجب الذي كان لله عليهم في الدنيا من طاعته وحقوقه، مضيعو ذلك، من قول الله تعالى: {يا حسرتا على ما فرطت في جنب الله} [الزمر: 56]».\nوبنحوه ابنُ عطية (5/ 375).\nثم ذكر ابنُ جرير قراءة من قرأ ذلك بكسر الراء وتخفيفها، وعلّق عليها، فقال: «وقرأ نافع بن أبي نعيم: «وأَنَّهُم مُّفْرِطُونَ» بكسر الراء وتخفيفها … بتأويل: أنهم مفرطون في الذنوب والمعاصي، مسرفون على أنفسهم مكثرون منها، من قولهم: أفرط فلان في القول: إذا تجاوز حده، وأسرف فيه».\nوعلّق عليها ابنُ عطية (3/ 375)، فقال: «وقرأ السبعة سوى نافع {مُفْرَطُونَ} بفتح الراء وخفتها، ومعناه: مقدمون إلى النار والعذاب. وهي قراءة الحسن، والأعرج، وأصحاب ابن عباس، وقد رويت عن نافع، وهو مأخوذ من فرط الماء، وهم القوم الذين يتقدمون إلى المياه لإصلاح الدلاء والأرشية، ومنه قول النبي صلى الله عليه وسلم: «أنا فرطكم على الحوض»».\nثم رجّح ابنُ جرير مستندًا إلى لموافقتها لتأويل أهل التأويل قراءة من قرأ ذلك بفتح الراء وتخفيفها، فقال: «والذي هو أولى القراءات في ذلك بالصواب قراءة الذين ذكرنا قراءتهم من أهل العراق؛ لموافقتها تأويل أهل التأويل الذي ذكرنا قبل، وخروج القراءات الأخرى عن تأويلهم».", "mawaqif": [{"taliq": 3687, "mi": 0, "aya": 62, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "14/ 267", "qawl": "", "nass": "وقرأه أبو جعفر القارئ: «وأنهم مفرطون", "qawaid": [], "tabi": ""}, {"taliq": 3687, "mi": 0, "aya": 62, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "5/ 375", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3687, "mi": 0, "aya": 62, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "وقرأ نافع بن أبي نعيم: «وأنهم مفرطون", "qawaid": [], "tabi": ""}, {"taliq": 3687, "mi": 0, "aya": 62, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "والذي هو أولى القراءات في ذلك بالصواب قراءة الذين ذكرنا قراءتهم من أهل العراق؛ لموافقتها تأويل أهل التأويل الذي ذكرنا قبل، وخروج القراءات الأخرى عن تأويلهم", "qawaid": ["أقوال السلف"], "tabi": ""}]}, {"id": 3688, "kinds": "حصر", "text": "لم يذكر ابن جرير (14/ 262) غير قول قتادة، وقول مجاهد.", "mawaqif": []}, {"id": 3690, "kinds": "تعليق،نقل", "text": "ذكر ابن كثير (8/ 322) هذا القول، وعلّق عليه بقوله: «وهذا كقوله تعالى: {فاليوم ننساهم كما نسوا لقاء يومهم هذا} [الأعراف: 51]».", "mawaqif": [{"taliq": 3690, "mi": 0, "aya": 62, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "8/ 322", "qawl": "", "nass": "وهذا كقوله تعالى: {فاليوم ننساهم كما نسوا لقاء يومهم هذا} [الأعراف: 51]", "qawaid": [], "tabi": ""}]}, {"id": 3691, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 375) هذا القول، وعلّق عليه بقوله: «وهذا قريب من الذي قبله». يعني: قول من قال: معناه: منسيون في النار.", "mawaqif": [{"taliq": 3691, "mi": 0, "aya": 62, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 375", "qawl": "", "nass": "وهذا قريب من الذي قبله", "qawaid": [], "tabi": ""}]}, {"id": 3692, "kinds": "تعليق،نقل", "text": "ذكر ابنُ كثير (8/ 322) قول قتادة، وعلّق عليه، فقال: «وعن قتادة أيضًا: {مفرطون} أي: معجلون إلى النار، من الفرط، وهو السابق إلى الورد».", "mawaqif": [{"taliq": 3692, "mi": 0, "aya": 62, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "8/ 322", "qawl": "قتادة", "nass": "وعن قتادة أيضا: {مفرطون} أي: معجلون إلى النار، من الفرط، وهو السابق إلى الورد", "qawaid": [], "tabi": ""}]}], "64": [{"id": 3695, "kinds": "خلاف", "text": "قال ابنُ عطية (5/ 376): «وقوله {الَّذِي اخْتَلَفُوا} فِيهِ لفظ عام لأنواع كفر الكفرة؛ من الجحد بالله تعالى، أو بالقيامة، أو بالنبوءات، أو غير ذلك، ولكن الإشارة في هذه الآية إنما هي لجحدهم الربوبية، وتشريكهم الأصنام في الألوهية، يدل على ذلك أخذه بعد هذا في إثبات العبر الدالة على أن الأنعام وسائر الأفعال إنما هي من الله تعالى، لا من الأصنام».", "mawaqif": [{"taliq": 3695, "mi": 0, "aya": 64, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 376", "qawl": "", "nass": "وقوله {الذي اختلفوا} فيه لفظ عام لأنواع كفر الكفرة؛ من الجحد بالله تعالى، أو بالقيامة، أو بالنبوءات، أو غير ذلك، ولكن الإشارة في هذه الآية إنما هي لجحدهم الربوبية، وتشريكهم الأصنام في الألوهية، يدل على ذلك أخذه بعد هذا في إثبات العبر الدالة على أن الأنعام وسائر الأفعال إنما هي من الله تعالى، لا من الأصنام", "qawaid": [], "tabi": ""}]}], "66": [{"id": 3696, "kinds": "خلاف،تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 377 - 378) في عود الضمير من قوله: {مما في بطونه} عدة أقوال، فقال: \"وقوله: {مِمّا فِي بُطُونِهِ} الضمير عائد على الجنس، وعلى المذكور، كما قال الشاعر:\nمثل الفراخ نتفت حواصله\nوهذا كثير، لقوله تعالى: {إنَّ هذِهِ تَذْكِرَةٌ} [الإنسان: 29]، {فَمَن شاءَ ذَكَرَهُ} [المدثر: 55]. وقيل: إنما قال: {مِمّا فِي بُطُونِهِ} لأن الأنعام والنعم واحد فرد، والضمير على معنى: النعم. وقالت فرقة: الضمير عائد على البعض، إذ الذكور لا ألبان لها، فكأن العبرة إنما هي في بعض الأنعام\".\nوذكر ابنُ كثير (8/ 323) في عود الضمير قولين، وعلّق عليهما، فقال: «وأفرد هاهنا الضمير عودًا على معنى: النعم، أو الضمير عائد على الحيوان؛ فإن الأنعام حيوانات، أي: نسقيكم مما في بطن هذا الحيوان، وفي الآية الأخرى: {مما في بطونها} [المؤمنون: 21]، ويجوز هذا وهذا، كما في قوله تعالى: {كلا إنه تذكرة فمن شاء ذكره} [المدثر: 54 - 55]، وفي قوله تعالى: {وإني مرسلة إليهم بهدية فناظرة بم يرجع المرسلون فلما جاء سليمان} [النمل: 35 - 36] أي: المال».", "mawaqif": [{"taliq": 3696, "mi": 0, "aya": 66, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 377 - 378", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3696, "mi": 0, "aya": 66, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "8/ 323", "qawl": "", "nass": "وأفرد هاهنا الضمير عودا على معنى: النعم، أو الضمير عائد على الحيوان؛ فإن الأنعام حيوانات، أي: نسقيكم مما في بطن هذا الحيوان، وفي الآية الأخرى: {مما في بطونها} [المؤمنون: 21]، ويجوز هذا وهذا، كما في قوله تعالى: {كلا إنه تذكرة فمن شاء ذكره} [المدثر: 54 - 55]، وفي قوله تعالى: {وإني مرسلة إليهم بهدية فناظرة بم يرجع المرسلون فلما جاء سليمان} [النمل: 35 - 36] أي: المال", "qawaid": [], "tabi": ""}]}], "68": [{"id": 3698, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (5/ 379) عدة معانٍ للوحي، ثم بيَّن أن الوحي في هذه الآية هو وحي الإلهام باتفاق المتأولين.", "mawaqif": [{"taliq": 3698, "mi": 0, "aya": 68, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 379", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 3699, "kinds": "ترجيح،بيان،نقل", "text": "بيّن ابنُ جرير (14/ 286 - 287) أن قوله: {مما يعرشون} معناه: ما يبنون من السقوف. وذكر قول ابن زيد، ولم يعلق عليه.\nورجّح ابنُ عطية (5/ 379 - 380) أن عَرَشَ معناه: هيَّأ، وأكثر ما يستعمل فيما يكون من اتفاق الأغصان والخشب وترتيب ظلالها، ومنه العريش الذي صُنع لرسول الله صلى الله عليه وسلم يوم بدر، ومن هذا هي لفظة العرش «. ثم ذكر ابن عطية قول ابن زيد، وقول ابن جرير أن يعرشون معناه: ما يبنون من السقوف. وانتقدهما، فقال:» وهذا منهما تفسير غير متقن\". ولم يذكر مستندًا.", "mawaqif": [{"taliq": 3699, "mi": 0, "aya": 68, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "14/ 286 - 287", "qawl": "ابن زيد", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3699, "mi": 0, "aya": 68, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 379 - 380", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3699, "mi": 0, "aya": 68, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "ابن زيد", "nass": "", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "69": [{"id": 3700, "kinds": "تعليق،نقل", "text": "ذكر ابن كثير (8/ 325) قول قتادة ونحوه عن ابن زيد، وعلّق عليه، فقال: «وقال قتادة، وعبد الرحمن بن زيد بن أسلم: {فاسلكي سبل ربك ذللا} أي: مطيعة. فجعلاه حالًا من السالكة».", "mawaqif": [{"taliq": 3700, "mi": 0, "aya": 69, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "8/ 325", "qawl": "قتادة ونحوه", "nass": "وقال قتادة، وعبد الرحمن بن زيد بن أسلم: {فاسلكي سبل ربك ذللا} أي: مطيعة. فجعلاه حالا من السالكة", "qawaid": [], "tabi": ""}]}, {"id": 3702, "kinds": "تعليق،نقل", "text": "قال ابنُ عطية (5/ 381): «وقوله: {فِيهِ شِفاءٌ لِلنّاسِ} الضمير للعسل، قاله الجمهور، ولا يقتضي العموم في كل علة، وفي كل إنسان، بل هو خبر عن أنه يشفي كما يشفي غيره من الأدوية في بعض، وعلى حال دون حال، ففي الآية إخبار منبه على أنه دواء لمّا كَثُرَ الشفاء به، وصار خليطًا ومعينًا للأدوية والأشربة والمعاجين». ثم ذكر هذا الأثر عن ابن عمر، وعلّق عليه بقوله: «وهذا يقتضي أنه يرى الشفاء به على العموم».", "mawaqif": [{"taliq": 3702, "mi": 0, "aya": 69, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 381", "qawl": "", "nass": "وقوله: {فيه شفاء للناس} الضمير للعسل، قاله الجمهور، ولا يقتضي العموم في كل علة، وفي كل إنسان، بل هو خبر عن أنه يشفي كما يشفي غيره من الأدوية في بعض، وعلى حال دون حال، ففي الآية إخبار منبه على أنه دواء لما كثر الشفاء به، وصار خليطا ومعينا للأدوية والأشربة والمعاجين", "qawaid": [], "tabi": ""}]}], "70": [{"id": 3704, "kinds": "توجيه،حصر", "text": "لم يذكر ابنُ جرير (14/ 292) غير قول علي.\nووجّهه ابنُ عطية (5/ 382) بقوله: «وهذا في الأغلب، وهذا لا ينحصر إلى مدة معينة، وإنما هو بحسب إنسان وإنسان، والمعنى: منكم من يرد إلى أرذل عمره؛ ورب من يكون ابن خمسين سنة وهو في أرذل عمره، ورب ابن مائة وتسعين ليس في أرذل عمره».", "mawaqif": [{"taliq": 3704, "mi": 0, "aya": 70, "alam": "ابن عطية", "fil": "وجهه", "kind": "توجيه", "ref": "5/ 382", "qawl": "", "nass": "وهذا في الأغلب، وهذا لا ينحصر إلى مدة معينة، وإنما هو بحسب إنسان وإنسان، والمعنى: منكم من يرد إلى أرذل عمره؛ ورب من يكون ابن خمسين سنة وهو في أرذل عمره، ورب ابن مائة وتسعين ليس في أرذل عمره", "qawaid": [], "tabi": ""}]}], "72": [{"id": 3705, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (14/ 295) غير قول قتادة.", "mawaqif": []}, {"id": 3706, "kinds": "ترجيح،توجيه", "text": "وجَّه ابن عطية (5/ 383) قول قتادة، فقال: «فمن حيث كانا مبتدأ الجميع ساغ حمل أمرهما على الجميع؛ حتى صار الأمر كأن النساء خلقن من أنفس الرجال». ثم رجّح مستندًا إلى النظائر أن «{مِن أنْفُسِكُمْ} أي: من نوعكم، وعلى خلقتكم، كما قال تعالى: {لَقَدْ جاءَكُمْ رَسُولٌ مِن أنْفُسِكُمْ} [التوبة: 128]».", "mawaqif": [{"taliq": 3706, "mi": 0, "aya": 72, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 383", "qawl": "قتادة", "nass": "فمن حيث كانا مبتدأ الجميع ساغ حمل أمرهما على الجميع؛ حتى صار الأمر كأن النساء خلقن من أنفس الرجال", "qawaid": ["القرآن والنظائر"], "tabi": ""}]}], "73": [{"id": 3708, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 387): «وقوله: {يَسْتَطِيعُونَ} على معناها بحسب اعتقاد الكفار في الأصنام أنها تعقل، ويحتمل أن يكون الضمير في {يَسْتَطِيعُونَ} للذين يعبدون، المعنى: لا يستطيعون ذلك ببرهان يُظهِرونه، وحجة يُثبِتونها».", "mawaqif": [{"taliq": 3708, "mi": 0, "aya": 73, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 387", "qawl": "", "nass": "وقوله: {يستطيعون} على معناها بحسب اعتقاد الكفار في الأصنام أنها تعقل، ويحتمل أن يكون الضمير في {يستطيعون} للذين يعبدون، المعنى: لا يستطيعون ذلك ببرهان يظهرونه، وحجة يثبتونها", "qawaid": [], "tabi": ""}]}], "76": [{"id": 3710, "kinds": "نقل", "text": "قال ابنُ عطية (5/ 388 - 389 بتصرف): «ذكر الطبري عن ابن عباس أنه قال: نزلت هذه الآية في عثمان بن عفان، وعبد كان له. وروي تعيين غير هذا، ولا يصح إسناده، والمثل لا يحتاج إلى تعيين أحد».", "mawaqif": [{"taliq": 3710, "mi": 0, "aya": 76, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 388 - 389 بتصرف", "qawl": "", "nass": "ذكر الطبري عن ابن عباس أنه قال: نزلت هذه الآية في عثمان بن عفان، وعبد كان له. وروي تعيين غير هذا، ولا يصح إسناده، والمثل لا يحتاج إلى تعيين أحد", "qawaid": [], "tabi": ""}]}], "78": [{"id": 3712, "kinds": "غيره", "text": "قال ابنُ جرير (14/ 315): «الله -تعالى ذكره- جعل لعباده السمع والأبصار والأفئدة قبل أن يخرجهم من بطون أمهاتهم، وإنما أعطاهم العلم والعقل بعد ما أخرجهم من بطون أمهاتهم».\nوبنحوه قال ابنُ القيم (2/ 117).", "mawaqif": [{"taliq": 3712, "mi": 0, "aya": 78, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "14/ 315", "qawl": "", "nass": "الله -تعالى ذكره- جعل لعباده السمع والأبصار والأفئدة قبل أن يخرجهم من بطون أمهاتهم، وإنما أعطاهم العلم والعقل بعد ما أخرجهم من بطون أمهاتهم", "qawaid": [], "tabi": ""}, {"taliq": 3712, "mi": 0, "aya": 78, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "2/ 117", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}]}], "79": [{"id": 3713, "kinds": "غيره", "text": "قال ابن عطية (5/ 391) في ختام هذه الآية: «والآية عِبرة بيِّنة، تفسيرها تكلُّف بحْت».", "mawaqif": [{"taliq": 3713, "mi": 0, "aya": 79, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 391", "qawl": "", "nass": "والآية عبرة بينة، تفسيرها تكلف بحت", "qawaid": [], "tabi": ""}]}], "80": [{"id": 3714, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 392): «وقوله: {وجعل لكم من جلود الأنعام بيوتا} يحتمل: أن يعمَّ به بيوت الأدم، وبيوت الشعر، وبيوت الصوف؛ لأن هذه هي من الجلود؛ لكونها نابتة فيها. نحا إلى ذلك ابن سلام، ويكون قوله: {ومن أصوافها} ابتداء كلام، كأنه قال: جعل أثاثًا، يريد الملابس والوطاء وغير ذلك. ويحتمل أن يريد بقوله: {من جلود الأنعام}: بيوت الأدم فقط، ويكون: {من أصوافها} عطفًا على قوله {من جلود الأنعام}، أي: جعل بيوتًا أيضًا، ويكون قوله: {أثاثا} نصبًا على الحال».", "mawaqif": [{"taliq": 3714, "mi": 0, "aya": 80, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 392", "qawl": "", "nass": "وقوله: {وجعل لكم من جلود الأنعام بيوتا} يحتمل: أن يعم به بيوت الأدم، وبيوت الشعر، وبيوت الصوف؛ لأن هذه هي من الجلود؛ لكونها نابتة فيها. نحا إلى ذلك ابن سلام، ويكون قوله: {ومن أصوافها} ابتداء كلام، كأنه قال: جعل أثاثا، يريد الملابس والوطاء وغير ذلك. ويحتمل أن يريد بقوله: {من جلود الأنعام}: بيوت الأدم فقط، ويكون: {من أصوافها} عطفا على قوله {من جلود الأنعام}، أي: جعل بيوتا أيضا، ويكون قوله: {أثاثا} نصبا على الحال", "qawaid": [], "tabi": ""}]}, {"id": 3715, "kinds": "خلاف،نقل", "text": "اختُلِف في معنى «الأثاث»: فقيل: هو المال. وقيل: المتاع. وقيل: الثياب.\nوذهب ابنُ جرير (14/ 318)، ومثله ابنُ عطية (5/ 392)، وكذا ابنُ كثير (8/ 337) إلى العموم استنادًا إلى اللغة، وأقوال السلف، قال ابنُ جرير: \"أما الأثاث: فإنه متاع البيت، لم يسمع له بواحد، وهو في أنه لا واحد له مثل المتاع، وقد حكي عن بعض النحويين أنه كان يقول: واحد الأثاث: أثاثة. ولم أر أهل العلم بكلام العرب يعرفون ذلك. ومن الدليل على أن الأثاث هو المتاع قول الشاعر:\nأهاجتك الظعائن يوم بانوا … بذي الرئي الجميل من الأثاث\".\nثم قال: «وأنا أرى أنّ أصل الأثاث: اجتماع بعض المتاع إلى بعض حتى يكثر، كالشعر الأثيث، وهو الكثير الملتف، يقال منه: أثَّ شعَرُ فلانٌ يَئِثُّ أثًّا: إذا كثُر والتفَّ واجتمع». وذكر الآثار السابقة.\nوقال ابنُ عطية: \"الاشتقاق يُقَوِّي هذا المعنى الأعم؛ لأن حال الإنسان تكون بالمال أثيثةً، تقول: شعر أثيث، ونبات أثيث: إذا كثر والتفّ.\nوقال ابنُ كثير: «والصحيح أعم من هذا كله؛ فإنه يتخذ منه الأثاث؛ البسط والثياب وغير ذلك، ويتخذ مالًا وتجارة».", "mawaqif": [{"taliq": 3715, "mi": 0, "aya": 80, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "14/ 318", "qawl": "العموم", "nass": "", "qawaid": ["اللغة", "أقوال السلف"], "tabi": ""}, {"taliq": 3715, "mi": 0, "aya": 80, "alam": "ابن عطية", "fil": "ذهب", "kind": "قول", "ref": "5/ 392", "qawl": "العموم", "nass": "", "qawaid": ["اللغة", "أقوال السلف"], "tabi": "ابن جرير"}, {"taliq": 3715, "mi": 0, "aya": 80, "alam": "ابن كثير", "fil": "وكذا", "kind": "موافقة", "ref": "8/ 337", "qawl": "", "nass": "", "qawaid": ["اللغة", "أقوال السلف"], "tabi": "ابن عطية"}, {"taliq": 3715, "mi": 0, "aya": 80, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "الشاعر", "nass": "وأنا أرى أن أصل الأثاث: اجتماع بعض المتاع إلى بعض حتى يكثر، كالشعر الأثيث، وهو الكثير الملتف، يقال منه: أث شعر فلان يئث أثا: إذا كثر والتف واجتمع", "qawaid": [], "tabi": ""}, {"taliq": 3715, "mi": 0, "aya": 80, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3715, "mi": 0, "aya": 80, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "والصحيح أعم من هذا كله؛ فإنه يتخذ منه الأثاث؛ البسط والثياب وغير ذلك، ويتخذ مالا وتجارة", "qawaid": [], "tabi": ""}]}], "81": [{"id": 3717, "kinds": "تعليق", "text": "عَلَّقَ ابنُ جرير (14/ 322) على هذه القراءة بقوله: «تأويل الكلام على قراءة ابن عباس هذه: كذلك يتم نعمته عليكم بما جعل لكم من السرابيل التي تقيكم بأسكم؛ لتسلموا من السلاح في حروبكم».", "mawaqif": [{"taliq": 3717, "mi": 0, "aya": 81, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "14/ 322", "qawl": "", "nass": "تأويل الكلام على قراءة ابن عباس هذه: كذلك يتم نعمته عليكم بما جعل لكم من السرابيل التي تقيكم بأسكم؛ لتسلموا من السلاح في حروبكم", "qawaid": [], "tabi": ""}]}, {"id": 3718, "kinds": "ترجيح", "text": "رجَّحَ ابنُ جرير (14/ 323) هذه القراءة -وهي قراءة الجمهور- لإجماع الحجة من قراء الأمصار عليها، فقال: «والقراءة التي لا أستجيز القراءة بخلافها بضم التاء من قوله: {لعلكم تُسلِمُون} وكسر اللام، مِن: أسلَمْت تُسْلِم يا هذا؛ لإجماع الحجة من قراء الأمصار عليها».", "mawaqif": [{"taliq": 3718, "mi": 0, "aya": 81, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "14/ 323", "qawl": "", "nass": "والقراءة التي لا أستجيز القراءة بخلافها بضم التاء من قوله: {لعلكم تسلمون} وكسر اللام، من: أسلمت تسلم يا هذا؛ لإجماع الحجة من قراء الأمصار عليها", "qawaid": [], "tabi": ""}]}], "82": [{"id": 3719, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 395): «هذه الآية فيها مُوادَعة، نسختها آية السيف».", "mawaqif": [{"taliq": 3719, "mi": 0, "aya": 82, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 395", "qawl": "", "nass": "هذه الآية فيها موادعة، نسختها آية السيف", "qawaid": [], "tabi": ""}]}], "83": [{"id": 3721, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 396): «حتَمَ على أكثرهم بالكفر، وهم أهل مكة، وذلك أنّه كان فيهم مَن قد داخله الإسلام، ومن أسلم بعد ذلك».", "mawaqif": [{"taliq": 3721, "mi": 0, "aya": 83, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 396", "qawl": "", "nass": "حتم على أكثرهم بالكفر، وهم أهل مكة، وذلك أنه كان فيهم من قد داخله الإسلام، ومن أسلم بعد ذلك", "qawaid": [], "tabi": ""}]}], "84": [{"id": 3722, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 396 بتصرف): «{ولا هم يستعتبون} معناه: يعتبون، يقال: أعتبت الرجل: إذا كفيته ما عتب فيه. فكأنه قال: ولا هم يكفون ما يعتبون فيه، ويشق عليهم. وقال قوم: معناه: لا يسألون أن يرجعوا عما كانوا عليه في الدنيا. فهذا استعتاب معناه: طلب عتابهم. وقال الطبري: معنى يستعتبون: يعطون الرجوع إلى الدنيا؛ فيقع منهم توبة عمل».", "mawaqif": [{"taliq": 3722, "mi": 0, "aya": 84, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 396 بتصرف", "qawl": "", "nass": "{ولا هم يستعتبون} معناه: يعتبون، يقال: أعتبت الرجل: إذا كفيته ما عتب فيه. فكأنه قال: ولا هم يكفون ما يعتبون فيه، ويشق عليهم. وقال قوم: معناه: لا يسألون أن يرجعوا عما كانوا عليه في الدنيا. فهذا استعتاب معناه: طلب عتابهم. وقال الطبري: معنى يستعتبون: يعطون الرجوع إلى الدنيا؛ فيقع منهم توبة عمل", "qawaid": [], "tabi": ""}]}], "85": [{"id": 3723, "kinds": "بيان", "text": "قال ابنُ عطية (5/ 396 - 397): «مقصد الآية: الفرق بين ما يحل بهم وبين رزايا الدنيا، فإن الإنسان لا يتوقع أمرًا من خطوب الدنيا إلا وله طمع في أن يتأخر عنه، وفي أن يجيئه في أخفِّ ما يُتَوَهَّم برجائه، وكذلك متى حلَّ به كان طامعًا في أن يخف، وقد يقع ذلك في خطوب الدنيا كثيرًا، فأخبر الله تعالى أنّ عذاب الآخرة إذا عاينه الكافر لا طماعية فيه بتخفيف ولا تأخير».", "mawaqif": [{"taliq": 3723, "mi": 0, "aya": 85, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 396 - 397", "qawl": "", "nass": "مقصد الآية: الفرق بين ما يحل بهم وبين رزايا الدنيا، فإن الإنسان لا يتوقع أمرا من خطوب الدنيا إلا وله طمع في أن يتأخر عنه، وفي أن يجيئه في أخف ما يتوهم برجائه، وكذلك متى حل به كان طامعا في أن يخف، وقد يقع ذلك في خطوب الدنيا كثيرا، فأخبر الله تعالى أن عذاب الآخرة إذا عاينه الكافر لا طماعية فيه بتخفيف ولا تأخير", "qawaid": [], "tabi": ""}]}], "86": [{"id": 3724, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 397): «الضمير في» القول «عائد على الشركاء، فمَن كان من المعبودين من البشر ألقى القول المعهود بلسانه، وما كان مِن الجمادات تكلمت بقدرة الله بتكذيب المشركين في وصفهم بأنهم آلهة وشركاء لله، ففي هذا وقَع الكذب، لا في العبادة».", "mawaqif": [{"taliq": 3724, "mi": 0, "aya": 86, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 397", "qawl": "", "nass": "الضمير في", "qawaid": [], "tabi": ""}]}], "88": [{"id": 3725, "kinds": "غيره", "text": "قال ابنُ كثير (8/ 341): «هذا دليل على تفاوت الكفار في عذابهم، كما يتفاوت المؤمنون في منازلهم في الجنة ودرجاتهم».", "mawaqif": [{"taliq": 3725, "mi": 0, "aya": 88, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "8/ 341", "qawl": "", "nass": "هذا دليل على تفاوت الكفار في عذابهم، كما يتفاوت المؤمنون في منازلهم في الجنة ودرجاتهم", "qawaid": [], "tabi": ""}]}], "89": [{"id": 3726, "kinds": "غيره", "text": "قال ابنُ كثير (8/ 396) مُعلِّقًا: «قول ابن مسعود أعم وأشمل؛ فإن القرآن اشتمل على كل علم نافع؛ مِن خبر ما سبق، وعلم ما سيأتي، وكل حلال وحرام، وما الناس إليه محتاجون في أمر دنياهم، ودينهم، ومعاشهم، ومعادهم، وهدى أي للقلوب، ورحمة وبشرى للمسلمين».", "mawaqif": [{"taliq": 3726, "mi": 0, "aya": 89, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "8/ 396", "qawl": "", "nass": "قول ابن مسعود أعم وأشمل؛ فإن القرآن اشتمل على كل علم نافع؛ من خبر ما سبق، وعلم ما سيأتي، وكل حلال وحرام، وما الناس إليه محتاجون في أمر دنياهم، ودينهم، ومعاشهم، ومعادهم، وهدى أي للقلوب، ورحمة وبشرى للمسلمين", "qawaid": [], "tabi": ""}]}, {"id": 3727, "kinds": "توجيه", "text": "قال ابنُ عطية (5/ 398): «قوله: {لكل شيء}، أي: مما نحتاج في الشرع، ولا بد منه في المِلَّة، كالحلال والحرام، والدعاء إلى الله والتخويف من عذابه، وهذا حصر ما اقتضته عبارات المفسرين».\nوقال ابن كثير (8/ 343): «ووجه اقتران قوله: {ونزلنا عليك الكتاب} مع قوله: {وجئنا بك شهيدا على هؤلاء} أن المراد -والله أعلم-: أنّ الذي فرض عليك تبليغ الكتاب الذي أنزله عليك سائلك عن ذلك يوم القيامة، {فلنسئلن الذين أرسل إليهم ولنسئلن المرسلين} [الأعراف: 6]، {فو ربك لنسئلنهم أجمعين عما كانوا يعملون} [الحجر: 92 - 93]، {يوم يجمع الله الرسل فيقول ماذا أجبتم قالوا لا علم لنا إنك أنت علام الغيوب} [المائدة: 109]، وقال تعالى: {إن الذي فرض عليك القرآن لرادك إلى معاد} [القصص: 85]، أي: إن الذي أوجب عليك تبليغ القرآن لرادك إليه، ومعيدك يوم القيامة، وسائلك عن أداء ما فرض عليك. هذا أحد الأقوال، وهو متجه حسن».", "mawaqif": [{"taliq": 3727, "mi": 0, "aya": 89, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 398", "qawl": "", "nass": "قوله: {لكل شيء}، أي: مما نحتاج في الشرع، ولا بد منه في الملة، كالحلال والحرام، والدعاء إلى الله والتخويف من عذابه، وهذا حصر ما اقتضته عبارات المفسرين", "qawaid": [], "tabi": ""}, {"taliq": 3727, "mi": 0, "aya": 89, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "8/ 343", "qawl": "", "nass": "ووجه اقتران قوله: {ونزلنا عليك الكتاب} مع قوله: {وجئنا بك شهيدا على هؤلاء} أن المراد -والله أعلم-: أن الذي فرض عليك تبليغ الكتاب الذي أنزله عليك سائلك عن ذلك يوم القيامة، {فلنسئلن الذين أرسل إليهم ولنسئلن المرسلين} [الأعراف: 6]، {فو ربك لنسئلنهم أجمعين عما كانوا يعملون} [الحجر: 92 - 93]، {يوم يجمع الله الرسل فيقول ماذا أجبتم قالوا لا علم لنا إنك أنت علام الغيوب} [المائدة: 109]، وقال تعالى: {إن الذي فرض عليك القرآن لرادك إلى معاد} [القصص: 85]، أي: إن الذي أوجب عليك تبليغ القرآن لرادك إليه، ومعيدك يوم القيامة، وسائلك عن أداء ما فرض عليك. هذا أحد الأقوال، وهو متجه حسن", "qawaid": [], "tabi": ""}]}], "90": [{"id": 3728, "kinds": "نقد،تعليق", "text": "علَّقَ ابن كثير (8/ 345) على هذا الأثر بقوله: «وقد ورد في نزول هذه الآية الكريمة حديث حسن، رواه الإمام أحمد».", "mawaqif": [{"taliq": 3728, "mi": 0, "aya": 90, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "8/ 345", "qawl": "", "nass": "وقد ورد في نزول هذه الآية الكريمة حديث حسن، رواه الإمام أحمد", "qawaid": [], "tabi": ""}]}, {"id": 3729, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 399 بتصرف): «العدل: هو فعل كل مفروض من عقائد وشرائع، وسيرٌ مع الناس في أداء الأمانات، وترْكِ الظلم، والإنصافُ وإعطاءُ الحق. والإحسان: هو فعل كل مندوب إليه. فمن الأشياء ما هو كله مندوب إليه، ومنها ما فرض، إلا أن حدَّ الإجزاء منه داخل في العدل، والتكميل الزائد على حد الإجزاء داخل في الإحسان».", "mawaqif": [{"taliq": 3729, "mi": 0, "aya": 90, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 399 بتصرف", "qawl": "", "nass": "العدل: هو فعل كل مفروض من عقائد وشرائع، وسير مع الناس في أداء الأمانات، وترك الظلم، والإنصاف وإعطاء الحق. والإحسان: هو فعل كل مندوب إليه. فمن الأشياء ما هو كله مندوب إليه، ومنها ما فرض، إلا أن حد الإجزاء منه داخل في العدل، والتكميل الزائد على حد الإجزاء داخل في الإحسان", "qawaid": [], "tabi": ""}]}, {"id": 3730, "kinds": "غيره", "text": "قال ابنُ جرير (14/ 334 - 335): «يقول -تعالى ذِكْرُه-: إن الله يأمر في هذا الكتاب الذي أنزله إليك -يا محمد- بالعدل، وهو الإنصاف، ومن الإنصاف: الإقرار بمن أنعم علينا بنعمته، والشكر له على إفضاله، ونُولي الحمدَ أهلَه. وإذا كان ذلك هو العدل، ولم يكن للأوثان والأصنام عندنا يد تستحق الحمد عليها؛ كان جهلًا بنا حمدُها وعبادتها، وهي لا تنعم فتشكر، ولا تنفع فتعبد، فلزمنا أن نشهد أن لا إله إلا الله، وحده لا شريك له، ولذلك قال مَن قال: العدل في هذا الموضع: شهادة أن لا إله إلا الله».", "mawaqif": [{"taliq": 3730, "mi": 0, "aya": 90, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "14/ 334 - 335", "qawl": "", "nass": "يقول -تعالى ذكره-: إن الله يأمر في هذا الكتاب الذي أنزله إليك -يا محمد- بالعدل، وهو الإنصاف، ومن الإنصاف: الإقرار بمن أنعم علينا بنعمته، والشكر له على إفضاله، ونولي الحمد أهله. وإذا كان ذلك هو العدل، ولم يكن للأوثان والأصنام عندنا يد تستحق الحمد عليها؛ كان جهلا بنا حمدها وعبادتها، وهي لا تنعم فتشكر، ولا تنفع فتعبد، فلزمنا أن نشهد أن لا إله إلا الله، وحده لا شريك له، ولذلك قال من قال: العدل في هذا الموضع: شهادة أن لا إله إلا الله", "qawaid": [], "tabi": ""}]}, {"id": 3731, "kinds": "بيان،تعليق", "text": "علَّقَ ابنُ عطية (5/ 399 - 400 بتصرف) على كلام ابن عباس هذا بقوله: «في هذا نظر؛ لأن أداء الفرائض هي الإسلام حسبما فسره رسول الله صلى الله عليه وسلم في حديث سؤال جبريل عليه السلام، وذلك هو العدل، وإنما الإحسان التكميلات والمندوب إليه، حسبما يقتضيه تفسير النبي صلى الله عليه وسلم لسؤال جبريل عليه السلام، بقوله: «أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك». فإن صحَّ هذا عن ابن عباس فإنما أراد: أداء الفرائض مُكَمَّلَة».", "mawaqif": [{"taliq": 3731, "mi": 0, "aya": 90, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 399 - 400 بتصرف", "qawl": "", "nass": "في هذا نظر؛ لأن أداء الفرائض هي الإسلام حسبما فسره رسول الله صلى الله عليه وسلم في حديث سؤال جبريل عليه السلام، وذلك هو العدل، وإنما الإحسان التكميلات والمندوب إليه، حسبما يقتضيه تفسير النبي صلى الله عليه وسلم لسؤال جبريل عليه السلام، بقوله: «أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك", "qawaid": [], "tabi": ""}]}, {"id": 3732, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 400): «{وإيتاء ذي القربى} لفظة تقتضي صلة الرحم، وتعُمُّ جميع إسداء الخير إلى القرابة، وترْكُه مبهمًا أبلغ؛ لأن كل مَن وصل في ذلك إلى غاية -وإن عَلَت- يرى أنه مقصِّر، وهذا المعنى المأمور به في جانب ذي القربى داخل تحت العدل، والإحسان، لكنه تعالى خصَّه بالذكر اهتمامًا به، وحضًّا عليه».", "mawaqif": [{"taliq": 3732, "mi": 0, "aya": 90, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 400", "qawl": "", "nass": "{وإيتاء ذي القربى} لفظة تقتضي صلة الرحم، وتعم جميع إسداء الخير إلى القرابة، وتركه مبهما أبلغ؛ لأن كل من وصل في ذلك إلى غاية -وإن علت- يرى أنه مقصر، وهذا المعنى المأمور به في جانب ذي القربى داخل تحت العدل، والإحسان، لكنه تعالى خصه بالذكر اهتماما به، وحضا عليه", "qawaid": [], "tabi": ""}]}, {"id": 3733, "kinds": "غيره", "text": "ذَهَبَ ابنُ جرير (14/ 336) مستندًا إلى قول ابن عباس إلى أنّ: «الفحشاء في هذا الموضع: الزنا».", "mawaqif": [{"taliq": 3733, "mi": 0, "aya": 90, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "14/ 336", "qawl": "ابن عباس", "nass": "الفحشاء في هذا الموضع: الزنا", "qawaid": ["أقوال السلف"], "tabi": ""}]}], "91": [{"id": 3736, "kinds": "غيره", "text": "قال ابن عطية (5/ 401 بتصرف): «عهد الله لفظ عام لجميع ما يعقد باللسان، ويلتزمه الإنسان؛ من بيع، أو صلة، أو مواثقة في أمر موافق للديانة، وقوله: {ولا تنقضوا الأيمان} خصَّ في هذه الألفاظ العهود التي تقترن بها أيمان تهمُّمًا بها، وتنبيهًا عليها. وهذا في كل ما كان الثبوت فيه على اليمين طاعة لله، وما كان الانصراف عنه أصوب في الحق، فهو الذي قال فيه رسول الله صلى الله عليه وسلم: «مَن حلف على يمين، ثم رأى غيرها خيرًا منها؛ فليكفر عن يمينه، ولْيَأْتِ الذي هو خير»».\nوبنحوه قال ابنُ كثير (8/ 347 - 348).", "mawaqif": [{"taliq": 3736, "mi": 0, "aya": 91, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 401 بتصرف", "qawl": "", "nass": "عهد الله لفظ عام لجميع ما يعقد باللسان، ويلتزمه الإنسان؛ من بيع، أو صلة، أو مواثقة في أمر موافق للديانة، وقوله: {ولا تنقضوا الأيمان} خص في هذه الألفاظ العهود التي تقترن بها أيمان تهمما بها، وتنبيها عليها. وهذا في كل ما كان الثبوت فيه على اليمين طاعة لله، وما كان الانصراف عنه أصوب في الحق، فهو الذي قال فيه رسول الله صلى الله عليه وسلم: «من حلف على يمين، ثم رأى غيرها خيرا منها؛ فليكفر عن يمينه، وليأت الذي هو خير»", "qawaid": [], "tabi": ""}, {"taliq": 3736, "mi": 0, "aya": 91, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "8/ 347 - 348", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}], "92": [{"id": 3737, "kinds": "ترجيح", "text": "رجَّحَ ابنُ كثير (8/ 349) أن يكون هذا مثلًا ضربه الله تعالى لمن نقض عهده بعد توكيده، كما قال مجاهد، وقتادة، وابن زيد؛ لأنه أعمّ، فقال: «وهذا القول أرجح وأظهر، سواء كان بمكة امرأة تنقض غزلها أم لا».", "mawaqif": [{"taliq": 3737, "mi": 0, "aya": 92, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "8/ 349", "qawl": "", "nass": "وهذا القول أرجح وأظهر، سواء كان بمكة امرأة تنقض غزلها أم لا", "qawaid": [], "tabi": ""}]}, {"id": 3739, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 404): «ويحتمل أن يكون القول معناه: لا تنقضوا الأيمان من أجل أن تكونوا أربى من غيركم، أي: أزيد خيرًا، فمعناه: لا تطلبوا الزيادة بعضكم على بعض بنقض العهود».", "mawaqif": [{"taliq": 3739, "mi": 0, "aya": 92, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 404", "qawl": "", "nass": "ويحتمل أن يكون القول معناه: لا تنقضوا الأيمان من أجل أن تكونوا أربى من غيركم، أي: أزيد خيرا، فمعناه: لا تطلبوا الزيادة بعضكم على بعض بنقض العهود", "qawaid": [], "tabi": ""}]}, {"id": 3740, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 404): «والضمير في {به} يحتمل: أن يعود على الوفاء الذي أمر الله به، ويحتمل: أن يعود على الربا، أي: أن الله تعالى ابتلى عباده بالتحاسد، وطلب بعضهم الظهور على بعض، واختبرهم بذلك ليرى من يجاهد نفسه ممن يتبعها هواها».", "mawaqif": [{"taliq": 3740, "mi": 0, "aya": 92, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 404", "qawl": "", "nass": "والضمير في {به} يحتمل: أن يعود على الوفاء الذي أمر الله به، ويحتمل: أن يعود على الربا، أي: أن الله تعالى ابتلى عباده بالتحاسد، وطلب بعضهم الظهور على بعض، واختبرهم بذلك ليرى من يجاهد نفسه ممن يتبعها هواها", "qawaid": [], "tabi": ""}]}], "102": [{"id": 3745, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 408): «وقوله: {بالحق} أي: مع الحق في أوامره ونواهيه وأحكامه ومصالحه وأخباره. ويحتمل أن يكون قوله بالحق بمعنى: حقًّا. ويحتمل أن يريد بالحق: في أن ينزل، أي: أنه واجب لمعنى المصلحة أن ينزل. وعلى هذا الاحتمال اعتراضات عند أصحاب الكلام على أصول الدين».", "mawaqif": [{"taliq": 3745, "mi": 0, "aya": 102, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 408", "qawl": "", "nass": "وقوله: {بالحق} أي: مع الحق في أوامره ونواهيه وأحكامه ومصالحه وأخباره. ويحتمل أن يكون قوله بالحق بمعنى: حقا. ويحتمل أن يريد بالحق: في أن ينزل، أي: أنه واجب لمعنى المصلحة أن ينزل. وعلى هذا الاحتمال اعتراضات عند أصحاب الكلام على أصول الدين", "qawaid": [], "tabi": ""}]}], "103": [{"id": 3746, "kinds": "نقد", "text": "استدرك ابنُ عطية (5/ 410) على هذا القول مستندًا إلى التاريخ قائلًا: «هذا نصراني أسلم وكتب، ثم ارتد ولحق بمكة ومات، ثم لفظته الأرض، وإلا فهذا القول يضعف؛ لأن الكاتب المشهور الذي ارتد لهذا السبب ولغيره من نحوه هو عبد الله بن أبي سرح العامري، ولسانه ليس بأعجمي. فتأمله».", "mawaqif": [{"taliq": 3746, "mi": 0, "aya": 103, "alam": "ابن عطية", "fil": "استدرك", "kind": "نقد", "ref": "5/ 410", "qawl": "مستندا إلى", "nass": "هذا نصراني أسلم وكتب، ثم ارتد ولحق بمكة ومات، ثم لفظته الأرض، وإلا فهذا القول يضعف؛ لأن الكاتب المشهور الذي ارتد لهذا السبب ولغيره من نحوه هو عبد الله بن أبي سرح العامري، ولسانه ليس بأعجمي. فتأمله", "qawaid": ["التاريخ والواقع"], "tabi": ""}]}, {"id": 3747, "kinds": "نقد", "text": "انتَقَدَ ابنُ عطية (5/ 408) هذا القول قائلًا: «هذا ضعيف؛ لأن سلمان إنما أسلم بعد الهجرة بمدة».\nوبنحوه ابنُ كثير (8/ 356).", "mawaqif": [{"taliq": 3747, "mi": 0, "aya": 103, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "5/ 408", "qawl": "قائلا", "nass": "هذا ضعيف؛ لأن سلمان إنما أسلم بعد الهجرة بمدة", "qawaid": [], "tabi": ""}, {"taliq": 3747, "mi": 0, "aya": 103, "alam": "ابن كثير", "fil": "وبنحوه", "kind": "موافقة", "ref": "8/ 356", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}], "106": [{"id": 3748, "kinds": "غيره", "text": "ذَهَبَ ابنُ تيمية (4/ 185) إلى هذا القول مستندًا إلى التاريخ، فقال: «الآية نزلت في عمار بن ياسر وبلال بن رباح وأمثالهما من المؤمنين المستضعفين لما أكرههم المشركون على سب النبي صلى الله عليه وسلم ونحو ذلك من كلمات الكفر، فمنهم من أجاب بلسانه كعمار، ومنهم من صبر على المحنة كبلال، ولم يكره أحد منهم على خلاف ما في قلبه، بل أكرهوا على التكلم، فمن تكلم بدون الإكراه لم يتكلم إلا وصدره منشرح به».", "mawaqif": [{"taliq": 3748, "mi": 0, "aya": 106, "alam": "ابن تيمية", "fil": "ذهب", "kind": "قول", "ref": "4/ 185", "qawl": "مستندا إلى", "nass": "الآية نزلت في عمار بن ياسر وبلال بن رباح وأمثالهما من المؤمنين المستضعفين لما أكرههم المشركون على سب النبي صلى الله عليه وسلم ونحو ذلك من كلمات الكفر، فمنهم من أجاب بلسانه كعمار، ومنهم من صبر على المحنة كبلال، ولم يكره أحد منهم على خلاف ما في قلبه، بل أكرهوا على التكلم، فمن تكلم بدون الإكراه لم يتكلم إلا وصدره منشرح به", "qawaid": ["التاريخ والواقع"], "tabi": ""}]}, {"id": 3749, "kinds": "نقد", "text": "انتَقَدَ ابنُ تيمية (4/ 184) هذا القول مستندًا إلى زمن النزول، فقال: «هو باطل؛ فإن هذه الآية نزلت بمكة، لما أكره عمار وبلال على الكفر، وردة هذا كانت بالمدينة بعد الهجرة، ولو قُدِّر أنه نزلت فيه هذه الآية فالنبي صلى الله عليه وسلم قد قَبِلَ إسلامه وبايعه».", "mawaqif": [{"taliq": 3749, "mi": 0, "aya": 106, "alam": "ابن تيمية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 184", "qawl": "مستندا إلى", "nass": "هو باطل؛ فإن هذه الآية نزلت بمكة، لما أكره عمار وبلال على الكفر، وردة هذا كانت بالمدينة بعد الهجرة، ولو قدر أنه نزلت فيه هذه الآية فالنبي صلى الله عليه وسلم قد قبل إسلامه وبايعه", "qawaid": ["سبب النزول وأحواله"], "tabi": ""}]}, {"id": 3750, "kinds": "غيره", "text": "قال ابنُ كثير (8/ 358 - 360 بتصرّف): «اتفق العلماء على أنّ المكره على الكفر يجوز له أن يوالي إبقاء لمهجته، ويجوز له أن يستقتل كما كان بلال رضي الله عنهما يأبى عليهم ذلك وهم يفعلون به الأفاعيل، والأفضل والأولى أن يثبت المسلم على دينه، ولو أفضى إلى قتله».", "mawaqif": [{"taliq": 3750, "mi": 0, "aya": 106, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "8/ 358 - 360 بتصرف", "qawl": "", "nass": "اتفق العلماء على أن المكره على الكفر يجوز له أن يوالي إبقاء لمهجته، ويجوز له أن يستقتل كما كان بلال رضي الله عنهما يأبى عليهم ذلك وهم يفعلون به الأفاعيل، والأفضل والأولى أن يثبت المسلم على دينه، ولو أفضى إلى قتله", "qawaid": [], "tabi": ""}]}], "110": [{"id": 3751, "kinds": "تعليق،نقل", "text": "علَّقَ ابنُ عطية (5/ 416) على هذا القول قائلًا: «جاءت هذه الرواية هكذا أنهم بعد نزول الآية خرجوا، فيجيء الجهاد الذي ذكر في الآية جهادهم مع رسول الله صلى الله عليه وسلم. وروت طائفة أنهم خرجوا وأتبعوا، وجاهدوا متبعيهم، فقتل من قتل، ونجا من نجا؛ فنزلت الآية حينئذ. فمعنى الجهاد المذكور: جهادهم لمتبعيهم».", "mawaqif": [{"taliq": 3751, "mi": 0, "aya": 110, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 416", "qawl": "قائلا", "nass": "جاءت هذه الرواية هكذا أنهم بعد نزول الآية خرجوا، فيجيء الجهاد الذي ذكر في الآية جهادهم مع رسول الله صلى الله عليه وسلم. وروت طائفة أنهم خرجوا وأتبعوا، وجاهدوا متبعيهم، فقتل من قتل، ونجا من نجا؛ فنزلت الآية حينئذ. فمعنى الجهاد المذكور: جهادهم لمتبعيهم", "qawaid": [], "tabi": ""}]}, {"id": 3752, "kinds": "بيان،تعليق،نقل", "text": "علَّقَ ابنُ عطية (5/ 416) على هذه القول قائلًا: «وذِكْرُ عمار في هذا عندي غير قويم؛ فإنه أرفع من طبقة هؤلاء، وإنما هؤلاء مَن شرح بالكفر صدرًا فتح الله لهم باب التوبة في آخر الآية».", "mawaqif": [{"taliq": 3752, "mi": 0, "aya": 110, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 416", "qawl": "قائلا", "nass": "وذكر عمار في هذا عندي غير قويم؛ فإنه أرفع من طبقة هؤلاء، وإنما هؤلاء من شرح بالكفر صدرا فتح الله لهم باب التوبة في آخر الآية", "qawaid": [], "tabi": ""}]}, {"id": 3753, "kinds": "توجيه،تعليق", "text": "وجَّه ابن عطية (5/ 416) قول عكرمة والحسن بقوله: «فكأنه قال: مِن بعد ما فتنهم الشيطان». ثم علَّق بقوله: «وهذه الآية مدنية، ولا أعلم في ذلك خلافًا، وإن وجد فهو ضعيف».", "mawaqif": [{"taliq": 3753, "mi": 0, "aya": 110, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 416", "qawl": "عكرمة والحسن", "nass": "فكأنه قال: من بعد ما فتنهم الشيطان", "qawaid": [], "tabi": ""}]}], "111": [{"id": 3754, "kinds": "نقد،نقل", "text": "قال ابنُ عطية (5/ 417): «وظاهر الآية أن كل نفس تُجادِلُ؛ مؤمنة كانت أو كافرة، فإذا جادل الكفار بكذبهم وجحدهم للكفر شهدت عليهم الجوارح والرسل وغير ذلك بحسب الطوائف، فحينئذ لا ينطقون، ولا يؤذن لهم فيعتذرون، فتجتمع آيات القرآن باختلاف المواطن». ثم ذكر قولًا آخر، وانتقده مستندًا إلى الدلالة العقلية، فقال: «وقالت فرقة: الجدال: قول كل أحد من الأنبياء وغيرهم: نفسي نفسي، وهذا ليس بجدال ولا احتجاج إنما هو مجرد رغبة».", "mawaqif": [{"taliq": 3754, "mi": 0, "aya": 111, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 417", "qawl": "", "nass": "وظاهر الآية أن كل نفس تجادل؛ مؤمنة كانت أو كافرة، فإذا جادل الكفار بكذبهم وجحدهم للكفر شهدت عليهم الجوارح والرسل وغير ذلك بحسب الطوائف، فحينئذ لا ينطقون، ولا يؤذن لهم فيعتذرون، فتجتمع آيات القرآن باختلاف المواطن", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}], "113": [{"id": 3757, "kinds": "نقل", "text": "قال ابنُ عطية (5/ 420): «والضمير في {جاءَهُمْ} لأهل مكة، والرسول محمد صلى الله عليه وسلم، والعَذابُ: الجوع، وأمر بدر ونحو ذلك إن كان التمثيل بمكة وكانت الآية مدنية، وإن كانت مكية فهو الجوع فقط، وذكر الطبري أنه القتل ببدر، وهذا يقتضي أن الآية نزلت بالمدينة. وإن كان التمثيل بمدينة قديمة غير معينة، فيحتمل أن يكون الضمير في {جاءَهُمْ} لأهل تلك المدينة، ويكون هذا مما جرى فيها كمدينة شعيب وغيره. ويحتمل أن يكون الضمير المذكور لأهل مكة. فتأمل».", "mawaqif": [{"taliq": 3757, "mi": 0, "aya": 113, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 420", "qawl": "", "nass": "والضمير في {جاءهم} لأهل مكة، والرسول محمد صلى الله عليه وسلم، والعذاب: الجوع، وأمر بدر ونحو ذلك إن كان التمثيل بمكة وكانت الآية مدنية، وإن كانت مكية فهو الجوع فقط، وذكر الطبري أنه القتل ببدر، وهذا يقتضي أن الآية نزلت بالمدينة. وإن كان التمثيل بمدينة قديمة غير معينة، فيحتمل أن يكون الضمير في {جاءهم} لأهل تلك المدينة، ويكون هذا مما جرى فيها كمدينة شعيب وغيره. ويحتمل أن يكون الضمير المذكور لأهل مكة. فتأمل", "qawaid": [], "tabi": ""}]}], "114": [{"id": 3758, "kinds": "نقد،بيان،نقل", "text": "قال ابنُ جرير (14/ 387 - 388): «قوله تعالى: {فكلوا مما رزقكم الله حلالا طيبا، واشكروا نعمة الله إن كنتم إياه تعبدون}، يقول -تعالى ذكره-: فكلوا -أيها الناس- مما رزقكم الله من بهائم الأنعام التي أحلها لكم حلالًا طيبًا مذكاة غير محرمة عليكم». ثم ذكر قولًا آخر، فقال: «وكان بعضهم يقول: إنما عنى بقوله: {فكلوا مما رزقكم الله حلالا طيبا}: طعامًا كان بَعَث به رسول الله صلى الله عليه وسلم إلى المشركين من قومه في سني الجدب والقحط رقة عليهم، فقال الله تعالى للمشركين: {فكلوا مما رزقكم الله} من هذا الذي بعث به إليكم {حلالًا طيبًا}». وانتقده مستندًا إلى السياق، فقال: «وذلك تأويل بعيد مما يدل عليه ظاهر التنزيل، وذلك أن الله تعالى قد أتبع ذلك بقوله: {إنما حرم عليكم الميتة والدم} الآية والتي بعدها، فبين بذلك أن قوله: {فكلوا مما رزقكم الله حلالا طيبا} إعلامٌ من الله عباده أن ما كان المشركون يحرمونه من البحائر والسوائب والوصائل وغير ذلك مما قد بينا قبل فيما مضى لا معنى له؛ إذ كان ذلك من خطوات الشيطان، فإن كل ذلك حلال لم يحرم الله منه شيئًا».\nووافقه ابنُ عطية (5/ 420) بقوله: «وكذلك هو فاسد من غير وجه».", "mawaqif": [{"taliq": 3758, "mi": 0, "aya": 114, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "14/ 387 - 388", "qawl": "", "nass": "قوله تعالى: {فكلوا مما رزقكم الله حلالا طيبا، واشكروا نعمة الله إن كنتم إياه تعبدون}، يقول -تعالى ذكره-: فكلوا -أيها الناس- مما رزقكم الله من بهائم الأنعام التي أحلها لكم حلالا طيبا مذكاة غير محرمة عليكم", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3758, "mi": 0, "aya": 114, "alam": "ابن عطية", "fil": "ووافقه", "kind": "موافقة", "ref": "5/ 420", "qawl": "", "nass": "وكذلك هو فاسد من غير وجه", "qawaid": [], "tabi": "ابن جرير"}]}], "115": [{"id": 3759, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 422): «وقوله: {فمن اضطر} قالت فرقة: معناه: أكره. وقال الجمهور: معناه: اضطره جوع واحتياج».", "mawaqif": [{"taliq": 3759, "mi": 0, "aya": 115, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 422", "qawl": "", "nass": "وقوله: {فمن اضطر} قالت فرقة: معناه: أكره. وقال الجمهور: معناه: اضطره جوع واحتياج", "qawaid": [], "tabi": ""}]}], "116": [{"id": 3761, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (14/ 391) غير قول مجاهد.", "mawaqif": []}, {"id": 3762, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 423): «هذه مخاطبة للكفار الذين حرَّموا البحائر والسوائب، وأحلوا ما في بطون بعض الأنعام وإن كانت ميتة، يدل على ذلك قوله حكاية عنهم: {وإنْ يَكُنْ مَيْتَةً فَهُمْ فِيهِ شُرَكاءُ} [الأنعام: 139]، والآية تقتضي كل ما كان لهم من تحليل وتحريم، فإنه كله افتراء منهم، ومنه ما فعلوه في الشهور».", "mawaqif": [{"taliq": 3762, "mi": 0, "aya": 116, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 423", "qawl": "", "nass": "هذه مخاطبة للكفار الذين حرموا البحائر والسوائب، وأحلوا ما في بطون بعض الأنعام وإن كانت ميتة، يدل على ذلك قوله حكاية عنهم: {وإن يكن ميتة فهم فيه شركاء} [الأنعام: 139]، والآية تقتضي كل ما كان لهم من تحليل وتحريم، فإنه كله افتراء منهم، ومنه ما فعلوه في الشهور", "qawaid": [], "tabi": ""}]}, {"id": 3763, "kinds": "نقل", "text": "قال ابنُ عطية (5/ 424): «وقوله: {لِتَفْتَرُوا عَلى اللَّهِ الكَذِبَ} إشارة إلى قولهم في فواحشهم التي هذه إحداها: {وجدنا عليها آباءنا والله أمرنا بها}. ويحتمل أن يريد: أنّه كان شرعهم؛ لاتباعهم سننًا لا يرضاها الله افتراء عليه؛ لأنّ مَن شرع أمرًا فكأنه قال لأتباعه: هذا هو الحق، وهذا مراد الله».", "mawaqif": [{"taliq": 3763, "mi": 0, "aya": 116, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 424", "qawl": "", "nass": "وقوله: {لتفتروا على الله الكذب} إشارة إلى قولهم في فواحشهم التي هذه إحداها: {وجدنا عليها آباءنا والله أمرنا بها}. ويحتمل أن يريد: أنه كان شرعهم؛ لاتباعهم سننا لا يرضاها الله افتراء عليه؛ لأن من شرع أمرا فكأنه قال لأتباعه: هذا هو الحق، وهذا مراد الله", "qawaid": [], "tabi": ""}]}], "119": [{"id": 3764, "kinds": "نقل", "text": "قال ابنُ عطية (5/ 425): «وقوله: {ثم إن ربك للذين عملوا السوء} إشارة إلى الكفار الذين افتروا على الله، وفعلوا الأفاعيل المذكورة، فهم إذا تابوا من كفرهم بالإيمان وأصلحوا من أعمال الإسلام غفر الله لهم، وتناولت هذه الآية بعد ذلك كل واقع تحت لفظها مِن كافر وعاصٍ».", "mawaqif": [{"taliq": 3764, "mi": 0, "aya": 119, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 425", "qawl": "", "nass": "وقوله: {ثم إن ربك للذين عملوا السوء} إشارة إلى الكفار الذين افتروا على الله، وفعلوا الأفاعيل المذكورة، فهم إذا تابوا من كفرهم بالإيمان وأصلحوا من أعمال الإسلام غفر الله لهم، وتناولت هذه الآية بعد ذلك كل واقع تحت لفظها من كافر وعاص", "qawaid": [], "tabi": ""}]}, {"id": 3765, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 425): \"والجهالة عندي في هذا الموضع ليست ضد العلم، بل هي تعدي الطور وركوب الرأس، ومنه قول النبي صلى الله عليه وسلم: «أو أجهل، أو يُجْهَل عَلَيَّ». وهي التي في قول الشاعر:\nألا لا يجهلن أحد علينا … فنجهل فوق جهل الجاهلينا\nوالجهالة التي هي ضد العلم تصحب هذه الأخرى كثيرًا، ولكن يخرج منها المتعمد، وهو الأكثر، وقلما يوجد في العصاة من لم يتقدم له علم بخطر المعصية التي تُواقع\".", "mawaqif": [{"taliq": 3765, "mi": 0, "aya": 119, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 425", "qawl": "النبي صلى", "nass": "أو أجهل، أو يجهل علي", "qawaid": [], "tabi": ""}]}], "122": [{"id": 3767, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (14/ 397 - 398) غير قول قتادة ومجاهد.\nوقال ابنُ عطية (5/ 427): «وقوله: {وآتيناه في الدنيا حسنة} الآية، الحسنة لسان الصدق وإمامته لجميع الخلق، هذا قول جميع المفسرين، وذلك أنّ كل أمة متشرعة فهي مُقِرَّة أن إيمانها إيمان إبراهيم، وأنه قدوتها، وأنه كان على الصواب».", "mawaqif": [{"taliq": 3767, "mi": 0, "aya": 122, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 427", "qawl": "", "nass": "وقوله: {وآتيناه في الدنيا حسنة} الآية، الحسنة لسان الصدق وإمامته لجميع الخلق، هذا قول جميع المفسرين، وذلك أن كل أمة متشرعة فهي مقرة أن إيمانها إيمان إبراهيم، وأنه قدوتها، وأنه كان على الصواب", "qawaid": [], "tabi": ""}]}, {"id": 3768, "kinds": "غيره", "text": "قال ابنُ عطية (5/ 427): «وقوله: {لَمِنَ الصّالِحِينَ} بمعنى: المنعم عليهم، أي: من الصالحين في أحوالهم ومراتبهم، أو بمعنى: أنه في الآخرة ممن يحكم له بحكم الصالحين في الدنيا، وهذا على أن الآية وصف حاليه في الدارين، ويحتمل أن يكون المعنى: في أعمال الآخرة، فعلى هذا هي وصف حالته في الأعمال الدنيوية والأخروية».", "mawaqif": [{"taliq": 3768, "mi": 0, "aya": 122, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "5/ 427", "qawl": "", "nass": "وقوله: {لمن الصالحين} بمعنى: المنعم عليهم، أي: من الصالحين في أحوالهم ومراتبهم، أو بمعنى: أنه في الآخرة ممن يحكم له بحكم الصالحين في الدنيا، وهذا على أن الآية وصف حاليه في الدارين، ويحتمل أن يكون المعنى: في أعمال الآخرة، فعلى هذا هي وصف حالته في الأعمال الدنيوية والأخروية", "qawaid": [], "tabi": ""}]}], "124": [{"id": 3769, "kinds": "نقل", "text": "ذكر ابنُ عطية (5/ 428 - 429) ما جاء في هذا الحديث وغيره، ثم قال معلِّقًا: «فليس الاختلاف المذكور في الآية هو الاختلاف الذي في الحديث».", "mawaqif": [{"taliq": 3769, "mi": 0, "aya": 124, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 428 - 429", "qawl": "", "nass": "فليس الاختلاف المذكور في الآية هو الاختلاف الذي في الحديث", "qawaid": [], "tabi": ""}]}], "126": [{"id": 3771, "kinds": "خلاف،نقد،تعليق،نقل", "text": "أورد ابنُ عطية (5/ 429 - 430) في نزول الآية قولين، فقال: «وقوله: {وإنْ عاقَبْتُمْ فَعاقِبُوا} الآية، أطبق أهل التفسير أن هذه الآية مدنية نزلت في شأن التمثيل بحمزة في يوم أحد، ووقع ذلك في صحيح البخاري، وفي كتاب السير، وذهب النحاس إلى أنها مكية». وعلَّق على القول بمكيتها بقوله: «والمعنى متصل بما قبلها من المكي اتصالًا حسنًا؛ لأنها تتدرج الرُّتَب من الذي يُدعى ويوعظ، إلى الذي يجادل، إلى الذي يجازى على فعله». ثم انتقده مستندًا إلى السياق، والتاريخ بقوله: «ولكن ما روى الجمهور أثبت، وأيضًا فقوله: {ولَئِنْ صَبَرْتُمْ} تعلَّق بمعنى الآية على ما روى الجمع: أنّ كفار قريش لما مثلوا بحمزة وقع ذلك مِن نفس رسول الله صلى الله عليه وسلم، فقال: «لئن أظفرني الله بهم لأمثلن بثلاثين». وفي كتاب النحاس وغيره: «بسبعين منهم». فقال الناس: إن ظفرنا لنفعلن ولنفعلن. فنزلت هذه الآية».", "mawaqif": [{"taliq": 3771, "mi": 0, "aya": 126, "alam": "ابن عطية", "fil": "أورد", "kind": "نقل", "ref": "5/ 429 - 430", "qawl": "", "nass": "وقوله: {وإن عاقبتم فعاقبوا} الآية، أطبق أهل التفسير أن هذه الآية مدنية نزلت في شأن التمثيل بحمزة في يوم أحد، ووقع ذلك في صحيح البخاري، وفي كتاب السير، وذهب النحاس إلى أنها مكية", "qawaid": ["السياق", "التاريخ والواقع"], "tabi": ""}]}, {"id": 3773, "kinds": "خلاف،تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 431) اختلاف أهل العلم فيمن ظلمه رجلٌ في أخذ مال، ثم ائتمن الظالم المظلوم على مال؛ تجوز له خيانته في القدر الذي ظلمه؟! وقال: «فقالت فرقة: له ذلك. منهم ابن سيرين، وإبراهيم النخعي، وسفيان، ومجاهد، واحتجت بهذه الآية، وعموم لفظها. وقال مالك وفرقة معه: لا يجوز له ذلك». وعلّق على قول مالك بقوله: «ويتقوى في أمر المال قول مالك?؛ لأن الخيانة لاحقة في ذلك، وهي رذيلة لا انفكاك عنها، ولا ينبغي للمرء أن يتأسى بغيره في الرذائل، وإنما ينبغي أن يتجنبها لنفسها، وأما الرجل يظلم في المال، ثم يتمكن من الانتصاف دون أن يؤتمن فيشبه أن ذلك له جائز، يرى أنّ الله حكم له كما لو تمكن له بالحكم من الحاكم».", "mawaqif": [{"taliq": 3773, "mi": 0, "aya": 126, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 431", "qawl": "", "nass": "فقالت فرقة: له ذلك. منهم ابن سيرين، وإبراهيم النخعي، وسفيان، ومجاهد، واحتجت بهذه الآية، وعموم لفظها. وقال مالك وفرقة معه: لا يجوز له ذلك", "qawaid": [], "tabi": ""}]}], "127": [{"id": 3774, "kinds": "خلاف،ترجيح،نقل", "text": "ذكر ابنُ عطية (5/ 431) في عود الضمير من قوله: {عليهم} قولين، فقال: «والضمير في قوله: {عَلَيْهِمْ} قيل: يعود على الكفار، أي: لا تتأسف على أن لم يسلموا. وقالت فرقة: بل يعود على القتلى: حمزة وأصحابه الذين حزن عليهم رسول الله صلى الله عليه وسلم».\nثم رجح مستندًا إلى اللغة القول الأول، فقال: «والأول أصوب؛ إذ يكون عود الضمائر على جهة واحدة».", "mawaqif": [{"taliq": 3774, "mi": 0, "aya": 127, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 431", "qawl": "", "nass": "والضمير في قوله: {عليهم} قيل: يعود على الكفار، أي: لا تتأسف على أن لم يسلموا. وقالت فرقة: بل يعود على القتلى: حمزة وأصحابه الذين حزن عليهم رسول الله صلى الله عليه وسلم", "qawaid": ["اللغة"], "tabi": ""}]}]}, "athar": {"41474": {"num": 41474, "aya": 62, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وتصف ألسنتهم الكذب}، أي: يَتكلَّمون."}, "41475": {"num": 41475, "aya": 62, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وتصف ألسنتهم الكذب}، أي: يتكلمون به، ويعلنون به."}, "42029": {"num": 42029, "aya": 97, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في قوله: {حياة طيّبة}، قال: الكسب الطيب، والعمل الصالح."}, "41989": {"num": 41989, "aya": 92, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {تتخذون أيمانكم دخلا بينكم}: يَغُرُّ بها؛ يعطيه العهد يؤمِّنه، ويُنزِلُه من مأمنه، فتزل قدمه، وهو في مأمن، ثم يعود يريد الغدر. قال: فأول بُدُوِّ هذا قومٌ كانوا حلفاءَ لقوم تحالفوا، وأعطى بعضُهم بعضًا العهد، فجاءهم قومٌ، قالوا: نحن أكثر وأعز وأمنع؛ فانقضوا عهد هؤلاء، وارجعوا إلينا. ففعلوا، وذلك قول -تعالى ذكره-: {ولا تنقضوا الأيمان بعد توكيدها وقد جعلتم الله عليكم كفيلا} - {أن تكون أمة هي أربى من أمة}: هي أربى: أكثر؛ من أجل أن كانوا هؤلاء أكثر من أولئك نقضتم العهد فيما بينكم وبين هؤلاء؟!، فكان هذا في هذا، وكان الأمر الآخر في الذي يعاهده، فينزله من حصنه، ثم ينكث عليه. الآية الأولى في هؤلاء القوم، وهي مبدؤه، والأخرى في هذا."}, "41479": {"num": 41479, "aya": 62, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر-: بـ {أن لهم الحسنى}، أي: الغِلْمان."}, "42030": {"num": 42030, "aya": 97, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {حياة طيبة}، قال: السعادة."}, "41993": {"num": 41993, "aya": 92, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {أن تكون أمة هي أربى من أمة}، قال: كانوا يُحالِفون الحلفاء، فيجدون أكثر منهم وأعزَّ، فينقضون حِلف هؤلاء، ويُحالفون هؤلاء الذين هم أعزُّ؛ فنُهُوا عن ذلك."}, "41996": {"num": 41996, "aya": 92, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "قال إسماعيل السُّدِّيّ: أن يكون قومٌ أكثرَ من قوم."}, "41997": {"num": 41997, "aya": 92, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {أن تكون أمة هي أربى من أمة}: هي أربى: أكثر؛ مِن أجل أن كان هؤلاء أكثر من أولئك نقضتم العهد فيما بينكم وبين هؤلاء؟! فكان هذا في هذا."}, "42031": {"num": 42031, "aya": 97, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {فلنحيينّه حياة طيبة}، قال: القنُوع. قال: وكان رسول الله صلى الله عليه وسلم يدعو: «اللهم، قَنِّعني بما رزقتني، وبارك لي فيه، واخلف عليَّ كلَّ غائبة لي بخير»."}, "41487": {"num": 41487, "aya": 62, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق أبي بشر جعفر بن أبي وحشية- في قوله: {وأنهم مفرطون}، قال: مَتْروكون في النار، مَنسيُّون فيها أبدًا."}, "41488": {"num": 41488, "aya": 62, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق الربيع، عن أبي بشر- {وأنهم مفرطون}، قال: مُخْسَؤون مُبْعَدون."}, "41492": {"num": 41492, "aya": 62, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق الحسين- {وأنهم مفرطون}، يقول: مُضاعون."}, "41493": {"num": 41493, "aya": 62, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {وأنهم مفرطون}، قال: قد فُرِطوا في النار، أي: مُعَجَّلون."}, "40988": {"num": 40988, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {وعلامات}، يعني: معالم الطرق بالنهار."}, "40989": {"num": 40989, "aya": 16, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- {وعلامات}، قال: هي الأعلام التي في السماء."}, "40990": {"num": 40990, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- في قوله: {وعلامات}، قال: منها ما يكون علامة."}, "40991": {"num": 40991, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر: أراد بالكل النجوم؛ منها ما يكون علامات، ومنها ما يهتدون به."}, "40992": {"num": 40992, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وعلامات}، قال: هي النجوم."}, "42035": {"num": 42035, "aya": 97, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن جريج- {فلنحيينه حياة طيبة}، قال: الآخرة، يحييهم حياة طيبة في الآخرة."}, "41832": {"num": 41832, "aya": 83, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- في قوله: {يعرفون نعمت الله ثم ينكرونها}، قال: هي المساكن، والأنعام، وما يُرْزَقون منها، والسرابيلُ مِن الحديد، والثياب؛ تَعرِفُ هذا كفارُ قريش، ثم تُنكِرُه بأن تقولَ: هذا كان لآبائِنا، فوَرَّثونا إيّاها."}, "40998": {"num": 40998, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {وبالنجم هم يهتدون}، يعني: بالليل."}, "40999": {"num": 40999, "aya": 16, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- {وبالنجم هم يهتدون}، قال: يهتدون به في البحر في أسفارهم."}, "41000": {"num": 41000, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- في قوله: {وبالنجم هم يهتدون}، قال: ومنها ما يُهتَدى به."}, "41001": {"num": 41001, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {وعلامات وبالنجم هم يهتدون}: والعلامات: النجوم، وإنّ الله تبارك وتعالى إنّما خلق هذه النجوم لثلاث خصلات: جعلها زينة للسماء، وجعلها يهتدي بها، وجعلها رجومًا للشياطين. فمن تعاطى فيها غير ذلك فَقَدَ رأيه، وأخطأ حظَّه، وأضاع نصيبه، وتكلَّف ما لا علم له به."}, "41833": {"num": 41833, "aya": 83, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر: يعني: نعمته التي قصَّ في هذه السورة."}, "42027": {"num": 42027, "aya": 97, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن علي بن أبي طالب -من طريق أبي خزيمة سليمان التمّار، عمَّن ذكره- في قوله: {فلنحيينّه حياة طيبة}، قال: القناعة."}, "42028": {"num": 42028, "aya": 97, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق أبي مالك، وأبي الربيع- أنّه سُئِل عن هذه الآية: {من عمل صالحًا من ذكر أو أنثى وهو مؤمن فَلَنُحيِيَنَّهُ حياة طيبة} الآية. قال: الحياة الطيبة: الرزق الحلال في هذه الحياة الدنيا."}, "41005": {"num": 41005, "aya": 16, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "أحكام متعلقة بالآية", "text": "عن إبراهيم النخعي: أنه كان لا يرى بأسًا أن يتعلَّمَ الرجل من النجوم ما يهتدي به."}, "41006": {"num": 41006, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "أحكام متعلقة بالآية", "text": "عن مجاهد بن جبر: أنه كان لا يرى بأسًا أن يتعلَّمَ الرجل منازل القمر."}, "41518": {"num": 41518, "aya": 67, "qail": "أبي رزين مسعود بن مالك الأسدي", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن أبي رَزِين [مسعود بن مالك الأسدي]-من طريق مغيرة- في الآية، قال: نزَل هذا وهم يَشرَبون الخمر قبلَ أن يَنزِلَ تحريمُها."}, "41519": {"num": 41519, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق همام، وعثمان- قال: نزلت قبل تحريم الخمر."}, "41520": {"num": 41520, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله:"}, "41522": {"num": 41522, "aya": 67, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "وعن سعيد بن جبير -من طريق سالم- ="}, "41523": {"num": 41523, "aya": 67, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "والحسن البصري -من طريق يونس- ="}, "41524": {"num": 41524, "aya": 67, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "وعامر الشعبي -من طريق مُغيرة- ="}, "41525": {"num": 41525, "aya": 67, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "وإبراهيم النخعي -من طريق مُغيرة- ="}, "41526": {"num": 41526, "aya": 67, "qail": "أبي رزين مسعود بن مالك الأسدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "وأبي رَزِين [مسعود بن مالك الأسدي]-من طريق مُغيرة-، مثله."}, "41527": {"num": 41527, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عمرو بن سفيان- أنّه سُئِل عن قوله: {تتخذون منه سكرًا ورزقًا حسنًا}. قال: السكر: ما حرم من ثمرتها. والرزقُ الحسنُ: ما حَلَّ مِن ثمرتها."}, "41528": {"num": 41528, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في الآية، قال: السَّكَرُ: الخَلُّ، والنبيذ، وما أشْبَهَه. والرزقُ الحسَنُ: التمرُ، والزبيبُ، وما أشْبَهَه."}, "41529": {"num": 41529, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، في الآية، قال: السَّكَرُ: الحرامُ منه. والرزقُ الحَسَنُ: زَبِيبُه، وخَلُّه، وعنبُه، ومنافعُه."}, "41530": {"num": 41530, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {تتخذون منه سكرًا ورزقًا حسنًا}، قال: فحَرَّم اللهُ بعدَ ذلك السَّكَرَ مع تحريم الخمر؛ لأنه منه، ثم قال: {ورزقًا حسنًا} فهو الحلالُ مِن الخَلِّ، والزبيبِ، والنبيذ، وأشْباهِ ذلك، فأقَرَّه اللهُ، وجعَله حلالًا للمسلمين."}, "41531": {"num": 41531, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {تتخذون منه سكرًا}، قال: إن الناسَ كانوا يُسَمُّون الخمرَ: سَكَرًا، وكانوا يشرَبونها، ثم سَمّاها اللهُ بعدَ ذلك: الخمرَ، حين حُرِّمَت. وكان ابن عباس يزعُمُ أن الحبشة يُسَمُّون الخلَّ: السَّكَرَ. وقوله: {ورزقًا حسنًا}، يعني: بذلك الحلالَ؛ التمرَ، والزبيبَ، وما كان حلالًا لا يُسْكِر."}, "42036": {"num": 42036, "aya": 97, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مزاحم -من طريق أبي روق- في قوله: {فلنحيينّه حياة طيبة}، قال: يأكل حلالًا، ويلبس حلالًا."}, "42037": {"num": 42037, "aya": 97, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مزاحم -من طريق عبيد بن سليمان- في قوله: {فلنحيينه حياة طيبة}، يقول: من عمل عملا صالحًا وهو مؤمن في فاقة أو ميسرة فحياته طيبة، ومن أعرض عن ذكر الله فلم يؤمن ولم يعمل صالحًا عيشته ضنكةٌ لا خير فيها."}, "41534": {"num": 41534, "aya": 67, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جبير -من طريق أبي حصين- قال: السَّكَرُ الحرامُ، والرزقُ الحسنُ الحلال."}, "41535": {"num": 41535, "aya": 67, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق أبي كدينة، عن ليث- قال: السَّكَرُ: الخمر. والرزق الحسن: الرطب، والأعناب."}, "41536": {"num": 41536, "aya": 67, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق مندل، عن ليث- {تتخذون منه سكرا ورزقا حسنا}، قال: ما كانوا يتخذون من النخل النبيذ، والرزق الحسن: ما كانوا يصنعون من الزبيب والتمر."}, "41537": {"num": 41537, "aya": 67, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن مجاهد- {تتخذون منه سكرا}، قال: هي الخمر قبل أن تحرم، {ورزقا حسنا} طعامًا."}, "42050": {"num": 42050, "aya": 97, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي مالك، وأبي الربيع- في قوله: {من عمل صالحًا من ذكر أو أنثى وهو مؤمن فَلَنُحيِيَنَّهُ حياة طيبة} الآية، قال: إذا صار إلى ربِّه جزاه بأحسن ما كان يعمل."}, "42040": {"num": 42040, "aya": 97, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق عوف- في قوله: {حياة طيبة}، قال: ما تطيب الحياة لأحد إلا في الجنة."}, "41540": {"num": 41540, "aya": 67, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال عامر الشعبي: السَّكَرُ: ما شربت. والرزق الحسن: ما أكلت."}, "41541": {"num": 41541, "aya": 67, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق عوف- في قوله: {تتخذون منه سكرًا}، قال: ذَكَر الله نعمته في السَّكَر قبل تحريم الخمر."}, "41542": {"num": 41542, "aya": 67, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق منصور، وعوف- قال: السَّكَرُ: ما حرم الله منه. والرزق: ما أحل الله منه."}, "41543": {"num": 41543, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ومن ثمرات النخيل والأعناب تتخذون منه سكرا ورزقا حسنا}: أما السكر: فخمور هذه الأعاجم. وأما الرزق الحسن: فما تنتبذون، وما تُخلِّلون، وما تأكلون. (9/ 71)"}, "42042": {"num": 42042, "aya": 97, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد-: قوله: {من عمل صالحا من ذكر أو أنثى وهو مؤمن فلنحيينه حياة طيبة}، فإن الله لا يشاء عملًا إلا في إخلاص، ويوجب لمن عمل ذلك في إيمان، قال الله تعالى: {فلنحيينه حياة طيبة}، وهي الجنة."}, "41547": {"num": 41547, "aya": 67, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {تتخذون منه سكرا ورزقا حسنا}، قال: الحلال: ما كان على وجه الحلال، حتى غيَّروها، فجعلوا منها سكرًا."}, "41553": {"num": 41553, "aya": 67, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "وسعيد بن جبير ="}, "41554": {"num": 41554, "aya": 67, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "ومجاهد بن جبر، قالوا: وهذا قبل تحريم الخمر."}, "41555": {"num": 41555, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "النسخ في الآية", "text": "عن عبد الله بن عباس، في الآية، قال: السَّكَرُ: النَّبيذُ. والرزقُ الحسنُ: الزَّبيبُ. فنسَخَتْها هذه الآية: {إنما الخمر والميسر} [المائدة: 90]."}, "41556": {"num": 41556, "aya": 67, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن إبراهيم النخعي ="}, "41557": {"num": 41557, "aya": 67, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "وعامر الشعبي -من طريق مغيرة- في قوله: {تتخذون منه سكرًا}، قالا: هي منسوخة."}, "41559": {"num": 41559, "aya": 67, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "وإبراهيم النخعي ="}, "41562": {"num": 41562, "aya": 67, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "تفسير مجاهد بن جبر -من طريق ابن مجاهد-: {سكرا} الخمر قبل تحريمها."}, "41563": {"num": 41563, "aya": 67, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {تتخذون منه سكرًا}، قال: خُمُورَ الأعاجم، ونُسِخت في سورة المائدة."}, "42074": {"num": 42074, "aya": 100, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {إنما سلطانه على الذين يتولّونه}، قال: حُجَّته."}, "42047": {"num": 42047, "aya": 97, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {من عمل صالحا من ذكر أو أنثى وهو مؤمن فلنحيينه حياة طيبة} قال: الحياة الطيبة في الآخرة هي الجنة، تلك الحياة الطيبة، قال: {ولنجزينهم أجرهم بأحسن ما كانوا يعملون} وقال: ألا تراه يقول: {يا ليتني قدمت لحياتي} [الفجر: 24]. قال: هذه آخرته. وقرأ أيضًا: {وإن الدار الآخرة لهي الحيوان} [العنكبوت: 64]. قال: الآخرة دار حياة لأهل النار وأهل الجنة، ليس فيها موت لأحد من الفريقين."}, "42075": {"num": 42075, "aya": 100, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- قوله: {إنما سلطانه على الذين يتولونه}، قال: يطيعونه."}, "42079": {"num": 42079, "aya": 100, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "", "text": "عن الربيع بن أنس -من طريق أبي جعفر- في الآية، قال: إنما سلطانه على قوم اتخذوه وليًّا، وأشركوه في أعمالهم."}, "42082": {"num": 42082, "aya": 100, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {والذين هم به مشركون}، قال: يعدلونه بربِّ العالمين."}, "42083": {"num": 42083, "aya": 100, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق عبيد بن سليمان- قال: في قوله: {والذين هم به مشركون} عدلوا إبليس بربهم، فإنهم بالله مشركون."}, "42085": {"num": 42085, "aya": 100, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "", "text": "عن الربيع بن أنس -من طريق أبي جعفر- في قوله: {والذين هم به مشركون}، قال: أشركوه في أعمالهم."}, "41582": {"num": 41582, "aya": 69, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {فاسلُكي سبل ربك ذللًا}، قال: طُرُقًا، لا يَتَوعَّرُ عليها مكانٌ سَلَكَتْه."}, "41583": {"num": 41583, "aya": 69, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {فاسلكي سبل ربك ذللًا}، قال: مُطِيعةً."}, "41072": {"num": 41072, "aya": 26, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {قد مكر الذين من قبلهم}، قال: هو نُمرُودُ بن كنعان حين بنى الصَّرح."}, "41076": {"num": 41076, "aya": 26, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {فأتى الله بنيانهم من القواعد}، قال: أتاها أمرُ الله مِن أصلها."}, "41589": {"num": 41589, "aya": 69, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {يخرج من بطونها شرابٌ مختلفٌ ألوانه"}, "41078": {"num": 41078, "aya": 26, "qail": "ابن أبي نجيح", "tabaqa": "تابع التابعين", "bab": "", "text": "عن ابن أبي نجيح -من طريق ورقاء، وغيره- {فأتى الله بنيانهم من القواعد}، قال: مكر نمرود بن كنعان الذي حاج إبراهيم في ربه."}, "41082": {"num": 41082, "aya": 26, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- قوله: {فخر عليهم السقف من فوقهم}، يقول: عذاب من السماء، لَمّا رَأَوْه استسلموا وذَلُّوا."}, "41083": {"num": 41083, "aya": 26, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {فَخَرَّ عليهم السقف من فوقهم}، والسقف: أعالي البيوت. فائْتَفَكَتْ بهم بيوتهم، فأهلكهم الله ودَمَّرهم."}, "41594": {"num": 41594, "aya": 69, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- {فيه شفاء للناس}، قال: في القرآن شفاء."}, "41595": {"num": 41595, "aya": 69, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {شراب مختلف ألوانه فيه شفاء للناس}، قال: هو العسلُ فيه الشِّفاءُ، وفي القرآن."}, "41597": {"num": 41597, "aya": 69, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {يخرج من بطونها شراب مختلف ألوانه، فيه شفاء للناس}: ففيه شفاء -كما قال الله تعالى- من الأدواء، وقد كان ينهى عن تغريق النحل، وعن قتلها."}, "42107": {"num": 42107, "aya": 103, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق مجاهد- قال: كان رسول الله صلى الله عليه وسلم يُعلِّمُ قَينًا بمكة اسمه: بَلعام، وكان أعجميَّ اللسان، فكان المشركون يرون رسول الله صلى الله عليه وسلم يدخل عليه ويخرج من عنده، فقالوا: إنما يُعَلِّمُه بَلعام. فأنزل الله: {ولقد نعلم أنهم يقولون إنما يعلمه بشر} الآية."}, "42108": {"num": 42108, "aya": 103, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق مجاهد- في قوله: {إنما يعلمه بشر}، قال: قالوا: إنما يعلِّم محمدًا عبدُ ابن الحضرميِّ، وهو صاحب الكتب. فأنزل الله: {لسان الذي يلحدون إليه أعجمي وهذا لسان عربي مبين}."}, "42111": {"num": 42111, "aya": 103, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ولقد نعلم أنهم يقولون إنما يعلمه بشر}، قال: قول قريش: إنما يعلِّم محمدًا عبدُ ابن الحضرمي، وهو صاحب كتب. فنزل: {لسان الذي يلحدون إليه أعجمي وهذا لسان عربي مبين}."}, "41602": {"num": 41602, "aya": 69, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن مسعود، قال: قال رسول الله صلى الله عليه وسلم: «عليكم بالشِّفاءَين: العسل، والقرآن»."}, "41603": {"num": 41603, "aya": 69, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن مسعود -من طريق الأسود- قال: عليكم بالشِّفاءَين: العسلِ، والقرآن."}, "41604": {"num": 41604, "aya": 69, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، عن النبيّ صلى الله عليه وسلم، قال: «الشفاءُ في ثلاثة: في شَرْطةِ مِحْجَمٍ، أو شَرْبةِ عسل، أو كَيَّةٍ بنار، وأنا أنهى أُمَّتي عن الكَيِّ»."}, "42116": {"num": 42116, "aya": 103, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ولقد نعلم أنهم يقولون إنما يعلمه بشر}: وقد قالت قريش: إنما يعلمه بشرٌ؛ عبدٌ لبني الحضرمي، يقال له: يعيش. قال الله تعالى: {لسان الذي يلحدون إليه أعجمي، وهذا لسان عربي مبين}، وكان يعيش يقرأ الكتب."}, "42117": {"num": 42117, "aya": 103, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة، قال: يقولون: إنما يعلِّم محمدًا عبدُ ابنِ الحضرمي. كان يُسمّى: مِقْيَس."}, "41609": {"num": 41609, "aya": 69, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن مسعود -من طريق أبي الأحوص- قال: إنّ العسلَ شفاءٌ مِن كلِّ داءٍ، والقرآن شفاءٌ لما في الصدور."}, "42122": {"num": 42122, "aya": 103, "qail": "محمد بن إسحاق", "tabaqa": "تابع التابعين", "bab": "نزول الآية", "text": "عن محمد بن إسحاق -من طريق سلمة- قال: كان رسول الله صلى الله عليه وسلم -فيما بلغني- كثيرًا ما يجلس عند المروة إلى غلام نصراني يُقال له: جبر؛ عبد لبني بياضة الحضرمي، فكانوا يقولون: واللهِ، ما يُعَلِّمُ محمدًا كثيرًا مما يأتي به إلا جبر النصراني غلام الحضرمي. فأنزل الله تعالى في قولهم: {ولقد نعلم أنهم يقولون إنما يعلمه بشر،"}, "42127": {"num": 42127, "aya": 103, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {لسان الذي يلحدون إليه أعجمي}: يتكلم بالرومية،"}, "42139": {"num": 42139, "aya": 106, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: لما أراد رسولُ الله صلى الله عليه وسلم أن يهاجر إلى المدينة قال لأصحابه: «تفرَّقوا عني، فمَن كانت به قوة فليتأخر إلى آخر الليل، ومَن لم تكن به قوة فليذهب في أول الليل، فإذا سمعتم بي قد استقرَّت بي الأرض فالحقوا بي». فأصبح بلالٌ المؤذن، وخبّاب، وعمّار، وجارية من قريش كانت أسلمت؛ فأصبحوا بمكة، فأخذهم المشركون وأبو جهل، فعرضوا على بلال أن يكفر، فأبى، فجعلوا يضعون دِرعًا مِن حديد في الشمس، ثم يُلبسونها إياه، فإذا ألبسوها إياه قال: أحد، أحد. وأَمّا خبّاب فجعلوا يَجُرُّونه في الشَّوْك، وأمّا عمار فقال لهم كلمة أعجبتهم تَقِيَّةً، وأما الجارية فوَتَّدَ لها أبو جهل أربعة أوتاد، ثم مَدَّها، فأدخل الحربة في قُبُلِها حتى قتلها، ثم خَلَّوا عن بلال وخباب وعمار، فلَحِقوا برسول الله صلى الله عليه وسلم، فأخبروه بالذي كان من أمرهم، واشتد على عمار الذي كان تكلَّم به، فقال له رسول الله صلى الله عليه وسلم: «كيف كان قلبك حين قلت الذي قلت، أكان منشرحًا بالذي قلت أم لا؟». قال: لا. قال: فأنزل الله: {إلا من أُكره وقلبه مطمئن بالإيمان}."}, "42147": {"num": 42147, "aya": 106, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "", "text": "عن أبي مالك غزوان الغفاري -من طريق حصين- في قوله: {إلا من أكره وقلبه مطمئن بالإيمان}، قال: نزلت في عمار بن ياسر."}, "42149": {"num": 42149, "aya": 106, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: ذُكِر لنا: أنّ هذه الآية: {إلا من أكره وقلبه مطمئن بالإيمان} نزلت في عمار بن ياسر، أخذه بنو المغيرة فغطّوه في بئر ميمون، وقالوا: اكفُرْ بمحمد. فتابعهم على ذلك وقلبه كاره؛ فنزلت."}, "41638": {"num": 41638, "aya": 72, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {والله جعل لكم من أنفسكم أزواجًا}، قال: خلق آدمَ، ثم خلَق زوجتَه منه."}, "41641": {"num": 41641, "aya": 72, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق زر بن حُبيش- في قوله: {بنين وحفدة}، قال: الحَفَدةُ: الأَخْتانُ."}, "41642": {"num": 41642, "aya": 72, "qail": "زر بن حبيش", "tabaqa": "تابعي", "bab": "", "text": "عن زر بن حبيش، قال: قال لي عبد الله بن مسعود: ما الحفدة، يا زر؟ قال: قلت: هم أحفاد الرجل مِن ولده، وولد ولده. قال: لا، هم الأصهار."}, "41643": {"num": 41643, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- قال: الحَفَدةُ: الأَصْهار."}, "41644": {"num": 41644, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- قال: الحَفَدةُ: الولدُ، وولدُ الولد."}, "41645": {"num": 41645, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد، وسعيد بن جبير- في هذه الآية: {بنين وحفدة}، قال: الحفدة: البنون."}, "41646": {"num": 41646, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: الحَفَدةُ: بنو البنين."}, "41647": {"num": 41647, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: أنّ نافع بن الأزرق قال له: أخبرني عن قوله عز وجل: {بنين وحفدة}. قال: ولدُ الولد، وهم الأَعْوانُ. قال: وهل تعرِفُ العربُ ذلك؟ قال: نعم، أما سمِعتَ الشاعرَ وهو يقولُ: حَفَدَ الوَلائِدُ حَوْلَهُنَّ وأُسْلِمَتْ … بأَكُفِّهِنَّ أزِمَّةُ الأَجْمالِ؟."}, "41648": {"num": 41648, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق جويبر، عن الضحاك بن مزاحم- أن نافع بن الأزرق قال له: أخبِرني عن قول الله عز وجل: {بنين وحفدة}، ما البنون والحفدة؟ قال: أما بنوك فإنهم يعاطونك، وأما حفدتك فإنهم خدمك. قال: وهل كانت العرب تعرف ذلك قبل أن ينزل الكتاب على محمد صلى الله عليه وسلم؟ قال: نعم، أما سمعت قول أمية بن أبي الصلت الثقفي: حَفَدَ الوَلائِدُ حَوْلَهُنَّ وأُلْقِيَت … بأَكُفِّهِنَّ أزِمَّةُ الأَجْمالِ؟."}, "42153": {"num": 42153, "aya": 106, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {من كفر بالله} الآية، قال: أخبر الله سبحانه أنّه مَن كفر بعد إيمانه فعليه غضب من الله وله عذاب عظيم، فأمّا من أُكره، فتكلَّم بلسانه، وخالفه قلبه بالإيمان لينجو بذلك من عدوِّه فلا حرج عليه؛ لأن الله سبحانه إنما يأخُذُ العباد بما عقدت عليه قلوبهم."}, "41650": {"num": 41650, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- قال: الحَفَدة: بنو امرأةِ الرجلِ ليسوا منه."}, "41651": {"num": 41651, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- قوله: {وجعل لكم من أزواجكم بنين وحفدة} … وقال: الحفدة: الرجل يعمل بين يدي الرجل، يقول: فلان يحفد لنا. ويزعم رجال: أنّ الحفدة: أختان الرجل."}, "41652": {"num": 41652, "aya": 72, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: الأختان."}, "41654": {"num": 41654, "aya": 72, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق مغيرة- قال: الحفدة: الخَتَنُ."}, "41655": {"num": 41655, "aya": 72, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق مغيرة- قال: الحفدة: هم الأصهار."}, "41656": {"num": 41656, "aya": 72, "qail": "أبي الضحى مسلم بن صبيح", "tabaqa": "تابعي", "bab": "", "text": "عن أبي الضُّحى مسلم بن صبيح -من طريق الأعمش- قال: الحفدة: الأختان."}, "41657": {"num": 41657, "aya": 72, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: الحفدة: الخَدَم."}, "41658": {"num": 41658, "aya": 72, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {بنين وحفدة}، قال: ابنه، وخادمه."}, "41659": {"num": 41659, "aya": 72, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قول الله تعالى: {بنين وحفدة}، قال: أنصارًا، وأعوانًا، وخدامًا."}, "41660": {"num": 41660, "aya": 72, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر: هم الأعوان؛ مَن أعانك فقد حفدك."}, "41667": {"num": 41667, "aya": 72, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "", "text": "عن أبي مالك غزوان الغفاري -من طريق السدي- قال: الحَفَدةُ: الأَعْوان."}, "41668": {"num": 41668, "aya": 72, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق منصور- قال: هم الخدم."}, "41669": {"num": 41669, "aya": 72, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي هلال الراسبي- قال: الحَفَدة: البنونَ، وبنو البنين، ومَن أعانَك مِن أهلٍ أو خادمٍ فقد حَفَدك."}, "41671": {"num": 41671, "aya": 72, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: {وجعل لكم من أزواجكم بنين وحفدة}، مَهَنَةً يمْهنُونك ويخدُمونك من ولدك، كرامة أكرمكم الله بها."}, "41674": {"num": 41674, "aya": 72, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وجعل لكم من أزواجكم بنين وحفدة}، قال: الحفدة: الخدم من ولد الرجل هم ولده، وهم يخدمونه، قال: وليس تكون العبيد من الأزواج، كيف يكون من زوجي عبد؟! إنما الحفدة: ولد الرجل، وخَدَمه."}, "41676": {"num": 41676, "aya": 72, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {أفبالباطل يؤمنون}، قال: بالشرك."}, "42193": {"num": 42193, "aya": 112, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {وضرب الله مثلًا قرية كانت ءامنة} الآية، قال: يعني: مكة."}, "42194": {"num": 42194, "aya": 112, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {قرية كانت ءامنة}، قال: مكة، ألا ترى إلى قوله: {ولقد جاءهم رسول منهم فكذبوه فأخذهم العذاب}؟."}, "42196": {"num": 42196, "aya": 112, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {قرية كانت ءامنة}، قال: هي مكة."}, "42199": {"num": 42199, "aya": 112, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وضرب الله مثلا قرية كانت ءامنة مطمئنة} إلى آخر الآية، قال: هذه مكة."}, "41691": {"num": 41691, "aya": 75, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق إبراهيم بن عكرمة بن يعلى بن أمية- قال: نزَلت هذه الآية: {ضرب الله مثلًا عبدًا مملوكًا لا يقدر على شيء} في رجلٍ من قريش وعبدِه؛ في هشام بن عمرو، وهو الذي ينفق مالَه سِرًّا وجهرًا، وفي عبدِه أبي الجوزاء الذي كان يَنْهاه."}, "42204": {"num": 42204, "aya": 112, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، في قوله: {فأذاقها الله لباس الجوع والخوف}، قال: فأخذهم الله بالجوع، والخوف، والقتل."}, "41693": {"num": 41693, "aya": 75, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {ضرب الله مثلًا عبدًا مملوكًا لا يقدر على شيء} يعني: الكافر، أنّه لا يستطيع أن يُنفِقَ نفقةً في سبيل الله، {ومن رزقناه منا رزقًا حسنًا} يعني: المؤمن."}, "41694": {"num": 41694, "aya": 75, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق ابن جريج- في قوله: {ضرب الله مثلًا عبدًا مملوكًا لا يقدر على شيء}، قال: يعني بذلك: الآلهةَ التي لا تَمْلِكُ ضَرًّا ولا نفعًا، ولا تَقْدِرُ على شيءٍ يَنفَعُها."}, "41695": {"num": 41695, "aya": 75, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ضرب الله مثلًا عبدًا مملوكًا لا يقدر على شيء ومَن رزقناه منا رزقًا حسنًا} و {رجُلين أحَدُهُما أبكم}، {ومن يأمُر بالعدل}، قال: كلُّ هذا مَثَلُ إلهِ الحق، وما يَدْعُون مِن دونِه الباطل."}, "41703": {"num": 41703, "aya": 75, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {فهو ينفق منه سرًا وجهرًا}: وهذا المثلُ في النفقة."}, "41704": {"num": 41704, "aya": 75, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق ابن جريج- في قوله: {فهو ينفق منه سرًا وجهرًا}، قال: علانية. الذي يُنفِقُ سرًّا وجهرًا اللهُ."}, "41706": {"num": 41706, "aya": 75, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال الله: {هل يستويان مثلًا} [هود: 24]، قال: لا، واللهِ، ما يستويان."}, "41711": {"num": 41711, "aya": 75, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "من أحكام الآية", "text": "عن عبد الله بن عباس، قال: ليس للعبد طلاقٌ إلا بإذن سَيِّدِه. وقرأ: {عبدًا مملوكًا لا يقدر على شيء}."}, "41712": {"num": 41712, "aya": 75, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "من أحكام الآية", "text": "عن عبد الله بن عباس -من طريق عطاء- أنّه سُئِل عن المملوك يتصدَّقُ بشيء. فقال: {ضرب الله مثلًا عبدًا مملوكًا لا يقدر على شيء}: لا يَتَصَدَّقُ بشيء."}, "41720": {"num": 41720, "aya": 76, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق جويبر- {وضرب الله مثلا"}, "41215": {"num": 41215, "aya": 41, "qail": "داود بن أبي هند", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن داود بن أبي هند -من طريق جعفر بن سليمان- قال: نزلت: {والذين هاجروا في الله من بعد ما ظُلِمُوا} إلى قوله: {وعلى ربهم يتوكلون} في أبي جندل بن سُهيل."}, "41217": {"num": 41217, "aya": 41, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {والذين هاجروا في الله"}, "41218": {"num": 41218, "aya": 41, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {والذين هاجروا في الله من بعد ما ظلموا}، قال: هؤلاء أصحاب محمد صلى الله عليه وسلم، ظَلَمهم أهلُ مكة، فأخرجوهم من ديارهم، حتى لَحِق طوائف منهم بأرض الحبشة، ثم بَوَّأهم الله المدينة بعد ذلك، فجعلها لهم دار هجرة، وجعل لهم أنصارًا من المؤمنين."}, "41222": {"num": 41222, "aya": 41, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي-: ظَلَمَهُمُ المشركون."}, "41738": {"num": 41738, "aya": 76, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي-: وبقوله: {ومن يأمر بالعدل} المؤمن. وهذا المَثَلُ في الأعمال."}, "41227": {"num": 41227, "aya": 41, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {لنبوّئنّهم في الدنيا حسنة}، قال: لنرزُقَنَّهم في الدنيا رزقًا حسنًا."}, "41228": {"num": 41228, "aya": 41, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي -من طريق داود بن أبي هند- في قوله: {لنبوّئنّهم في الدنيا حسنة}، قال: المدينة."}, "41740": {"num": 41740, "aya": 76, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {هل يستوي هو ومن يأمر بالعدل}، قال: الله يأمر بالعدل."}, "41230": {"num": 41230, "aya": 41, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "تفسير قتادة بن دعامة: قال: {لنبوئنهم في الدنيا حسنة} المدينة منزِلًا."}, "41739": {"num": 41739, "aya": 76, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {هل يستوي هو ومن يأمر بالعدل وهو على صراط مستقيم}، يعني: نفسَه."}, "41232": {"num": 41232, "aya": 41, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {ولأجر الآخرة أكبر}، قال: إي والله، لَما يُثِيبُهم عليه من جنته ونعمته أكبر، {لو كانوا يعلمون}."}, "42038": {"num": 42038, "aya": 97, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق أبي سعيد- في قوله: {فلنحيينّه حياة طيبة}، قال: الحياة الطيبة: القناعة."}, "42039": {"num": 42039, "aya": 97, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق أبي مسلم عبد الرحمن بن حيان- في قوله: {فلنحيينّه حياة طيبة}، قال: لنرزقنَّه قناعة يجِدُ لذَّتها في قلبه."}, "40758": {"num": 40758, "aya": 1, "qail": "أبي بكر بن حفص", "tabaqa": "", "bab": "نزول الآية", "text": "عن أبي بكر بن حفص -من طريق إسماعيل- قال: لما نزلت: {أتى أمر الله} قاموا، فنزلت: {فلا تستعجلوه}."}, "40763": {"num": 40763, "aya": 1, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مزاحم -من طريق جويبر- في قوله: {أتى أمر الله}، قال: الأحكام، والحدود، والفرائض."}, "40767": {"num": 40767, "aya": 1, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الملك ابن جريج -من طريق حجاج- قال: لما نزلت هذه الآية: {أتى أمر الله فلا تستعجلوه} قال رجال من المنافقين بعضهم لبعض: إن هذا يزعم أن أمر الله قد أتى؛ فأمسِكوا عن بعض ما كنتم تعملون حتى تنظُروا ما هو كائن. فلما رأوا أنه لا ينزل شيءٌ قالوا: ما نراه نزل شيء. فنزلت {اقترب للناس حسابهم} الآية [الأنبياء: 1]. فقالوا: إن هذا يزعُمُ مثلَها أيضًا. فلما رأوا أنه لا ينزل شيء قالوا: ما نراه نزل شيء. فنزلت: {ولئن أخرنا عنهم العذاب إلى أُمة معدودة} الآية [هود: 8]."}, "40773": {"num": 40773, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ينزل الملائكة بالروح من أمره}، قال: إنّه لا ينزل ملك إلا ومعه روح، كالحفيظ عليه، لا يتكلم ولا يراه ملك ولا شيء مما خلق الله."}, "40774": {"num": 40774, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- قوله: {ينزل الملائكة بالروح من أمره}، قال: لا ينزل ملك إلا معه روح، {ينزل الملائكة بالروح من أمره على من يشاء من عباده} قال: بالنبوة. ="}, "42312": {"num": 42312, "aya": 126, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، قال: قال رسول الله صلى الله عليه وسلم يوم قُتل حمزة ومُثِّل به: «لئِن ظَفِرْتُ بقريش لأُمثِّلَّن بسبعين رجلًا منهم». فأنزل الله: {وإن عاقبتم} الآية. فقال رسول الله صلى الله عليه وسلم: «بل نصبر، يا ربِّ». فصبر، ونهى عن المُثْلَة."}, "42317": {"num": 42317, "aya": 126, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "النسخ في الآية", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {وإن عاقبتم فعاقبوا بمثل ما عوقبتم به}، قال: هذا حين أمر الله نبيَّه أن يقاتل من قاتله، ثم نزلت براءة وانسلاخ الأشهر الحُرم. قال: فهذا من المنسوخ."}, "42318": {"num": 42318, "aya": 126, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "قال إبراهيم النخعي ="}, "42319": {"num": 42319, "aya": 126, "qail": "محمد بن سيرين", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "ومحمد بن سيرين ="}, "42322": {"num": 42322, "aya": 126, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "النسخ في الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- قال: كانوا قد أُمِروا بالصفح عن المشركين، فأسلم رجال [ذوو] مَنَعة، فقالوا: يا رسول الله، لو أذِن اللهُ لنا لانتصرنا من هؤلاء الكلاب. فنزلت هذه الآية، ثم نُسِخ ذلك بالجهاد."}, "42323": {"num": 42323, "aya": 126, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إبراهيم النخعي -من طريق منصور- قال: إن أخذ منك شيئًا فخُذْ منه مثله."}, "42324": {"num": 42324, "aya": 126, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وإن عاقبتم فعاقبوا بمثل ما عوقبتم به}، قال: لا تعتدوا، يعني: محمدًا صلى الله عليه وسلم وأصحابه."}, "42325": {"num": 42325, "aya": 126, "qail": "محمد بن سيرين", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن محمد بن سيرين -من طريق خالد- في قوله: {وإن عاقبتم فعاقبوا بمثل ما عوقبتم به}، قال: إن أخَذ منك رجلٌ شيئًا فخُذ منه مثله."}, "41831": {"num": 41831, "aya": 83, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر: أنّ أعرابيًّا أتى النبيَّ صلى الله عليه وسلم، فسأَله، فقرَأ عليه رسول الله صلى الله عليه وسلم: {والله جعل لكم من بيوتكم سكنًا}. قال الأعرابي: نعم. {وجعل لكم من جلود الأنعام بيوتًا تستخفونها}. قال الأعرابي: نعم. ثم قرَأ عليه، كلَّ ذلك يقول: نعم. حتى بلَغ: {كذلك يتم نعمته عليكم لعلكم تسلمون}. فوَلّى الأعرابي؛ فأنزَل الله: {يعرفون نعمت الله ثم ينكرونها وأكثرهم الكافرون}."}, "41320": {"num": 41320, "aya": 48, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {يتفيّؤا ظلاله}، قال: تتميَّل."}, "41321": {"num": 41321, "aya": 48, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: «تَتَفَيَّأُ ظِلالُهُ»: تتهيأ."}, "41322": {"num": 41322, "aya": 48, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- قوله: {أولم يروا إلى ما خلق الله من شيء يتفيأ ظلاله}: ما خلق من شيء عن يمينه وشمائله -فلفظ {ما} لفظ عن اليمين والشمائل- قال: ألم تر أنك إذا صليت الفجر كان ما بين مطلع الشمس إلى مغربها ظلًّا؟ ثم بعث الله عليه الشمس دليلًا، وقبض الله الظل."}, "41323": {"num": 41323, "aya": 48, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- في الآية، قال: فَيْءُ كلِّ شيء ظِلُّه، وسجود كلِّ شيء فيئُه؛ سجود الجبال فيئُها."}, "41324": {"num": 41324, "aya": 48, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- في الآية، قال: إذا زالت الشمس سجد كلُّ شيء لله."}, "41325": {"num": 41325, "aya": 48, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {يتفيّؤا ظلاله عن اليمين والشّمآئل}، قال: الغدوّ والآصال، إذا فاء ظلُّ كلِّ شيء، أما الظِّلُّ بالغداة فعن اليمين، وأما بالعَشِيِّ فعن الشمائل، إذا كان بالغداة سجدت لله، وإذا كان بالعَشِيّ سجدت له."}, "41326": {"num": 41326, "aya": 48, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق ثابت- في قوله: {أو لم يروا إلى ما خلق الله من شيء يتفيّؤا ظلاله}، قال: إذا فاء الفيء توجَّه كلُّ شيء ساجدًا لله قِبَلَ القبلة من بيت أو شجر. قال: فكانوا يستحِبُّون الصلاة عند ذلك."}, "41327": {"num": 41327, "aya": 48, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق ثابت- في الآية، قال: إذا فاء الفيء لم يبق شيءٌ مِن دابة ولا طائر إلا خَرَّ لله ساجدًا."}, "41328": {"num": 41328, "aya": 48, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق عبيد بن سليمان- في قوله: {يتفيؤ ظلاله عن اليمين والشمائل}، قال: يعني بالغدو والآصال: تسجد الظلال لله غدوة إلى أن يفيء الظل، ثم تسجد لله إلى الليل، يعني: ظل كل شيء."}, "41329": {"num": 41329, "aya": 48, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم، في قوله عز وجل: {عن اليمين والشمائل سجدا لله}، قال: أما اليمين: فأول النهار، والشمال: آخر النهار، تسجد الظلال لله."}, "41837": {"num": 41837, "aya": 83, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق سفيان- في قوله: {يعرفون نعمت الله ثم ينكرونها}، قال: محمد صلى الله عليه وسلم."}, "41838": {"num": 41838, "aya": 83, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ، في قوله: {يعرفون نعمت الله ثم ينكرونها}، قال: هذا في حديث أبي جهل، والأَخْنس؛ حينَ سأل الأخنسُ أبا جهلٍ عن محمد صلى الله عليه وسلم. فقال: هو نبي."}, "41835": {"num": 41835, "aya": 83, "qail": "عون بن عبد الله الهذلي", "tabaqa": "تابعي", "bab": "", "text": "عن عون بن عبد الله الهذلي -من طريق ليث- في قوله: {يعرفون نعمة الله ثم ينكرونها}، قال: إنكارُهم إيّاها: أن يقولَ الرجلُ: لولا فلانٌ أصابني كذا وكذا، ولولا فلانٌ لم أُصِبْ كذا وكذا."}, "41839": {"num": 41839, "aya": 83, "qail": "محمد بن السائب الكلبي", "tabaqa": "تابع التابعين", "bab": "", "text": "قال محمد بن السائب الكلبي: هو أنّه لما ذكر لهم هذه النعم قالوا: نَعَمْ، هذه كلها من الله، ولكنها بشفاعة آلهتنا."}, "41339": {"num": 41339, "aya": 48, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وهم داخرون}، قال: صاغرون."}, "41340": {"num": 41340, "aya": 48, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق ثابت- {يتفيؤ ظلاله}، قال: سجد ظل المؤمن طوعًا، وظل الكافر كرهًا."}, "41363": {"num": 41363, "aya": 52, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- في قوله: {وله الدّين"}, "41366": {"num": 41366, "aya": 52, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي نضرة- في قوله: {وله الدّين واصِبًا}، قال: دائمًا."}, "41367": {"num": 41367, "aya": 52, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {وله الدّين واصِبًا}، قال: واجبًا."}, "41368": {"num": 41368, "aya": 52, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، أن نافع بن الأزرق قال له: أخبِرني عن قوله: {وله الدّين واصِبًا}، ما الواصِب؟ قال: الدائم، قال فيه أُمَيَّة بن أبي الصَّلت: وله الدّين واصبًا وله الملـ … ـك وحَمْدٌ له على كلّ حال."}, "41369": {"num": 41369, "aya": 52, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- في قوله: {واصِبًا}: دائمًا."}, "41370": {"num": 41370, "aya": 52, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق جويبر- {وله الدين واصبا}، قال: دائمًا."}, "41374": {"num": 41374, "aya": 52, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وله الدين واصبا}، أي: دائمًا؛ فإنّ الله تبارك وتعالى لم يدع شيئًا مِن خلقه إلا عبده، طائعًا أو كارهًا."}, "41375": {"num": 41375, "aya": 52, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {واصبا}، قال: دائمًا، ألا ترى أنه يقول: {عذاب واصب} [الصافات: 9]، أي: دائم."}, "41378": {"num": 41378, "aya": 52, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وله الدين واصبا}، قال: دائمًا، والواصِب: الدائم."}, "41385": {"num": 41385, "aya": 53, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {فإليه تجأرون}، قال: تتضرَّعون دعاء."}, "41386": {"num": 41386, "aya": 53, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر: {تجأرون}: تصرخون."}, "41952": {"num": 41952, "aya": 91, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "قال مجاهد بن جبر ="}, "41953": {"num": 41953, "aya": 91, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "وقتادة بن دعامة: نزلت في حِلف أهل الجاهلية."}, "41955": {"num": 41955, "aya": 91, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب-: هؤلاء قوم كانوا حلفاء لقوم تحالفوا، وأعطى بعضُهم العهد، فجاءهم قوم، فقالوا: نحن أكثر وأعزُّ وأمنع؛ فانقضوا عهد هؤلاء، وارجعوا إلينا. ففعلوا، فذلك قول الله تعالى: {ولا تنقضوا الأيمان بعد توكيدها وقد جعلتم الله عليكم كفيلا}."}, "41957": {"num": 41957, "aya": 91, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ولا تنقضوا الأيمان بعد توكيدها}، قال: تغليظها في الحِلْف."}, "42023": {"num": 42023, "aya": 97, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن أبي صالح باذام -من طريق إسماعيل- قال: جلس ناسٌ مِن أهل الأوثان، وأهل التوراة، وأهل الإنجيل، فقال هؤلاء: نحن أفضل. وقال هؤلاء: نحن أفضل. فأنزل الله تعالى: {من عمل صالحا من ذكر أو أنثى وهو مؤمن، فلنحيينه حياة طيبة، ولنجزينهم أجرهم بأحسن ما كانوا يعملون}."}, "41960": {"num": 41960, "aya": 91, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {ولا تنقضوا الأيمان بعد توكيدها}، يقول: بعد تشديدها وتغليظها."}, "41961": {"num": 41961, "aya": 91, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: بعد تشديدها وتغليظها."}, "41967": {"num": 41967, "aya": 91, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- في قوله: {وقد جعلتم الله عليكم كفيلًا}، قال: وكيلًا."}, "42025": {"num": 42025, "aya": 97, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الربيع بن أنس -من طريق أبي جعفر- في قوله: {من عمل صالحا من ذكر أو أنثى وهو مؤمن}، قال: الإيمان: الإخلاص لله وحده. فبيَّن أنه لا يقبل عملًا إلا بالإخلاص له."}, "40948": {"num": 40948, "aya": 14, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق يزيد بن إبراهيم- {وترى الفلك مواخر فيه}، قال: مقبلة ومدبرة بريح واحدة."}, "40949": {"num": 40949, "aya": 14, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق يونس- في قوله: {وترى الفلك مواخر فيه}، قال: المواقِرُ."}, "41974": {"num": 41974, "aya": 92, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن إسماعيل السُّدِّيّ -من طريق ابن عيينة، عن صدقة بن عبد الله بن كثير المكي- في قوله: {ولا تكونوا كالتي نقضت غزلها}، قال: كانت امرأةٌ بمكة، كانت تُسَمّى: خرقاء مكة، كانت تغزل، فإذا أبرمت غزلها نقضته."}, "41979": {"num": 41979, "aya": 92, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ولا تكونوا كالتي نقضت غزلها}، قال: نقضت حبلها بعد إبرامِها إيّاه."}}, "n_athar": {"0": 15, "1": 17, "2": 22, "3": 4, "4": 4, "5": 18, "6": 9, "7": 14, "8": 31, "9": 26, "10": 13, "11": 8, "12": 5, "13": 6, "14": 31, "15": 26, "16": 20, "17": 8, "18": 3, "19": 2, "20": 6, "21": 4, "22": 11, "23": 12, "24": 8, "25": 10, "26": 18, "27": 13, "28": 13, "29": 2, "30": 21, "31": 3, "32": 9, "33": 14, "34": 5, "35": 6, "36": 10, "37": 8, "38": 11, "39": 5, "40": 3, "41": 24, "42": 2, "43": 24, "44": 20, "45": 6, "46": 11, "47": 19, "48": 25, "49": 8, "50": 2, "51": 8, "52": 19, "53": 9, "54": 3, "55": 5, "56": 10, "57": 9, "58": 11, "59": 12, "60": 10, "61": 17, "62": 30, "63": 6, "64": 5, "65": 4, "66": 6, "67": 50, "68": 13, "69": 29, "70": 14, "71": 14, "72": 43, "73": 3, "74": 7, "75": 22, "76": 35, "77": 9, "78": 6, "79": 9, "80": 34, "81": 23, "82": 2, "83": 13, "84": 6, "85": 5, "86": 9, "87": 6, "88": 17, "89": 21, "90": 44, "91": 19, "92": 34, "93": 3, "94": 5, "95": 5, "96": 4, "97": 34, "98": 10, "99": 7, "100": 15, "101": 10, "102": 8, "103": 26, "104": 2, "105": 5, "106": 20, "107": 2, "108": 1, "109": 2, "110": 22, "111": 4, "112": 17, "113": 9, "114": 3, "115": 4, "116": 8, "117": 2, "118": 8, "119": 9, "120": 19, "121": 4, "122": 6, "123": 3, "124": 13, "125": 15, "126": 21, "127": 7, "128": 5}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});